export const MATH_HTML: string = "<!doctype html>\n<html lang=\"fr\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1, viewport-fit=cover\">\n<title>Atelier Maths SN4 | e-formation.net</title>\n<meta name=\"robots\" content=\"noindex\">\n<link rel=\"stylesheet\" href=\"https://fonts.googleapis.com/css2?family=Bricolage+Grotesque:opsz,wght@12..96,600;12..96,800&family=Instrument+Sans:wght@400;500;600&family=STIX+Two+Text:ital,wght@0,400;0,600;1,400&display=swap\">\n<style>\n/* Concept : cahier quadrillé. Papier à carreaux, encre indigo, surligneur jaune pour l'essentiel. */\n:root{\n  --bg:#f2f3fa; --paper:#fcfcff; --grid:rgba(75,50,195,.08);\n  --ink:#1c1a35; --muted:#5b5877; --line:#d9d7ea;\n  --accent:#4b32c3; --accent-ink:#ffffff; --accent-soft:#ebe8fb;\n  --hi:#ffe27a; --ok:#0b7a55; --ok-soft:#dcf5ea; --bad:#b42318; --bad-soft:#fde8e6;\n  --f-display:'Bricolage Grotesque',system-ui,sans-serif;\n  --f-body:'Instrument Sans',system-ui,-apple-system,sans-serif;\n  --f-math:'STIX Two Text','Cambria Math',Georgia,serif;\n}\n@media (prefers-color-scheme: dark){:root:not([data-theme=\"light\"]){\n  --bg:#13122a; --paper:#1b1a38; --grid:rgba(150,135,255,.08);\n  --ink:#ecebfa; --muted:#a8a5c9; --line:#33315e;\n  --accent:#a496ff; --accent-ink:#17142e; --accent-soft:#2a2756;\n  --hi:#5b4b00; --ok:#56d6a6; --ok-soft:#133a30; --bad:#ff9087; --bad-soft:#41201f; color-scheme:dark}}\n:root[data-theme=\"dark\"]{\n  --bg:#13122a; --paper:#1b1a38; --grid:rgba(150,135,255,.08);\n  --ink:#ecebfa; --muted:#a8a5c9; --line:#33315e;\n  --accent:#a496ff; --accent-ink:#17142e; --accent-soft:#2a2756;\n  --hi:#5b4b00; --ok:#56d6a6; --ok-soft:#133a30; --bad:#ff9087; --bad-soft:#41201f; color-scheme:dark}\n\n*{box-sizing:border-box}\nbody{margin:0;background-color:var(--bg);color:var(--ink);font:16px/1.6 var(--f-body);\n  background-image:linear-gradient(var(--grid) 1px,transparent 1px),linear-gradient(90deg,var(--grid) 1px,transparent 1px);\n  background-size:24px 24px;\n  padding-left:max(16px,env(safe-area-inset-left,0px));padding-right:max(16px,env(safe-area-inset-right,0px));padding-block:0 48px}\nbody::before{content:\"\";position:fixed;inset:0 0 auto;height:env(safe-area-inset-top,0px);z-index:30;background:var(--paper)}\n.wrap{max-width:960px;margin:0 auto}\na{color:var(--accent)}\nh1,h2,h3{font-family:var(--f-display);line-height:1.15;margin:0;text-wrap:balance}\nh1{font-size:clamp(2rem,6vw,3.2rem);font-weight:800;letter-spacing:-.02em}\nh2{font-size:1.35rem;font-weight:800}\nh3{font-size:1.08rem;font-weight:600}\np{margin:0 0 .8em}\n.eyebrow{font-size:.78rem;letter-spacing:.12em;text-transform:uppercase;color:var(--muted);font-weight:600;margin:0 0 .6rem}\n.muted{color:var(--muted)}\nsup,sub{font-size:.7em;line-height:0}\n.fr{display:inline-flex;flex-direction:column;align-items:center;vertical-align:middle;line-height:1.15;margin:0 .15em;font-family:var(--f-math)}\n.fr>span:first-child{border-bottom:1.5px solid currentColor;padding:0 .25em}\n.fr>span:last-child{padding:0 .25em}\n.rad{font-family:var(--f-math)}\n.rc{border-top:1.5px solid currentColor;padding:0 .12em;margin-left:1px}\n.m{font-family:var(--f-math);font-size:1.08em}\n\n/* header */\n.top{position:sticky;top:env(safe-area-inset-top,0px);z-index:20;background:var(--paper);border-bottom:1px solid var(--line);\n  margin-inline:calc(-1*max(16px,env(safe-area-inset-left,0px))) calc(-1*max(16px,env(safe-area-inset-right,0px)));\n  padding-inline:max(16px,env(safe-area-inset-left,0px)) max(16px,env(safe-area-inset-right,0px))}\n.top .wrap{display:flex;align-items:center;gap:1rem;flex-wrap:wrap;padding-block:.6rem}\n.brand{font-family:var(--f-display);font-weight:800;text-decoration:none;color:var(--ink);font-size:1.1rem;margin-right:auto}\n.brand b{background:var(--hi);padding:0 .3em;border-radius:3px}\nnav{display:flex;gap:.25rem;flex-wrap:wrap}\nnav a{padding:.4rem .8rem;border-radius:999px;text-decoration:none;color:var(--muted);font-weight:600;font-size:.92rem}\nnav a:hover{color:var(--ink)}\nnav a[aria-current=\"page\"]{background:var(--accent);color:var(--accent-ink)}\na:focus-visible,button:focus-visible,input:focus-visible,select:focus-visible{outline:3px solid var(--accent);outline-offset:2px}\n\nmain{padding-top:2rem}\n.intro{display:grid;gap:.9rem;margin-bottom:2rem}\n.intro p.lead{font-size:1.12rem;max-width:60ch;color:var(--muted)}\n.intro h1 mark{background:var(--hi);color:inherit;padding:0 .12em;border-radius:4px}\n.summary{display:flex;gap:1.5rem;flex-wrap:wrap;font-weight:600}\n.summary span b{font-family:var(--f-display);font-size:1.5rem;margin-right:.3rem}\n\n.list{display:grid;gap:.75rem;margin:0 0 2.2rem;padding:0;list-style:none}\n.row{display:grid;grid-template-columns:auto minmax(0,1fr) auto;gap:1rem;align-items:center;background:var(--paper);border:1px solid var(--line);border-radius:12px;padding:1rem 1.1rem}\n.num{font-family:var(--f-display);font-weight:800;font-size:1.7rem;color:var(--accent);min-width:2ch;text-align:center}\n.row p{margin:.15rem 0 .5rem;color:var(--muted);font-size:.92rem}\n.bar{height:6px;background:var(--accent-soft);border-radius:99px;overflow:hidden;max-width:320px}\n.bar i{display:block;height:100%;background:var(--accent);border-radius:99px}\n.best{font-size:.8rem;color:var(--muted);margin-top:.3rem}\n.acts{display:flex;gap:.5rem;flex-wrap:wrap}\n.btn,.btn-s{font:600 .95rem var(--f-body);padding:.6rem 1.1rem;border-radius:10px;text-decoration:none;cursor:pointer;border:1.5px solid var(--accent);display:inline-block}\n.btn{background:var(--accent);color:var(--accent-ink)}\n.btn:hover{filter:brightness(1.08)}\n.btn-s{background:transparent;color:var(--accent)}\n.btn-s:hover{background:var(--accent-soft)}\nbutton:disabled{opacity:.45;cursor:not-allowed}\n@media (max-width:620px){.row{grid-template-columns:auto minmax(0,1fr)}.acts{grid-column:1/-1}}\n\n.two{display:grid;grid-template-columns:repeat(auto-fit,minmax(260px,1fr));gap:1rem;margin-bottom:2.2rem}\n.panel{background:var(--paper);border:1px solid var(--line);border-radius:12px;padding:1.2rem 1.3rem;min-width:0}\n.panel h2{margin-bottom:.4rem}\n.hist{list-style:none;margin:0;padding:0;display:grid;gap:.4rem;font-size:.93rem}\n.hist li{display:flex;justify-content:space-between;gap:1rem;border-bottom:1px dashed var(--line);padding-bottom:.35rem}\n\n/* chapter */\n.crumb{display:flex;justify-content:space-between;gap:1rem;flex-wrap:wrap;font-size:.9rem;margin-bottom:1rem}\n.tabs{display:flex;gap:.4rem;margin:1rem 0 1.5rem}\n.tabs a{padding:.5rem 1rem;border-radius:10px;text-decoration:none;font-weight:600;border:1.5px solid var(--line);color:var(--muted);background:var(--paper)}\n.tabs a[aria-current=\"page\"]{border-color:var(--accent);color:var(--accent);background:var(--accent-soft)}\n.sec{background:var(--paper);border:1px solid var(--line);border-radius:12px;padding:1.2rem 1.4rem;margin-bottom:1rem}\n.sec h2{margin-bottom:.7rem}\n.sec ul{margin:0 0 .8em;padding-left:1.2em}\n.sec li{margin:.25em 0}\n.formula{font-family:var(--f-math);font-size:1.12rem;background:var(--accent-soft);border-left:4px solid var(--accent);padding:.7rem 1rem;border-radius:0 8px 8px 0;margin:.7rem 0;display:grid;gap:.3rem}\n.ex{border:1.5px dashed var(--line);border-radius:10px;padding:.7rem 1rem;margin:.8rem 0}\n.ex>b:first-child{background:var(--hi);padding:0 .35em;border-radius:3px;margin-right:.4rem;color:inherit}\n.tip{font-size:.95rem;color:var(--muted)}\n.cta{margin:1.5rem 0;display:flex;gap:.6rem;flex-wrap:wrap}\n\n/* explorer */\n.xp{display:grid;grid-template-columns:minmax(0,300px) minmax(0,1fr);gap:1.2rem;align-items:start}\n@media (max-width:640px){.xp{grid-template-columns:1fr}}\n.xp label{display:grid;grid-template-columns:2.2ch 1fr 5ch;gap:.6rem;align-items:center;margin:.4rem 0;font-family:var(--f-math);font-size:1.05rem}\n.xp input[type=range]{width:100%;accent-color:var(--accent)}\n.xp svg{width:100%;max-width:384px;height:auto;display:block;border:1px solid var(--line);border-radius:8px;background:var(--paper)}\n.readout{font-family:var(--f-math);display:grid;gap:.2rem;margin-top:.6rem;font-size:1.02rem}\n.gridl{stroke:var(--line);stroke-width:1}\n.axis{stroke:var(--muted);stroke-width:1.5}\n.curve{fill:none;stroke:var(--accent);stroke-width:2.5}\n.pt{fill:var(--bad)}\n.pz{fill:var(--ok)}\n.svgt{fill:var(--muted);font:10px var(--f-body)}\n\n/* quiz */\n.qhead{display:flex;justify-content:space-between;align-items:center;gap:1rem;flex-wrap:wrap;margin-bottom:.6rem}\n.timer{font-family:var(--f-display);font-weight:800;font-size:1.3rem;font-variant-numeric:tabular-nums;padding:.2rem .7rem;border-radius:8px;background:var(--accent-soft)}\n.timer.low{background:var(--bad-soft);color:var(--bad)}\n.qbar{height:8px;background:var(--accent-soft);border-radius:99px;overflow:hidden;margin-bottom:1.2rem}\n.qbar i{display:block;height:100%;background:var(--accent);transition:width .25s}\n.qlayout{display:grid;grid-template-columns:minmax(0,1fr) 190px;gap:1.2rem;align-items:start}\n@media (max-width:760px){.qlayout{grid-template-columns:1fr}}\n.qlayout.solo{grid-template-columns:minmax(0,1fr)}\n.qcard{background:var(--paper);border:1px solid var(--line);border-radius:12px;padding:1.3rem}\n.qtag{font-size:.8rem;color:var(--muted);margin-bottom:.5rem}\n.qtext{font-size:1.18rem;font-weight:500;margin-bottom:1rem}\n.opts{display:grid;gap:.55rem}\n.opt{display:grid;grid-template-columns:2rem minmax(0,1fr);gap:.7rem;align-items:center;text-align:left;font:500 1.05rem var(--f-math);color:var(--ink);background:var(--paper);border:1.5px solid var(--line);border-radius:10px;padding:.65rem .8rem;cursor:pointer;width:100%}\n.opt .l{font:700 .9rem var(--f-body);width:1.8rem;height:1.8rem;border-radius:50%;display:grid;place-items:center;background:var(--accent-soft);color:var(--accent)}\n.opt:hover:not(:disabled){border-color:var(--accent)}\n.opt.sel{border-color:var(--accent);background:var(--accent-soft)}\n.opt.good{border-color:var(--ok);background:var(--ok-soft)}\n.opt.bad{border-color:var(--bad);background:var(--bad-soft)}\n.opt:disabled{cursor:default;opacity:1}\n.expl{margin-top:1rem;padding:.8rem 1rem;border-radius:10px;background:var(--accent-soft);font-size:.98rem}\n.expl b.g{color:var(--ok)}.expl b.r{color:var(--bad)}\n.qnav{display:flex;justify-content:space-between;gap:.6rem;margin-top:1rem;flex-wrap:wrap}\n.navg{display:grid;grid-template-columns:repeat(auto-fill,minmax(36px,1fr));gap:.35rem}\n.navg button{font:600 .85rem var(--f-body);padding:.4rem 0;border-radius:8px;border:1.5px solid var(--line);background:var(--paper);color:var(--muted);cursor:pointer}\n.navg button.done{background:var(--accent-soft);color:var(--accent);border-color:var(--accent-soft)}\n.navg button.cur{border-color:var(--accent);color:var(--ink)}\n.warn{background:var(--bad-soft);color:var(--ink);border-radius:10px;padding:.8rem 1rem;margin-top:1rem}\n\n/* results */\n.score{display:flex;align-items:baseline;gap:1rem;flex-wrap:wrap;margin:.4rem 0 1rem}\n.score .big{font-family:var(--f-display);font-weight:800;font-size:clamp(2.6rem,9vw,4rem);line-height:1}\n.mention{font-weight:700;background:var(--hi);padding:.1rem .6rem;border-radius:6px;color:inherit}\n.bars{display:grid;gap:.5rem;margin:1rem 0}\n.bars div{display:grid;grid-template-columns:minmax(0,13rem) 1fr 4ch;gap:.7rem;align-items:center;font-size:.92rem}\n.bars .bar{max-width:none}\n.bars .bar i.lo{background:var(--bad)}\n.rev{display:grid;gap:.8rem;margin-top:1rem}\n.rev .qcard{padding:1rem 1.1rem}\n.rev .res-ok{color:var(--ok);font-weight:700}.rev .res-no{color:var(--bad);font-weight:700}\n.filters{display:flex;gap:.5rem;flex-wrap:wrap;margin-top:1.2rem}\n\n/* builder */\n.form{display:grid;gap:1rem}\n.chk{display:grid;grid-template-columns:repeat(auto-fit,minmax(230px,1fr));gap:.4rem}\n.chk label,.inl label{display:flex;gap:.55rem;align-items:center;cursor:pointer}\n.inl{display:flex;gap:1.2rem;flex-wrap:wrap;align-items:center}\nselect,input[type=number]{font:500 1rem var(--f-body);padding:.4rem .6rem;border-radius:8px;border:1.5px solid var(--line);background:var(--paper);color:var(--ink)}\ninput[type=checkbox],input[type=radio]{accent-color:var(--accent);width:1.1rem;height:1.1rem}\n.presets{display:grid;gap:.75rem}\n.preset{display:grid;grid-template-columns:minmax(0,1fr) auto;gap:1rem;align-items:center}\n/* pièges */\n.lead{font-size:1.05rem;color:var(--muted)}\n.tabs{flex-wrap:wrap}\n.trap{background:var(--paper);border:1px solid var(--line);border-left:5px solid var(--bad);border-radius:12px;padding:1.1rem 1.3rem;margin-bottom:1rem}\n.trap h3{margin:0 0 .6rem;font-size:1.12rem}\n.tg{display:grid;grid-template-columns:repeat(auto-fit,minmax(240px,1fr));gap:.7rem;margin:.6rem 0 .8rem}\n.tg>div{border-radius:10px;padding:.7rem .9rem;font-size:1.02rem;min-width:0;overflow-wrap:anywhere}\n.tg .bad{background:var(--bad-soft)}\n.tg .good{background:var(--ok-soft)}\n.tg span{display:block;font:700 .72rem var(--f-body);letter-spacing:.1em;text-transform:uppercase;margin-bottom:.25rem}\n.tg .bad span{color:var(--bad)}\n.tg .good span{color:var(--ok)}\n.trap .why{margin:.4rem 0}\n.trap .hint{margin:.6rem 0 0;padding:.6rem .85rem;border-radius:8px;background:var(--accent-soft);font-size:.97rem}\n.chips{display:flex;flex-wrap:wrap;gap:.45rem;margin:1rem 0}\n.chips a{padding:.35rem .8rem;border-radius:999px;border:1.5px solid var(--line);background:var(--paper);text-decoration:none;font-size:.88rem;font-weight:600}\n.toplist{list-style:none;margin:.8rem 0 1rem;padding:0;display:grid;gap:.4rem}\n.toplist a{display:flex;justify-content:space-between;gap:1rem;padding:.55rem .8rem;border:1px solid var(--line);border-left:4px solid var(--bad);border-radius:8px;text-decoration:none;color:var(--ink)}\n.toplist a span{color:var(--muted);font-size:.85rem;white-space:nowrap}\n.toplist a:hover{background:var(--accent-soft)}\n.badge{display:inline-block;min-width:1.3em;padding:0 .35em;border-radius:99px;background:var(--bad);color:var(--paper);font-size:.75rem;text-align:center;margin-left:.2em}\n/* problèmes + fiches */\ntextarea{width:100%;box-sizing:border-box;margin-top:.5rem;font:500 1rem/1.5 var(--f-body);padding:.7rem .8rem;border-radius:10px;border:1.5px solid var(--line);background:var(--paper);color:var(--ink);resize:vertical}\n.steps{padding-left:1.2rem}.steps li{margin:.5rem 0}\n.final{margin:.8rem 0 0;padding:.7rem .9rem;border-radius:10px;background:var(--ok-soft)}\n.crit{display:flex;gap:.6rem;align-items:flex-start;margin:.5rem 0;cursor:pointer}\n.crit input{margin-top:.25rem;flex:none}\n.hint-p,#hints .hint{margin:.6rem 0 0;padding:.6rem .85rem;border-radius:8px;background:var(--accent-soft);font-size:.97rem}\n.chips a[aria-current=\"page\"]{background:var(--accent);color:var(--accent-ink);border-color:var(--accent)}\n.crumb button{font-family:inherit}\n.fiche{background:var(--paper);border:1px solid var(--line);border-radius:12px;padding:1.2rem 1.4rem}\n.fs{break-inside:avoid;margin-bottom:1rem}\n.fs h2{font-size:1.1rem;margin:.4rem 0 .4rem;border-bottom:2px solid var(--hi)}\n.fp{padding-left:1.1rem;columns:2 260px;column-gap:1.5rem}.fp li{break-inside:avoid;margin:0 0 .6rem;font-size:.95rem}\n@media print{\n .top,.noprint,.crumb{display:none!important}\n body{background:#fff!important;background-image:none!important;color:#000}\n body::before{display:none}\n .wrap{max-width:none;padding:0}\n .fiche{border:0;padding:0}\n .fs,.formula,.fp li{break-inside:avoid}\n :root{--paper:#fff;--ink:#000;--line:#bbb;--muted:#333;--hi:#ffe27a;--accent-soft:#eee}\n a{color:#000;text-decoration:none}\n}\n@media (prefers-reduced-motion: reduce){*{transition:none!important}}\n:root{color-scheme:light}\n[hidden]{display:none!important}\n</style>\n</head>\n<body>\n\n<div class=\"top\"><div class=\"wrap\">\n  <a class=\"brand\" href=\"#accueil\"><b>Maths</b> SN4</a>\n  <nav id=\"nav\" aria-label=\"Navigation principale\">\n    <a href=\"#accueil\" data-k=\"accueil\">Accueil</a>\n    <a href=\"#pieges\" data-k=\"pieges\">Pièges</a>\n    <a href=\"#problemes\" data-k=\"problemes\">Problèmes</a>\n    <a href=\"#erreurs\" data-k=\"erreurs\">Mes erreurs</a>\n    <a href=\"#tests\" data-k=\"tests\">Tests</a>\n    <a href=\"#examens\" data-k=\"examens\">Examens</a>\n  </nav>\n</div></div>\n<main class=\"wrap\" id=\"app\"></main>\n<script>\nwindow.CH = window.CH || [];\nCH.push({\nid:1, titre:\"La manipulation d'expressions algébriques\",\nresume:\"Multiplication et division de polynômes, fractions algébriques (expressions rationnelles).\",\ncours:[\n{h:\"La multiplication de polynômes\", html:`\n<p>On distribue chaque terme du premier facteur à chaque terme du second, puis on regroupe les termes semblables. Le degré du produit est la somme des degrés des facteurs.</p>\n<div class=\"formula\">\n<div>(a + b)(c + d) = ac + ad + bc + bd</div>\n<div>(a + b)^{2} = a^{2} + 2ab + b^{2} &nbsp;&nbsp; (a + b)(a − b) = a^{2} − b^{2}</div>\n</div>\n<div class=\"ex\"><b>Exemple</b> (2x − 3)(x^{2} + 4x − 1) = 2x^{3} + 8x^{2} − 2x − 3x^{2} − 12x + 3 = 2x^{3} + 5x^{2} − 14x + 3</div>\n<p class=\"tip\">Pour éviter les oublis, multipliez toujours terme par terme dans le même ordre et cochez chaque produit.</p>`},\n{h:\"La division de polynômes\", html:`\n<p>Diviser P(x) par D(x), c'est trouver un quotient Q(x) et un reste R(x) tels que :</p>\n<div class=\"formula\">\n<div>P(x) = D(x) · Q(x) + R(x) &nbsp;&nbsp; avec degré de R &lt; degré de D</div>\n</div>\n<p>Si le diviseur est x − a, le <b>théorème du reste</b> dit que le reste vaut P(a).</p>\n<div class=\"ex\"><b>Exemple</b> (x^{3} + 2x^{2} − 5x + 6) ÷ (x − 2) : quotient x^{2} + 4x + 3 et reste 12. On le vérifie avec P(2) = 8 + 8 − 10 + 6 = 12.</div>\n<p>Quand le reste est nul, le diviseur est un facteur : x^{2} − 5x + 6 = (x − 2)(x − 3).</p>`},\n{h:\"Les fractions algébriques\", html:`\n<p>Une fraction algébrique est un quotient de polynômes. Les valeurs qui annulent le dénominateur sont <b>interdites</b>.</p>\n<ul>\n<li><b>Simplifier :</b> factoriser le numérateur et le dénominateur, puis éliminer les facteurs communs.</li>\n<li><b>Multiplier :</b> multiplier les numérateurs entre eux et les dénominateurs entre eux (après simplification).</li>\n<li><b>Diviser :</b> multiplier par l'inverse de la deuxième fraction.</li>\n<li><b>Additionner :</b> mettre au même dénominateur, puis additionner les numérateurs.</li>\n</ul>\n<div class=\"ex\"><b>Exemple</b> [[x^{2} − 4|x^{2} − 2x]] = [[(x − 2)(x + 2)|x(x − 2)]] = [[x + 2|x]] &nbsp; (x ≠ 0 et x ≠ 2)</div>\n<div class=\"ex\"><b>Exemple</b> [[1|x]] + [[2|x + 1]] = [[(x + 1) + 2x|x(x + 1)]] = [[3x + 1|x(x + 1)]]</div>`}\n],\nq:[\n{p:\"Développer (x + 3)(x − 5).\", o:[\"x^{2} − 2x − 15\",\"x^{2} + 2x − 15\",\"x^{2} − 8x − 15\",\"x^{2} − 15\"], a:0, e:\"x · x + x · (−5) + 3 · x + 3 · (−5) = x^{2} − 5x + 3x − 15 = x^{2} − 2x − 15.\"},\n{p:\"Développer (2x − 1)(x^{2} + 3x + 2).\", o:[\"2x^{3} + 5x^{2} + x − 2\",\"2x^{3} + 7x^{2} + x − 2\",\"2x^{3} + 5x^{2} + 7x − 2\",\"2x^{3} + 6x^{2} + 4x − 2\"], a:0, e:\"2x^{3} + 6x^{2} + 4x − x^{2} − 3x − 2 = 2x^{3} + 5x^{2} + x − 2.\"},\n{p:\"Quel est le degré du produit (x^{3} − 2x)(4x^{2} + 1) ?\", o:[\"5\",\"6\",\"3\",\"2\"], a:0, e:\"Le degré d'un produit est la somme des degrés : 3 + 2 = 5.\"},\n{p:\"Quel est le reste de la division de x^{3} + 2x^{2} − 5x + 6 par x − 2 ?\", o:[\"12\",\"0\",\"16\",\"6\"], a:0, e:\"Théorème du reste : P(2) = 8 + 8 − 10 + 6 = 12.\"},\n{p:\"Quel est le quotient de (x^{2} − 5x + 6) ÷ (x − 2) ?\", o:[\"x − 3\",\"x + 3\",\"x − 2\",\"x − 6\"], a:0, e:\"x^{2} − 5x + 6 = (x − 2)(x − 3), donc le quotient est x − 3 et le reste est nul.\"},\n{p:\"Quel est le quotient de (2x^{2} + x − 6) ÷ (x + 2) ?\", o:[\"2x − 3\",\"2x + 3\",\"x − 3\",\"2x − 4\"], a:0, e:\"(x + 2)(2x − 3) = 2x^{2} − 3x + 4x − 6 = 2x^{2} + x − 6. Le reste est nul.\"},\n{p:\"Quelles sont les valeurs interdites de [[3|x^{2} − 9]] ?\", o:[\"x = 3 et x = −3\",\"x = 3\",\"x = 9\",\"x = 0\"], a:0, e:\"On résout x^{2} − 9 = 0, soit (x − 3)(x + 3) = 0 : x = 3 ou x = −3.\"},\n{p:\"Simplifier [[x^{2} − 4|x^{2} − 2x]].\", o:[\"[[x + 2|x]]\",\"[[x − 2|x]]\",\"[[x + 2|x − 2]]\",\"[[−4|−2x]]\"], a:0, e:\"Numérateur : (x − 2)(x + 2). Dénominateur : x(x − 2). On simplifie le facteur x − 2.\"},\n{p:\"Effectuer [[1|x]] + [[2|x + 1]].\", o:[\"[[3x + 1|x(x + 1)]]\",\"[[3|2x + 1]]\",\"[[3x + 2|x(x + 1)]]\",\"[[x + 3|x(x + 1)]]\"], a:0, e:\"Dénominateur commun x(x + 1) : [[(x + 1) + 2x|x(x + 1)]] = [[3x + 1|x(x + 1)]]. On n'additionne jamais les dénominateurs.\"},\n{p:\"Effectuer [[x^{2} − 1|x]] ÷ [[x + 1|x^{2}]].\", o:[\"x(x − 1)\",\"[[x − 1|x]]\",\"x − 1\",\"[[(x + 1)^{2}|x^{3}]]\"], a:0, e:\"On multiplie par l'inverse : [[(x − 1)(x + 1)|x]] · [[x^{2}|x + 1]] = x(x − 1).\"}\n]});\n\nCH.push({\nid:2, titre:\"La factorisation\",\nresume:\"Mise en évidence double, trinômes, différence de carrés, complétion du carré, équations du 2e degré.\",\ncours:[\n{h:\"Mise en évidence et factorisation d'un trinôme\", html:`\n<p>Toujours commencer par la mise en évidence d'un facteur commun : 3x^{2} − 12x = 3x(x − 4).</p>\n<p><b>Mise en évidence double :</b> grouper les termes deux par deux. Pour factoriser ax^{2} + bx + c, on cherche deux nombres dont le produit est a · c et la somme est b, puis on décompose le terme du milieu.</p>\n<div class=\"ex\"><b>Exemple</b> 2x^{2} + 7x + 3 : a · c = 6, somme 7, donc 1 et 6.<br>\n2x^{2} + 6x + x + 3 = 2x(x + 3) + (x + 3) = (x + 3)(2x + 1)</div>`},\n{h:\"Trinôme carré parfait et différence de carrés\", html:`\n<div class=\"formula\">\n<div>a^{2} + 2ab + b^{2} = (a + b)^{2} &nbsp;&nbsp; a^{2} − 2ab + b^{2} = (a − b)^{2}</div>\n<div>a^{2} − b^{2} = (a − b)(a + b)</div>\n</div>\n<div class=\"ex\"><b>Exemples</b> 4x^{2} − 12x + 9 = (2x − 3)^{2} &nbsp; et &nbsp; 9x^{2} − 16 = (3x − 4)(3x + 4)</div>\n<p class=\"tip\">Un trinôme est un carré parfait quand le double produit des racines des deux carrés est égal au terme du milieu.</p>`},\n{h:\"La complétion du carré\", html:`\n<p>Ajouter et retrancher le carré de la moitié du coefficient de x pour obtenir une forme (x + h)^{2} + k.</p>\n<div class=\"ex\"><b>Exemple</b> x^{2} + 8x + 3 = (x^{2} + 8x + 16) − 16 + 3 = (x + 4)^{2} − 13</div>\n<div class=\"ex\"><b>Si a ≠ 1</b> 2x^{2} + 12x + 5 = 2(x^{2} + 6x) + 5 = 2(x + 3)^{2} − 18 + 5 = 2(x + 3)^{2} − 13</div>`},\n{h:\"Factoriser pour manipuler les fractions algébriques\", html:`\n<p>La factorisation permet de simplifier et de trouver un dénominateur commun.</p>\n<div class=\"ex\"><b>Exemple</b> [[x^{2} − 9|x^{2} + 6x + 9]] = [[(x − 3)(x + 3)|(x + 3)^{2}]] = [[x − 3|x + 3]] &nbsp; (x ≠ −3)</div>`},\n{h:\"La résolution d'une équation du second degré\", html:`\n<p>Trois outils : factorisation, racine carrée (si b = 0) et formule quadratique.</p>\n<div class=\"formula\">\n<div>x = [[−b ± √{b^{2} − 4ac}|2a]] &nbsp;&nbsp; Δ = b^{2} − 4ac</div>\n</div>\n<ul>\n<li>Δ &gt; 0 : deux solutions. Δ = 0 : une solution. Δ &lt; 0 : aucune solution réelle.</li>\n<li>Somme des solutions : −[[b|a]]. Produit : [[c|a]].</li>\n</ul>\n<div class=\"ex\"><b>Exemple</b> 2x^{2} − x − 6 = 0 : (2x + 3)(x − 2) = 0, donc x = 2 ou x = −[[3|2]].</div>`}\n],\nq:[\n{p:\"Factoriser x^{2} − 49.\", o:[\"(x − 7)(x + 7)\",\"(x − 7)^{2}\",\"(x + 7)^{2}\",\"(x − 49)(x + 1)\"], a:0, e:\"Différence de carrés : a^{2} − b^{2} = (a − b)(a + b) avec a = x et b = 7.\"},\n{p:\"Factoriser x^{2} + 5x + 6.\", o:[\"(x + 2)(x + 3)\",\"(x + 1)(x + 6)\",\"(x − 2)(x − 3)\",\"(x + 5)(x + 1)\"], a:0, e:\"On cherche deux nombres de produit 6 et de somme 5 : 2 et 3.\"},\n{p:\"Factoriser complètement 3x^{2} − 12x.\", o:[\"3x(x − 4)\",\"3x(x − 12)\",\"x(3x − 4)\",\"3(x − 4)\"], a:0, e:\"Le facteur commun est 3x : 3x^{2} ÷ 3x = x et 12x ÷ 3x = 4.\"},\n{p:\"Factoriser 2x^{2} + 7x + 3.\", o:[\"(2x + 1)(x + 3)\",\"(2x + 3)(x + 1)\",\"(2x − 1)(x − 3)\",\"(x + 7)(2x + 3)\"], a:0, e:\"a · c = 6 et somme 7 : 1 et 6. 2x^{2} + 6x + x + 3 = 2x(x + 3) + (x + 3) = (2x + 1)(x + 3).\"},\n{p:\"Factoriser 4x^{2} − 12x + 9.\", o:[\"(2x − 3)^{2}\",\"(2x + 3)^{2}\",\"(4x − 3)(x − 3)\",\"(2x − 3)(2x + 3)\"], a:0, e:\"4x^{2} = (2x)^{2}, 9 = 3^{2} et le double produit vaut 2 · 2x · 3 = 12x. C'est (2x − 3)^{2}.\"},\n{p:\"Écrire x^{2} + 8x + 3 sous la forme (x + h)^{2} + k.\", o:[\"(x + 4)^{2} − 13\",\"(x + 4)^{2} + 3\",\"(x + 8)^{2} − 61\",\"(x − 4)^{2} − 13\"], a:0, e:\"(x + 4)^{2} = x^{2} + 8x + 16. Pour retrouver +3, on retranche 13.\"},\n{p:\"Simplifier [[x^{2} − 9|x^{2} + 6x + 9]].\", o:[\"[[x − 3|x + 3]]\",\"[[x + 3|x − 3]]\",\"[[−3|3]]\",\"[[x − 3|6]]\"], a:0, e:\"Numérateur : (x − 3)(x + 3). Dénominateur : (x + 3)^{2}. On simplifie un facteur (x + 3).\"},\n{p:\"Résoudre 2x^{2} − x − 6 = 0.\", o:[\"x = 2 ou x = −[[3|2]]\",\"x = −2 ou x = [[3|2]]\",\"x = 3 ou x = −2\",\"x = 6 ou x = −1\"], a:0, e:\"2x^{2} − x − 6 = (2x + 3)(x − 2) = 0. On vérifie : Δ = 1 + 48 = 49, x = [[1 ± 7|4]].\"},\n{p:\"Pour quelle valeur de k l'équation x^{2} + 4x + k = 0 a-t-elle exactement une solution ?\", o:[\"k = 4\",\"k = 2\",\"k = 8\",\"k = 16\"], a:0, e:\"Il faut Δ = 0 : 16 − 4k = 0, donc k = 4.\"},\n{p:\"L'aire d'un rectangle est de 48 cm². Sa longueur dépasse sa largeur de 2 cm. Quelle est sa largeur ?\", o:[\"6 cm\",\"8 cm\",\"4 cm\",\"12 cm\"], a:0, e:\"w(w + 2) = 48 donne w^{2} + 2w − 48 = 0, soit (w + 8)(w − 6) = 0. La largeur est 6 cm (la solution négative est rejetée).\"}\n]});\n\nCH.push({\nid:3, titre:\"L'étude des fonctions\",\nresume:\"Propriétés d'une fonction, paramètres de transformation, fonction partie entière.\",\ncours:[\n{h:\"Les fonctions et leurs propriétés\", html:`\n<ul>\n<li><b>Domaine :</b> valeurs permises de x. Il exclut les valeurs qui annulent un dénominateur ou rendent un radicand négatif.</li>\n<li><b>Image :</b> valeurs prises par y.</li>\n<li><b>Zéros :</b> valeurs de x pour lesquelles f(x) = 0. <b>Ordonnée à l'origine :</b> f(0).</li>\n<li><b>Croissance, décroissance, extremums, signe</b> : se lisent sur le graphique.</li>\n</ul>\n<div class=\"ex\"><b>Exemple</b> f(x) = √{x − 4} + 1 : il faut x − 4 ≥ 0, donc dom f = [4, +∞[. Pour f(x) = [[5|x + 2]], dom f = ℝ \\\\ {−2}.</div>`},\n{h:\"Les paramètres d'une fonction\", html:`\n<div class=\"formula\">\n<div>g(x) = a · f(b(x − h)) + k</div>\n</div>\n<ul>\n<li><b>a :</b> étirement vertical ; réflexion par rapport à l'axe des x si a &lt; 0</li>\n<li><b>b :</b> étirement horizontal de facteur [[1||b|]] ; réflexion par rapport à l'axe des y si b &lt; 0</li>\n<li><b>h :</b> translation horizontale (vers la droite si h &gt; 0)</li>\n<li><b>k :</b> translation verticale (vers le haut si k &gt; 0)</li>\n</ul>\n<p>Fonctions de base : x^{2}, |x|, √x, [[1|x]]. Pour f(x) = a|x − h| + k, le sommet est (h, k). Pour f(x) = [[a|x − h]] + k, les asymptotes sont x = h et y = k.</p>\n<p>Valeur absolue : |x − a| = b donne x = a + b ou x = a − b ; |x − a| &lt; b équivaut à a − b &lt; x &lt; a + b.</p>`},\n{h:\"La fonction partie entière : une fonction en escalier\", html:`\n<p>[x] est le plus grand entier inférieur ou égal à x. Le graphique de f(x) = [x] est un escalier : sur chaque intervalle [n, n + 1[, la fonction est constante et vaut n.</p>\n<div class=\"formula\">\n<div>[3,7] = 3 &nbsp;&nbsp; [5] = 5 &nbsp;&nbsp; [−2,3] = −3</div>\n</div>\n<p class=\"tip\">Pour un nombre négatif, on recule vers l'entier plus petit : [−2,3] vaut −3, pas −2.</p>\n<p>Avec des paramètres : f(x) = a[b(x − h)] + k, utile pour modéliser des tarifs par tranche (stationnement, livraison).</p>`}\n],\nq:[\n{p:\"Quel est le domaine de f(x) = √{x − 4} + 1 ?\", o:[\"[4, +∞[\",\"]4, +∞[\",\"[−4, +∞[\",\"[1, +∞[\"], a:0, e:\"Il faut x − 4 ≥ 0, donc x ≥ 4. La valeur 4 est permise (le radicand vaut 0).\"},\n{p:\"Quel est le domaine de f(x) = [[5|x + 2]] ?\", o:[\"ℝ \\\\ {−2}\",\"ℝ \\\\ {2}\",\"ℝ\",\"]−2, +∞[\"], a:0, e:\"Le dénominateur s'annule pour x = −2. Cette valeur est interdite.\"},\n{p:\"Quel est le sommet de f(x) = |x + 3| − 2 ?\", o:[\"(−3, −2)\",\"(3, −2)\",\"(−3, 2)\",\"(3, 2)\"], a:0, e:\"|x + 3| = |x − (−3)| : h = −3. Le sommet est (−3, −2).\"},\n{p:\"Quelle est l'image de f(x) = −|x| + 4 ?\", o:[\"]−∞, 4]\",\"[4, +∞[\",\"ℝ\",\"[0, 4]\"], a:0, e:\"|x| ≥ 0, donc −|x| ≤ 0 et f(x) ≤ 4. Le maximum 4 est atteint en x = 0.\"},\n{p:\"Par rapport à f(x) = √x, la courbe de g(x) = −√{x + 2} est obtenue par :\", o:[\"une réflexion par rapport à l'axe des x et une translation de 2 vers la gauche\",\"une réflexion par rapport à l'axe des y et une translation de 2 vers la droite\",\"une translation de 2 vers le haut seulement\",\"une réflexion par rapport à l'axe des x et une translation de 2 vers le bas\"], a:0, e:\"Le signe − devant la racine réfléchit sur l'axe des x. Le x + 2 = x − (−2) déplace de 2 unités vers la gauche.\"},\n{p:\"Que vaut [−2,3] ?\", o:[\"−3\",\"−2\",\"2\",\"−2,3\"], a:0, e:\"La partie entière est le plus grand entier inférieur ou égal au nombre. Pour −2,3, c'est −3.\"},\n{p:\"Si f(x) = [x] + 2, que vaut f(3,9) ?\", o:[\"5\",\"6\",\"4\",\"3\"], a:0, e:\"[3,9] = 3, donc f(3,9) = 3 + 2 = 5.\"},\n{p:\"Pour quelles valeurs de x a-t-on [x] = 4 ?\", o:[\"4 ≤ x &lt; 5\",\"3 &lt; x ≤ 4\",\"3,5 ≤ x &lt; 4,5\",\"x = 4 seulement\"], a:0, e:\"La partie entière vaut 4 sur l'intervalle [4, 5[ (4 inclus, 5 exclu).\"},\n{p:\"Si f(x) = [[6|x]], que vaut f(−3) ?\", o:[\"−2\",\"2\",\"−18\",\"18\"], a:0, e:\"f(−3) = [[6|−3]] = −2.\"},\n{p:\"Résoudre |2x − 1| &lt; 5.\", o:[\"]−2, 3[\",\"]−3, 2[\",\"]−∞, −2[ ∪ ]3, +∞[\",\"[−2, 3]\"], a:0, e:\"−5 &lt; 2x − 1 &lt; 5, donc −4 &lt; 2x &lt; 6, soit −2 &lt; x &lt; 3. L'inégalité est stricte : crochets ouverts.\"}\n]});\n\nCH.push({\nid:4, titre:\"La fonction polynomiale du second degré\",\nresume:\"Règle et propriétés, différentes notations, recherche de la règle, inéquations du 2e degré. Explorateur interactif inclus.\",\nexplorer:true,\ncours:[\n{h:\"Règle et propriétés\", html:`\n<div class=\"formula\">\n<div>Générale : f(x) = ax^{2} + bx + c</div>\n<div>Canonique : f(x) = a(x − h)^{2} + k &nbsp; sommet (h, k)</div>\n<div>Factorisée : f(x) = a(x − x_{1})(x − x_{2}) &nbsp; zéros x_{1} et x_{2}</div>\n</div>\n<ul>\n<li><b>Ouverture :</b> vers le haut si a &gt; 0 (minimum k), vers le bas si a &lt; 0 (maximum k).</li>\n<li><b>Axe de symétrie :</b> x = h = −[[b|2a]]</li>\n<li><b>Ordonnée à l'origine :</b> f(0) = c</li>\n<li><b>Image :</b> [k, +∞[ si a &gt; 0, ]−∞, k] si a &lt; 0</li>\n</ul>\n<div class=\"ex\"><b>Exemple</b> f(x) = x^{2} − 6x + 4 : h = [[6|2]] = 3 et k = f(3) = −5. Sommet (3, −5), minimum −5.</div>`},\n{h:\"Les différentes notations : passer d'une forme à l'autre\", html:`\n<p>Chaque forme répond rapidement à une question : la canonique donne le sommet, la factorisée donne les zéros, la générale donne l'ordonnée à l'origine.</p>\n<div class=\"ex\"><b>Générale → canonique</b> (complétion du carré) x^{2} + 8x + 3 = (x + 4)^{2} − 13</div>\n<div class=\"ex\"><b>Canonique → générale</b> (développer) 2(x − 1)^{2} + 3 = 2x^{2} − 4x + 5</div>\n<div class=\"ex\"><b>Générale → factorisée</b> x^{2} − 2x − 8 = (x − 4)(x + 2)</div>`},\n{h:\"La recherche de la règle\", html:`\n<p>Choisir la forme selon les données : sommet et un point (forme canonique), deux zéros et un point (forme factorisée), trois points (système d'équations sur a, b et c).</p>\n<div class=\"ex\"><b>Exemple</b> Sommet (1, 2), passe par (0, 3) : 3 = a(0 − 1)^{2} + 2, donc a = 1 et f(x) = (x − 1)^{2} + 2.</div>`},\n{h:\"La résolution d'une inéquation du second degré à une variable\", html:`\n<ol>\n<li>Ramener l'inéquation à la forme f(x) ≥ 0 (ou ≤, &gt;, &lt;).</li>\n<li>Trouver les zéros de f.</li>\n<li>Imaginer la parabole : si a &gt; 0, elle est positive à l'extérieur des zéros et négative entre eux.</li>\n</ol>\n<div class=\"ex\"><b>Exemple</b> x^{2} − x − 12 ≤ 0 : zéros −3 et 4, parabole ouverte vers le haut. Solution : [−3, 4]</div>`}\n],\nq:[\n{p:\"Quel est le sommet de f(x) = (x − 3)^{2} + 5 ?\", o:[\"(3, 5)\",\"(−3, 5)\",\"(3, −5)\",\"(5, 3)\"], a:0, e:\"Dans a(x − h)^{2} + k, le sommet est (h, k). Ici h = 3 (attention au signe) et k = 5.\"},\n{p:\"Quelle est l'équation de l'axe de symétrie de f(x) = −2x^{2} + 4x + 1 ?\", o:[\"x = 1\",\"x = −1\",\"x = 2\",\"x = [[1|2]]\"], a:0, e:\"h = −[[b|2a]] = −[[4|−4]] = 1.\"},\n{p:\"Quelle est la valeur minimale de f(x) = x^{2} − 6x + 4 ?\", o:[\"−5\",\"3\",\"4\",\"−9\"], a:0, e:\"h = 3 et f(3) = 9 − 18 + 4 = −5. Le minimum est la deuxième coordonnée du sommet.\"},\n{p:\"Quels sont les zéros de f(x) = x^{2} − 2x − 8 ?\", o:[\"−2 et 4\",\"2 et −4\",\"−2 et −4\",\"8 et −1\"], a:0, e:\"x^{2} − 2x − 8 = (x − 4)(x + 2). Les zéros sont 4 et −2.\"},\n{p:\"Quelle est l'ordonnée à l'origine de f(x) = −(x + 1)^{2} + 9 ?\", o:[\"8\",\"9\",\"10\",\"−1\"], a:0, e:\"f(0) = −(1)^{2} + 9 = 8.\"},\n{p:\"Une parabole a pour sommet (1, 2) et passe par (0, 3). Quelle est sa règle ?\", o:[\"f(x) = (x − 1)^{2} + 2\",\"f(x) = 3(x − 1)^{2} + 2\",\"f(x) = (x + 1)^{2} + 2\",\"f(x) = −(x − 1)^{2} + 2\"], a:0, e:\"3 = a(0 − 1)^{2} + 2 donne a = 1. Seule la première option a le sommet (1, 2) et passe par (0, 3).\"},\n{p:\"Écrire f(x) = 2(x − 1)^{2} + 3 sous la forme générale.\", o:[\"2x^{2} − 4x + 5\",\"2x^{2} − 2x + 4\",\"2x^{2} + 4x + 5\",\"2x^{2} − 4x + 3\"], a:0, e:\"2(x^{2} − 2x + 1) + 3 = 2x^{2} − 4x + 2 + 3 = 2x^{2} − 4x + 5.\"},\n{p:\"La hauteur d'un ballon est h(t) = −5t^{2} + 20t + 1 (en mètres, t en secondes). Quelle est sa hauteur maximale ?\", o:[\"21 m\",\"20 m\",\"41 m\",\"1 m\"], a:0, e:\"t = −[[20|−10]] = 2 s, puis h(2) = −20 + 40 + 1 = 21 m.\"},\n{p:\"Résoudre x^{2} − x − 12 ≤ 0.\", o:[\"[−3, 4]\",\"]−∞, −3] ∪ [4, +∞[\",\"[−4, 3]\",\"]−3, 4[\"], a:0, e:\"Les zéros sont −3 et 4. La parabole est négative entre les zéros, et l'inégalité large inclut les zéros.\"},\n{p:\"Résoudre x^{2} &gt; 9.\", o:[\"x &lt; −3 ou x &gt; 3\",\"−3 &lt; x &lt; 3\",\"x &gt; 3\",\"x &lt; −9 ou x &gt; 9\"], a:0, e:\"x^{2} − 9 &gt; 0 : la parabole est positive à l'extérieur des zéros −3 et 3.\"}\n]});\n\nCH.push({\nid:5, titre:\"Les triangles et les figures équivalentes\",\nresume:\"Triangles isométriques, triangles semblables, relations métriques dans le triangle rectangle, figures équivalentes.\",\ncours:[\n{h:\"Les triangles isométriques\", html:`\n<p>Deux triangles sont <b>isométriques</b> (≅) quand leurs côtés et leurs angles homologues sont égaux. Pour le prouver, il suffit de vérifier l'un de ces cas :</p>\n<ul>\n<li><b>CCC :</b> trois côtés homologues égaux</li>\n<li><b>CAC :</b> deux côtés égaux et l'angle compris entre eux égal</li>\n<li><b>ACA :</b> deux angles égaux et le côté compris entre eux égal</li>\n</ul>\n<p class=\"tip\">Deux triangles dont trois angles sont égaux ne sont pas forcément isométriques : ils sont seulement semblables.</p>`},\n{h:\"Les triangles semblables\", html:`\n<p>Deux triangles sont <b>semblables</b> (∼) quand leurs angles homologues sont égaux et leurs côtés homologues sont proportionnels. Cas suffisants : <b>AA</b> (deux angles égaux), <b>CAC</b> proportionnel, <b>CCC</b> proportionnel.</p>\n<div class=\"formula\">\n<div>Rapport de similitude k = [[longueur dans la figure image|longueur homologue dans la figure initiale]]</div>\n<div>longueurs × k &nbsp;&nbsp; aires × k^{2} &nbsp;&nbsp; volumes × k^{3}</div>\n</div>\n<div class=\"ex\"><b>Exemple</b> ABC ∼ DEF avec AB = 6, DE = 9 et BC = 8 : k = [[9|6]] = 1,5, donc EF = 8 × 1,5 = 12.</div>`},\n{h:\"Les relations métriques dans un triangle rectangle\", html:`\n<p>Soit un triangle rectangle d'hypoténuse a, de cathètes b et c, et de hauteur h issue de l'angle droit. Cette hauteur partage l'hypoténuse en deux segments m (adjacent à c) et n (adjacent à b).</p>\n<div class=\"formula\">\n<div>c^{2} = a · m &nbsp;&nbsp; b^{2} = a · n</div>\n<div>h^{2} = m · n</div>\n<div>b · c = a · h</div>\n<div>a^{2} = b^{2} + c^{2} (Pythagore)</div>\n</div>\n<div class=\"ex\"><b>Exemple</b> Cathètes 6 et 8 : a = 10 et h = [[6 × 8|10]] = 4,8.</div>\n<p class=\"tip\">Triplets pythagoriciens courants : (3, 4, 5), (5, 12, 13), (8, 15, 17), (7, 24, 25).</p>`},\n{h:\"Les figures équivalentes\", html:`\n<p>Deux figures sont <b>équivalentes</b> si elles ont la même aire (ou le même volume), même si leur forme est différente.</p>\n<div class=\"formula\">\n<div>Triangle : [[b × h|2]] &nbsp;&nbsp; Trapèze : [[(B + b) × h|2]] &nbsp;&nbsp; Cercle : πr^{2}</div>\n</div>\n<div class=\"ex\"><b>Exemple</b> Un carré de côté 6 (aire 36) est équivalent à un rectangle de largeur 4 et de longueur 9.</div>`}\n],\nq:[\n{p:\"Deux triangles ont deux côtés égaux, ainsi que l'angle compris entre ces côtés. Quel cas d'isométrie s'applique ?\", o:[\"CAC\",\"ACA\",\"CCC\",\"AA\"], a:0, e:\"Deux côtés et l'angle compris : côté-angle-côté (CAC). AA n'est pas un cas d'isométrie, seulement de similitude.\"},\n{p:\"ABC ∼ DEF avec AB = 6, DE = 9 et BC = 8. Quelle est la longueur EF ?\", o:[\"12\",\"10\",\"5,3\",\"14\"], a:0, e:\"Le rapport de similitude est [[9|6]] = 1,5. EF = 8 × 1,5 = 12.\"},\n{p:\"Deux triangles semblables ont un rapport de similitude de 3. Le plus petit a une aire de 20 cm². Quelle est l'aire du plus grand ?\", o:[\"180 cm²\",\"60 cm²\",\"540 cm²\",\"120 cm²\"], a:0, e:\"Les aires sont multipliées par k^{2} = 9 : 20 × 9 = 180 cm².\"},\n{p:\"Dans un triangle rectangle, la hauteur issue de l'angle droit divise l'hypoténuse en segments de 4 et de 9. Quelle est la mesure de cette hauteur ?\", o:[\"6\",\"36\",\"6,5\",\"13\"], a:0, e:\"h^{2} = m · n = 4 × 9 = 36, donc h = 6.\"},\n{p:\"Un triangle rectangle a une hypoténuse de 25. La projection d'une cathète sur l'hypoténuse mesure 9. Quelle est la longueur de cette cathète ?\", o:[\"15\",\"20\",\"16\",\"9\"], a:0, e:\"c^{2} = a · m = 25 × 9 = 225, donc c = 15.\"},\n{p:\"Les cathètes d'un triangle rectangle mesurent 6 et 8. Quelle est la hauteur issue de l'angle droit ?\", o:[\"4,8\",\"5\",\"3,6\",\"7\"], a:0, e:\"L'hypoténuse est 10. Avec b · c = a · h : 48 = 10h, donc h = 4,8.\"},\n{p:\"Lequel de ces triplets est pythagoricien ?\", o:[\"(5, 12, 13)\",\"(6, 8, 11)\",\"(4, 5, 6)\",\"(7, 9, 12)\"], a:0, e:\"5^{2} + 12^{2} = 25 + 144 = 169 = 13^{2}. Les autres ne vérifient pas a^{2} + b^{2} = c^{2}.\"},\n{p:\"Un carré de côté 6 est équivalent à un rectangle de largeur 4. Quelle est la longueur du rectangle ?\", o:[\"9\",\"6\",\"8\",\"12\"], a:0, e:\"Aire du carré : 36. Longueur du rectangle : 36 ÷ 4 = 9.\"},\n{p:\"Quelle est l'aire d'un trapèze dont les bases mesurent 10 et 6 et dont la hauteur est 5 ?\", o:[\"40\",\"80\",\"30\",\"50\"], a:0, e:\"Aire = [[(10 + 6) × 5|2]] = [[80|2]] = 40.\"},\n{p:\"Un cercle de rayon 5 est équivalent à un carré. Quelle est environ la longueur du côté du carré ?\", o:[\"8,86\",\"7,85\",\"5\",\"9,87\"], a:0, e:\"Aire du cercle : 25π ≈ 78,54. Côté du carré : √78,54 ≈ 8,86.\"}\n]});\n\nCH.push({\nid:6, titre:\"Les relations trigonométriques\",\nresume:\"Rapports trigonométriques, résolution de problèmes, loi des sinus, loi des cosinus et aire d'un triangle.\",\ncours:[\n{h:\"Les relations trigonométriques dans un triangle rectangle\", html:`\n<div class=\"formula\">\n<div>sin θ = [[côté opposé|hypoténuse]]</div>\n<div>cos θ = [[côté adjacent|hypoténuse]]</div>\n<div>tan θ = [[côté opposé|côté adjacent]]</div>\n</div>\n<p>Pour trouver un angle, on utilise la fonction réciproque : θ = tan^{−1}([[3|4]]) ≈ 36,9°. Pour deux angles aigus complémentaires : sin θ = cos(90° − θ).</p>\n<p class=\"tip\">Calculatrice en mode degrés ! C'est l'erreur la plus fréquente aux examens.</p>`},\n{h:\"La résolution de problèmes à l'aide des relations trigonométriques\", html:`\n<p>Faire un schéma, repérer le triangle rectangle, choisir le rapport qui relie ce qu'on connaît à ce qu'on cherche.</p>\n<div class=\"ex\"><b>Exemple</b> À 20 m de la base d'un arbre, l'angle d'élévation du sommet est de 35° : tan 35° = [[h|20]], donc h = 20 tan 35° ≈ 14,0 m.</div>`},\n{h:\"La loi des sinus et la loi des cosinus dans un triangle quelconque\", html:`\n<p>Dans un triangle ABC (côté a opposé à l'angle A, etc.) :</p>\n<div class=\"formula\">\n<div>Loi des sinus : [[a|sin A]] = [[b|sin B]] = [[c|sin C]]</div>\n<div>Loi des cosinus : a^{2} = b^{2} + c^{2} − 2bc · cos A</div>\n</div>\n<ul>\n<li><b>Sinus :</b> on connaît un angle et son côté opposé, plus une autre donnée.</li>\n<li><b>Cosinus :</b> on connaît deux côtés et l'angle compris, ou les trois côtés.</li>\n</ul>\n<div class=\"ex\"><b>Exemple</b> A = 40°, B = 60°, a = 10 : b = [[10 · sin 60°|sin 40°]] ≈ 13,5</div>\n<div class=\"ex\"><b>Exemple</b> b = 7, c = 8, A = 60° : a^{2} = 49 + 64 − 2(7)(8)(0,5) = 57, donc a ≈ 7,55.</div>`},\n{h:\"L'aire d'un triangle\", html:`\n<div class=\"formula\">\n<div>Aire = [[1|2]] · a · b · sin C</div>\n</div>\n<div class=\"ex\"><b>Exemple</b> a = 8, b = 10, C = 30° : aire = [[1|2]] · 8 · 10 · 0,5 = 20.</div>`}\n],\nq:[\n{p:\"Dans un triangle rectangle, l'hypoténuse mesure 10 et un angle aigu vaut 30°. Quelle est la longueur du côté opposé à cet angle ?\", o:[\"5\",\"5√3\",\"10√3\",\"[[10|√3]]\"], a:0, e:\"sin 30° = [[opposé|10]] = 0,5, donc le côté opposé mesure 5.\"},\n{p:\"Si tan θ = [[3|4]], quelle est la mesure de θ ?\", o:[\"36,9°\",\"53,1°\",\"41,4°\",\"48,6°\"], a:0, e:\"θ = tan^{−1}(0,75) ≈ 36,9°. L'angle de 53,1° est son complément.\"},\n{p:\"Un triangle a des côtés de 3, 4 et 5. Que vaut le cosinus du plus petit angle ?\", o:[\"[[4|5]]\",\"[[3|5]]\",\"[[3|4]]\",\"[[5|4]]\"], a:0, e:\"Le plus petit angle est opposé au côté 3. Son côté adjacent est 4 : cos θ = [[4|5]].\"},\n{p:\"À 20 m de la base d'un arbre, l'angle d'élévation du sommet est de 35°. Quelle est la hauteur de l'arbre ?\", o:[\"14,0 m\",\"28,6 m\",\"11,5 m\",\"16,4 m\"], a:0, e:\"tan 35° = [[h|20]], donc h = 20 tan 35° ≈ 14,0 m.\"},\n{p:\"Laquelle de ces valeurs est égale à sin 35° ?\", o:[\"cos 55°\",\"cos 35°\",\"tan 55°\",\"sin 55°\"], a:0, e:\"Pour des angles complémentaires (35° + 55° = 90°), sin 35° = cos 55°.\"},\n{p:\"Dans un triangle ABC, A = 40°, B = 60° et a = 10. Quelle est la longueur b ?\", o:[\"13,5\",\"7,4\",\"11,5\",\"15,6\"], a:0, e:\"Loi des sinus : b = [[10 · sin 60°|sin 40°]] ≈ [[8,66|0,643]] ≈ 13,5.\"},\n{p:\"Dans un triangle, b = 7, c = 8 et A = 60°. Quelle est la longueur a ?\", o:[\"7,55\",\"10,63\",\"8,12\",\"5,29\"], a:0, e:\"a^{2} = 49 + 64 − 2(7)(8)cos 60° = 113 − 56 = 57, donc a ≈ 7,55. Oublier le terme en cosinus donnerait 10,63.\"},\n{p:\"Un triangle a des côtés de 5, 6 et 7. Quel est l'angle opposé au côté de 7 ?\", o:[\"78,5°\",\"101,5°\",\"57,1°\",\"44,4°\"], a:0, e:\"Loi des cosinus : cos C = [[25 + 36 − 49|2(5)(6)]] = 0,2, donc C ≈ 78,5°.\"},\n{p:\"Quelle est l'aire d'un triangle dont deux côtés mesurent 8 et 10 avec un angle compris de 30° ?\", o:[\"20\",\"40\",\"34,6\",\"80\"], a:0, e:\"Aire = [[1|2]] · 8 · 10 · sin 30° = 40 × 0,5 = 20.\"},\n{p:\"Quelle loi faut-il utiliser pour trouver le troisième côté d'un triangle quelconque quand on connaît deux côtés et l'angle compris ?\", o:[\"La loi des cosinus\",\"La loi des sinus\",\"Le théorème de Pythagore\",\"Le rapport tangente\"], a:0, e:\"La loi des sinus exige un angle et son côté opposé connus. Ici, l'angle est entre les deux côtés : loi des cosinus.\"}\n]});\n\nCH.push({\nid:7, titre:\"Les droites et les inéquations à deux variables\",\nresume:\"Pente, droites parallèles et perpendiculaires, distance, formes d'équation d'une droite, inéquations à deux variables.\",\ncours:[\n{h:\"Géométrie analytique : pente, droites parallèles et perpendiculaires, distance\", html:`\n<div class=\"formula\">\n<div>d(A, B) = √{(x_{2} − x_{1})^{2} + (y_{2} − y_{1})^{2}}</div>\n<div>m = [[y_{2} − y_{1}|x_{2} − x_{1}]]</div>\n</div>\n<ul>\n<li>Droites <b>parallèles</b> : même pente.</li>\n<li>Droites <b>perpendiculaires</b> : m_{1} · m_{2} = −1 (pentes opposées et inverses).</li>\n</ul>\n<div class=\"ex\"><b>Exemple</b> A(1, 2) et B(7, 10) : d = √{36 + 64} = 10. Pente de la droite par (1, 3) et (5, 11) : [[8|4]] = 2.</div>`},\n{h:\"Les différentes formes d'équation d'une droite\", html:`\n<div class=\"formula\">\n<div>Fonctionnelle : y = mx + b</div>\n<div>Générale : Ax + By + C = 0 &nbsp; (pente −[[A|B]])</div>\n<div>Symétrique : [[x|a]] + [[y|b]] = 1 &nbsp; (coupe les axes en a et en b)</div>\n</div>\n<div class=\"ex\"><b>Exemple</b> Parallèle à y = 2x + 5 passant par (1, 4) : y − 4 = 2(x − 1), donc y = 2x + 2.</div>\n<div class=\"ex\"><b>Exemple</b> Droite par (2, 1) et (6, 9) : m = 2 et 1 = 2(2) + b, donc y = 2x − 3.</div>`},\n{h:\"Les inéquations du premier degré à deux variables\", html:`\n<p>Tracer la droite frontière (trait plein si ≤ ou ≥, pointillé si &lt; ou &gt;), puis tester un point (souvent l'origine) pour savoir quel côté colorier.</p>\n<div class=\"ex\"><b>Exemple</b> y &gt; 2x − 1 : région au-dessus de la droite, frontière exclue. Le point (0, 0) convient car 0 &gt; −1.</div>`},\n{h:\"Les inéquations du second degré à deux variables\", html:`\n<p>Même méthode, avec une parabole comme frontière : y ≥ ax^{2} + bx + c colorie l'intérieur de la parabole (au-dessus), y ≤ … colorie l'extérieur (au-dessous), si a &gt; 0.</p>\n<div class=\"ex\"><b>Exemple</b> y ≤ x^{2} − 4 : le point (0, −5) convient car −5 ≤ −4, mais (0, 0) ne convient pas car 0 &gt; −4.</div>`}\n],\nq:[\n{p:\"Quelle est la distance entre A(1, 2) et B(7, 10) ?\", o:[\"10\",\"14\",\"8\",\"100\"], a:0, e:\"d = √{6^{2} + 8^{2}} = √{36 + 64} = √100 = 10.\"},\n{p:\"Quelle est la pente de la droite passant par (1, 3) et (5, 11) ?\", o:[\"2\",\"[[1|2]]\",\"−2\",\"4\"], a:0, e:\"m = [[11 − 3|5 − 1]] = [[8|4]] = 2.\"},\n{p:\"Quelle est la pente d'une droite perpendiculaire à y = −[[2|3]]x + 1 ?\", o:[\"[[3|2]]\",\"−[[3|2]]\",\"[[2|3]]\",\"−[[2|3]]\"], a:0, e:\"Le produit des pentes doit valoir −1 : −[[2|3]] × [[3|2]] = −1.\"},\n{p:\"Quelle est l'équation de la droite parallèle à y = 2x + 5 qui passe par (1, 4) ?\", o:[\"y = 2x + 2\",\"y = 2x + 4\",\"y = −[[1|2]]x + 4,5\",\"y = [[1|2]]x + 3,5\"], a:0, e:\"La pente reste 2. De 4 = 2(1) + b, on tire b = 2.\"},\n{p:\"Quelle est l'équation de la droite passant par (2, 1) et (6, 9) ?\", o:[\"y = 2x − 3\",\"y = 2x + 3\",\"y = [[1|2]]x\",\"y = 4x − 7\"], a:0, e:\"m = [[9 − 1|6 − 2]] = 2. De 1 = 2(2) + b, on tire b = −3.\"},\n{p:\"Quelle est la pente de la droite d'équation 2x − 3y + 6 = 0 ?\", o:[\"[[2|3]]\",\"−[[2|3]]\",\"[[3|2]]\",\"2\"], a:0, e:\"On isole y : 3y = 2x + 6, donc y = [[2|3]]x + 2. La pente est [[2|3]].\"},\n{p:\"En quel point la droite d'équation [[x|4]] + [[y|3]] = 1 coupe-t-elle l'axe des y ?\", o:[\"(0, 3)\",\"(0, 4)\",\"(0, [[3|4]])\",\"(0, 12)\"], a:0, e:\"Dans la forme symétrique [[x|a]] + [[y|b]] = 1, b est l'ordonnée à l'origine. Ici b = 3.\"},\n{p:\"Lequel de ces points est dans la région y &gt; 2x − 1 (frontière exclue) ?\", o:[\"(0, 0)\",\"(1, 1)\",\"(2, 3)\",\"(0, −1)\"], a:0, e:\"Pour (0, 0) : 0 &gt; −1, vrai. Les autres points sont sur la droite : 1 = 1, 3 = 3 et −1 = −1, donc ils sont exclus.\"},\n{p:\"Lequel de ces points vérifie y ≤ x^{2} − 4 ?\", o:[\"(0, −5)\",\"(0, 0)\",\"(3, 6)\",\"(1, −2)\"], a:0, e:\"Pour (0, −5) : −5 ≤ −4, vrai. Pour (0, 0) : 0 ≤ −4 faux. Pour (3, 6) : 6 ≤ 5 faux. Pour (1, −2) : −2 ≤ −3 faux.\"},\n{p:\"Quelle région représente l'inéquation y ≥ 2x − 1 ?\", o:[\"Au-dessus de la droite, frontière incluse\",\"Au-dessous de la droite, frontière incluse\",\"Au-dessus de la droite, frontière exclue\",\"Au-dessous de la droite, frontière exclue\"], a:0, e:\"y ≥ signifie « au-dessus ». Le symbole ≥ inclut la frontière (trait plein).\"}\n]});\n\nCH.push({\nid:8, titre:\"Les systèmes d'équations\",\nresume:\"Comparaison, substitution, réduction, nombre de solutions, systèmes formés d'une droite et d'une parabole.\",\ncours:[\n{h:\"Comparaison et nombre de solutions d'un système du premier degré\", html:`\n<p><b>Comparaison :</b> isoler la même variable dans les deux équations, puis égaler les expressions.</p>\n<div class=\"ex\"><b>Exemple</b> y = 2x + 1 et y = −x + 7 : 2x + 1 = −x + 7, donc x = 2 et y = 5.</div>\n<ul>\n<li>Pentes différentes : une solution (droites sécantes).</li>\n<li>Même pente, ordonnées différentes : aucune solution (droites parallèles).</li>\n<li>Droites confondues : une infinité de solutions.</li>\n</ul>`},\n{h:\"La résolution par substitution\", html:`\n<p>Isoler une variable dans une équation et la remplacer dans l'autre.</p>\n<div class=\"ex\"><b>Exemple</b> y = 2x − 1 et 3x + y = 9 : 3x + 2x − 1 = 9, donc x = 2 et y = 3. Solution (2, 3).</div>`},\n{h:\"La résolution par réduction\", html:`\n<p>Additionner ou soustraire les équations (après avoir multiplié au besoin) pour éliminer une variable.</p>\n<div class=\"ex\"><b>Exemple</b> 2x + 3y = 12 et 4x − 3y = 6 : on additionne, 6x = 18, donc x = 3, puis y = 2.</div>`},\n{h:\"Les systèmes formés d'une équation du premier degré et d'une équation du second degré\", html:`\n<p>On égale les deux règles pour obtenir une équation du second degré en x, puis on calcule les y correspondants. Il y a 0, 1 ou 2 solutions.</p>\n<div class=\"ex\"><b>Exemple</b> y = x + 1 et y = x^{2} − 1 : x^{2} − x − 2 = 0, donc x = 2 ou x = −1. Points d'intersection : (2, 3) et (−1, 0).</div>`}\n],\nq:[\n{p:\"Résoudre le système x + y = 7 et x − y = 1.\", o:[\"(4, 3)\",\"(3, 4)\",\"(5, 2)\",\"(6, 1)\"], a:0, e:\"On additionne : 2x = 8, donc x = 4, puis y = 3.\"},\n{p:\"Résoudre y = 2x − 1 et 3x + y = 9.\", o:[\"(2, 3)\",\"(3, 2)\",\"(1, 1)\",\"(2, −3)\"], a:0, e:\"Par substitution : 3x + 2x − 1 = 9, donc x = 2 et y = 3.\"},\n{p:\"Résoudre 2x + 3y = 12 et 4x − 3y = 6.\", o:[\"(3, 2)\",\"(2, 3)\",\"(4, 1)\",\"(1, 4)\"], a:0, e:\"On additionne : 6x = 18, donc x = 3. Puis 2(3) + 3y = 12 donne y = 2.\"},\n{p:\"Combien de solutions possède le système 2x + 4y = 6 et x + 2y = 3 ?\", o:[\"Une infinité\",\"Aucune\",\"Une seule\",\"Deux\"], a:0, e:\"La première équation est le double de la seconde : les droites sont confondues.\"},\n{p:\"Combien de solutions possède 2x + y = 5 et 4x + 2y = 7 ?\", o:[\"Aucune\",\"Une\",\"Deux\",\"Une infinité\"], a:0, e:\"En divisant la seconde par 2 : 2x + y = 3,5. Même pente que la première, ordonnées différentes : droites parallèles.\"},\n{p:\"Quels sont les points d'intersection de y = x + 1 et y = x^{2} − 1 ?\", o:[\"(2, 3) et (−1, 0)\",\"(2, 3) seulement\",\"(−2, −1) et (1, 2)\",\"(−1, 0) et (1, 2)\"], a:0, e:\"x^{2} − 1 = x + 1 donne x^{2} − x − 2 = 0, soit x = 2 ou x = −1. Les ordonnées : y = 3 et y = 0.\"},\n{p:\"Deux cahiers et trois crayons coûtent 11 $. Un cahier et deux crayons coûtent 6 $. Quel est le prix d'un cahier ?\", o:[\"4 $\",\"3 $\",\"2 $\",\"5 $\"], a:0, e:\"c = 6 − 2k dans la seconde, puis 2(6 − 2k) + 3k = 11 donne k = 1 $ et c = 4 $.\"},\n{p:\"Deux nombres ont pour somme 10 et pour produit 21. Quels sont-ils ?\", o:[\"3 et 7\",\"2 et 8\",\"5 et 5\",\"1 et 9\"], a:0, e:\"Ce sont les solutions de t^{2} − 10t + 21 = 0, soit (t − 3)(t − 7) = 0.\"},\n{p:\"Un système formé d'une droite et d'une parabole a au plus combien de solutions ?\", o:[\"2\",\"1\",\"3\",\"4\"], a:0, e:\"L'équation obtenue est de degré 2 : elle a au plus 2 solutions.\"},\n{p:\"Deux nombres ont pour somme 15 et pour différence 3. Quel est le plus grand ?\", o:[\"9\",\"6\",\"12\",\"10\"], a:0, e:\"x + y = 15 et x − y = 3 donnent 2x = 18, donc x = 9.\"}\n]});\n\nCH.push({\nid:9, titre:\"La statistique\",\nresume:\"Distribution à deux caractères, corrélation linéaire, coefficient de corrélation, droite de régression.\",\ncours:[\n{h:\"La distribution à deux caractères et la corrélation linéaire\", html:`\n<p>On étudie deux variables mesurées sur les mêmes individus. Le <b>nuage de points</b> montre le lien entre elles.</p>\n<ul>\n<li><b>Corrélation positive :</b> le nuage monte de gauche à droite (y augmente avec x).</li>\n<li><b>Corrélation négative :</b> le nuage descend (y diminue quand x augmente).</li>\n<li><b>Corrélation nulle :</b> aucun alignement visible.</li>\n<li>Plus les points sont proches d'une droite, plus la corrélation est <b>forte</b>.</li>\n</ul>`},\n{h:\"Le coefficient de corrélation linéaire\", html:`\n<div class=\"formula\">\n<div>−1 ≤ r ≤ 1</div>\n</div>\n<ul>\n<li>Le signe de r donne le sens ; |r| donne la force.</li>\n<li>|r| proche de 1 : corrélation forte. |r| proche de 0 : corrélation faible ou nulle.</li>\n<li>r = 1 ou r = −1 : tous les points sont exactement alignés.</li>\n</ul>\n<p class=\"tip\">Corrélation n'est pas causalité : deux variables peuvent évoluer ensemble à cause d'un troisième facteur (variable cachée).</p>`},\n{h:\"La droite de régression\", html:`\n<p>La droite de régression y = ax + b résume la tendance du nuage. Sa pente a indique la variation moyenne de y quand x augmente de 1.</p>\n<ul>\n<li><b>Interpolation :</b> prédire à l'intérieur de l'étendue des données (assez fiable).</li>\n<li><b>Extrapolation :</b> prédire en dehors de cette étendue (risquée).</li>\n</ul>\n<div class=\"ex\"><b>Exemple</b> y = 2x + 3 : pour x = 5, y prévu = 2(5) + 3 = 13.</div>`}\n],\nq:[\n{p:\"Un nuage de points monte nettement de la gauche vers la droite. Quel type de corrélation observe-t-on ?\", o:[\"Positive\",\"Négative\",\"Nulle\",\"Impossible à dire\"], a:0, e:\"Quand y augmente avec x, la corrélation est positive.\"},\n{p:\"Un coefficient de corrélation vaut r = −0,92. Que peut-on conclure ?\", o:[\"La corrélation est forte et négative\",\"La corrélation est faible et négative\",\"La corrélation est forte et positive\",\"Il n'y a pas de corrélation\"], a:0, e:\"|r| est proche de 1 (corrélation forte) et le signe − indique que y diminue quand x augmente.\"},\n{p:\"Un coefficient de corrélation vaut r = 0,15. Que peut-on conclure ?\", o:[\"La corrélation linéaire est très faible\",\"La corrélation est forte et positive\",\"La corrélation est forte et négative\",\"Les points sont parfaitement alignés\"], a:0, e:\"|r| est proche de 0 : il n'y a presque pas de lien linéaire.\"},\n{p:\"Laquelle de ces valeurs ne peut pas être un coefficient de corrélation ?\", o:[\"1,2\",\"−0,8\",\"0\",\"−1\"], a:0, e:\"Un coefficient de corrélation est toujours compris entre −1 et 1.\"},\n{p:\"Les points (1, 2), (2, 4), (3, 6) et (4, 8) sont alignés sur y = 2x. Que vaut r ?\", o:[\"1\",\"2\",\"0\",\"−1\"], a:0, e:\"Points parfaitement alignés sur une droite croissante : r = 1.\"},\n{p:\"La droite de régression est y = 2x + 3. Quelle valeur de y prévoit-on pour x = 5 ?\", o:[\"13\",\"10\",\"15\",\"8\"], a:0, e:\"y = 2(5) + 3 = 13.\"},\n{p:\"La droite de régression passe par (0, 10) et (5, 35). Quelle est son équation ?\", o:[\"y = 5x + 10\",\"y = 7x + 10\",\"y = 5x + 35\",\"y = 10x + 5\"], a:0, e:\"Pente : [[35 − 10|5 − 0]] = 5. Ordonnée à l'origine : 10.\"},\n{p:\"Une droite de régression est y = −1,5x + 40. Que signifie la pente ?\", o:[\"Quand x augmente de 1, y diminue en moyenne de 1,5\",\"Quand x augmente de 1, y augmente en moyenne de 1,5\",\"Quand x vaut 0, y vaut −1,5\",\"Quand y augmente de 1, x diminue de 1,5\"], a:0, e:\"La pente est la variation moyenne de y pour une augmentation de 1 de x. Elle est négative : y diminue.\"},\n{p:\"Les données de x vont de 10 à 50. Prédire y pour x = 80 avec la droite de régression est :\", o:[\"Une extrapolation, moins fiable\",\"Une interpolation, très fiable\",\"Une interpolation, moins fiable\",\"Une extrapolation, très fiable\"], a:0, e:\"x = 80 est en dehors de l'étendue des données : c'est une extrapolation, donc risquée.\"},\n{p:\"Les ventes de crème glacée et les coups de soleil sont fortement corrélés. Quelle conclusion est la plus appropriée ?\", o:[\"Une variable cachée, la chaleur, peut expliquer les deux\",\"La crème glacée cause les coups de soleil\",\"Les coups de soleil causent les ventes de crème glacée\",\"Les données sont forcément fausses\"], a:0, e:\"Une corrélation n'implique pas une causalité. Il fait chaud : on achète plus de crème glacée et on attrape plus de coups de soleil.\"}\n]});\n\nwindow.CHP = window.CHP || {};\nCHP[1] = {\npieges:[\n{t:\"Le carré d'une somme n'est PAS la somme des carrés\",\n faux:\"(x + 3)^{2} = x^{2} + 9\",\n vrai:\"(x + 3)^{2} = (x + 3)(x + 3) = x^{2} + 6x + 9\",\n why:\"On a l'impression que l'exposant « entre » dans la parenthèse. Mais un carré, c'est deux fois la même parenthèse : il y a donc quatre produits à faire, dont le double produit 2 · x · 3.\",\n astuce:\"Test de 10 secondes : essayez x = 1. (1 + 3)^{2} = 16, mais 1^{2} + 9 = 10. Les deux côtés ne sont pas égaux, donc l'égalité est fausse.\"},\n{t:\"Le signe moins devant une parenthèse change TOUS les signes\",\n faux:\"5 − (x − 3) = 5 − x − 3\",\n vrai:\"5 − (x − 3) = 5 − x + 3 = 8 − x\",\n why:\"Le « − » devant la parenthèse veut dire « multiplier par −1 ». On l'applique à chaque terme, pas seulement au premier.\",\n astuce:\"Réécrivez −(…) comme (−1)(…) avant de distribuer. Le « − » devant −3 devient un « + ».\"},\n{t:\"Exposants : on additionne pour multiplier, on ne touche pas pour additionner\",\n faux:\"x^{2} · x^{3} = x^{6} &nbsp; et &nbsp; x^{2} + x^{3} = x^{5}\",\n vrai:\"x^{2} · x^{3} = x^{5} &nbsp; mais &nbsp; x^{2} + x^{3} reste x^{2} + x^{3}\",\n why:\"x^{2} · x^{3} = (x · x)(x · x · x) : cinq x au total, donc on additionne les exposants. Mais x^{2} + x^{3} n'est pas un produit : les deux termes ne sont pas semblables et ne se regroupent pas.\",\n astuce:\"Seuls les termes semblables (même lettre, même exposant) s'additionnent : 4x^{2} + 3x^{2} = 7x^{2}.\"},\n{t:\"On ne simplifie que des FACTEURS, jamais des termes\",\n faux:\"[[x + 6|6]] = x\",\n vrai:\"[[x + 6|6]] ne se simplifie pas. En revanche [[x^{2} + 2x|x]] = [[x(x + 2)|x]] = x + 2\",\n why:\"Barrer un nombre en haut et en bas n'est permis que s'il multiplie TOUT le numérateur et TOUT le dénominateur. Dans x + 6, le 6 est ajouté : il n'est pas un facteur.\",\n astuce:\"Avant de barrer, factorisez. Si le « candidat » à barrer n'est pas dans une multiplication, ne le barrez pas.\"},\n{t:\"Les valeurs interdites restent interdites, même après simplification\",\n faux:\"[[x + 2|x^{2} − 4]] = [[1|x − 2]] donc seule x = 2 est interdite\",\n vrai:\"Dénominateur de départ : x^{2} − 4 = (x − 2)(x + 2), donc x ≠ 2 et x ≠ −2\",\n why:\"Les restrictions se cherchent sur l'expression de départ. Après simplification, la valeur −2 « disparaît » de l'écriture, mais elle n'était pas permise au départ.\",\n astuce:\"Écrivez les restrictions AVANT de simplifier, au bord de la page.\"},\n{t:\"Division de polynômes : n'oubliez pas les « trous »\",\n faux:\"(x^{3} − 8) ÷ (x − 2) : on écrit x^{3} − 8 et on décale les colonnes\",\n vrai:\"On écrit x^{3} + 0x^{2} + 0x − 8. Quotient x^{2} + 2x + 4, reste 0\",\n why:\"Chaque puissance de x doit avoir sa colonne. Si un terme manque, on met un coefficient 0 pour garder les colonnes alignées.\",\n astuce:\"Rangez dans l'ordre décroissant des exposants, puis vérifiez : diviseur × quotient + reste doit redonner le polynôme de départ.\"}\n],\nq:[\n{p:\"Développer et réduire (x − 4)^{2}.\", o:[\"x^{2} − 8x + 16\",\"x^{2} − 16\",\"x^{2} + 16\",\"x^{2} − 8x − 16\"], a:0, e:\"Piège : le double produit. (x − 4)(x − 4) = x^{2} − 4x − 4x + 16 = x^{2} − 8x + 16. Test : pour x = 1, (−3)^{2} = 9 et 1 − 8 + 16 = 9.\"},\n{p:\"Développer et réduire 3 − 2(x − 5).\", o:[\"13 − 2x\",\"−2x − 7\",\"x − 5\",\"13 + 2x\"], a:0, e:\"Piège : l'ordre des opérations. On distribue d'abord : −2 · x = −2x et −2 · (−5) = +10. Donc 3 − 2x + 10 = 13 − 2x. On ne calcule pas 3 − 2 en premier.\"},\n{p:\"Simplifier 2x^{3} · x^{4}.\", o:[\"2x^{7}\",\"2x^{12}\",\"x^{7}\",\"5x^{7}\"], a:0, e:\"Piège : exposants et coefficients. Les exposants s'additionnent (3 + 4 = 7). Le coefficient 2 reste tel quel : 2 · 1 = 2.\"},\n{p:\"Laquelle de ces égalités est vraie pour toutes les valeurs permises de x ?\", o:[\"[[x^{2} + 3x|x]] = x + 3\",\"[[x + 3|3]] = x\",\"[[x^{2} + 4|4]] = x^{2}\",\"[[2x + 4|4]] = x + 1\"], a:0, e:\"Piège : barrer des termes. Seule la première se factorise : [[x(x + 3)|x]] = x + 3 (avec x ≠ 0). Dans les autres, le nombre barré est ajouté, pas multiplié : [[2x + 4|4]] = [[x + 2|2]], pas x + 1.\"},\n{p:\"Quelles sont les valeurs interdites de [[x + 2|x^{2} − 9]] ?\", o:[\"x = 3 et x = −3\",\"x = −2\",\"x = 9 et x = −9\",\"x = 3 seulement\"], a:0, e:\"Piège : chercher ce qui annule le DÉNOMINATEUR, pas le numérateur. x^{2} − 9 = (x − 3)(x + 3) s'annule en 3 et en −3.\"},\n{p:\"Quel est le reste de (x^{3} − 8) ÷ (x − 2) ?\", o:[\"0\",\"−8\",\"−16\",\"2\"], a:0, e:\"Piège : le signe de a dans le théorème du reste. Pour x − 2, a = +2. Le reste vaut P(2) = 8 − 8 = 0. (P(−2) = −16 serait pour x + 2.)\"},\n{p:\"Développer (2x + 3)^{2}.\", o:[\"4x^{2} + 12x + 9\",\"4x^{2} + 9\",\"2x^{2} + 12x + 9\",\"4x^{2} + 6x + 9\"], a:0, e:\"Piège : le double produit et le carré du coefficient. (2x)^{2} = 4x^{2} et 2 · 2x · 3 = 12x. Le dernier terme est 3^{2} = 9.\"},\n{p:\"Développer et réduire (x + 2)(x − 2) − (x − 1)^{2}.\", o:[\"2x − 5\",\"−2x − 5\",\"2x − 3\",\"−3\"], a:0, e:\"Piège : le moins devant la parenthèse. (x^{2} − 4) − (x^{2} − 2x + 1) = x^{2} − 4 − x^{2} + 2x − 1 = 2x − 5. Chaque terme de la deuxième parenthèse change de signe.\"},\n{p:\"Quel est le quotient et le reste de (2x^{3} − 3x^{2} + 5) ÷ (x − 1) ?\", o:[\"Q = 2x^{2} − x − 1 et R = 4\",\"Q = 2x^{2} − x − 1 et R = −4\",\"Q = 2x^{2} − 3x et R = 5\",\"Q = 2x^{2} − x + 1 et R = 6\"], a:0, e:\"Piège : le terme manquant. On écrit 2x^{3} − 3x^{2} + 0x + 5. Le reste vaut P(1) = 2 − 3 + 5 = 4. Vérification : (x − 1)(2x^{2} − x − 1) + 4 = 2x^{3} − 3x^{2} + 1 + 4 = 2x^{3} − 3x^{2} + 5.\"},\n{p:\"Un élève écrit : 4x^{2} · 3x^{3} = 12x^{6}. Quelle est son erreur ?\", o:[\"Les exposants s'additionnent : la bonne réponse est 12x^{5}\",\"Les coefficients doivent s'additionner : 7x^{6}\",\"Les exposants se multiplient : 12x^{6} est juste\",\"Il n'y a pas d'erreur\"], a:0, e:\"Piège : confondre multiplier les exposants (réservé à (x^{2})^{3}) et les additionner (produit de puissances de même base). 2 + 3 = 5, donc 12x^{5}.\"}\n]};\n\nCHP[2] = {\npieges:[\n{t:\"Cherchez TOUJOURS le facteur commun en premier\",\n faux:\"2x^{2} − 18 : « on ne peut rien faire »\",\n vrai:\"2x^{2} − 18 = 2(x^{2} − 9) = 2(x − 3)(x + 3)\",\n why:\"Les gros coefficients cachent des différences de carrés. En sortant 2, on retrouve une forme connue.\",\n astuce:\"Avant tout, posez-vous la question : « Y a-t-il un nombre ou une lettre dans tous les termes ? »\"},\n{t:\"Trinôme x^{2} + bx + c : le produit donne c, la somme donne b, et les SIGNES comptent\",\n faux:\"x^{2} − 5x + 6 = (x + 2)(x + 3)\",\n vrai:\"x^{2} − 5x + 6 = (x − 2)(x − 3), car (−2)(−3) = 6 et (−2) + (−3) = −5\",\n why:\"On cherche deux nombres de produit 6 ET de somme −5. Si c est positif, les deux nombres ont le même signe que b. Si c est négatif, ils ont des signes différents.\",\n astuce:\"Vérifiez toujours en redéveloppant : (x − 2)(x − 3) = x^{2} − 5x + 6. Si ça marche, c'est bon.\"},\n{t:\"Une somme de carrés ne se factorise pas\",\n faux:\"x^{2} + 9 = (x + 3)(x + 3)\",\n vrai:\"x^{2} + 9 ne se factorise pas dans ℝ. Mais x^{2} − 9 = (x − 3)(x + 3)\",\n why:\"(x + 3)^{2} = x^{2} + 6x + 9 : il y a un terme du milieu. Et (x − 3)(x + 3) donne bien x^{2} − 9 : les termes du milieu s'annulent grâce aux signes opposés.\",\n astuce:\"Différence de carrés = deux carrés avec un MOINS entre eux. Avec un plus, c'est impossible.\"},\n{t:\"Factorisez jusqu'au bout\",\n faux:\"x^{4} − 16 = (x^{2} − 4)(x^{2} + 4) et on s'arrête\",\n vrai:\"x^{4} − 16 = (x^{2} − 4)(x^{2} + 4) = (x − 2)(x + 2)(x^{2} + 4)\",\n why:\"Le facteur x^{2} − 4 est encore une différence de carrés. Une factorisation complète ne laisse aucun facteur qu'on peut encore décomposer.\",\n astuce:\"Regardez chaque facteur obtenu et demandez-vous : « Puis-je encore le casser ? »\"},\n{t:\"Produit = 0 est magique, produit = 10 ne l'est pas\",\n faux:\"x(x − 3) = 10 donc x = 10 ou x − 3 = 10\",\n vrai:\"x^{2} − 3x − 10 = 0, soit (x − 5)(x + 2) = 0, donc x = 5 ou x = −2\",\n why:\"La règle « un produit nul a un facteur nul » ne marche que si le produit vaut 0. Il faut d'abord ramener l'équation à la forme « = 0 ».\",\n astuce:\"Ordre à suivre : tout d'un côté, = 0, factoriser, annuler chaque facteur.\"},\n{t:\"Ne divisez jamais les deux côtés par x : vous perdez une solution\",\n faux:\"x^{2} = 3x donc x = 3\",\n vrai:\"x^{2} − 3x = 0, x(x − 3) = 0, donc x = 0 ou x = 3\",\n why:\"Diviser par x suppose que x ≠ 0. On fait disparaître la solution x = 0.\",\n astuce:\"Passez tout d'un côté et factorisez plutôt que diviser.\"},\n{t:\"Complétion du carré : ce qu'on ajoute, on le retire\",\n faux:\"x^{2} + 6x = (x + 3)^{2} + 9\",\n vrai:\"x^{2} + 6x = (x + 3)^{2} − 9\",\n why:\"(x + 3)^{2} = x^{2} + 6x + 9 contient 9 de trop. Pour retrouver x^{2} + 6x, il faut retirer 9.\",\n astuce:\"Le nombre à ajouter est (b ÷ 2)^{2}. Écrivez immédiatement « − (b ÷ 2)^{2} » pour compenser.\"}\n],\nq:[\n{p:\"Factoriser complètement 3x^{2} − 12.\", o:[\"3(x − 2)(x + 2)\",\"3(x^{2} − 4)\",\"(3x − 2)(x + 6)\",\"3(x − 2)^{2}\"], a:0, e:\"Piège : s'arrêter trop tôt. 3x^{2} − 12 = 3(x^{2} − 4), puis x^{2} − 4 est une différence de carrés : 3(x − 2)(x + 2).\"},\n{p:\"Factoriser x^{2} − 7x + 12.\", o:[\"(x − 3)(x − 4)\",\"(x + 3)(x + 4)\",\"(x − 2)(x − 6)\",\"(x − 1)(x − 12)\"], a:0, e:\"Piège : les signes. On cherche un produit de 12 et une somme de −7 : (−3) · (−4) = 12 et (−3) + (−4) = −7.\"},\n{p:\"Factoriser x^{2} + 2x − 15.\", o:[\"(x + 5)(x − 3)\",\"(x − 5)(x + 3)\",\"(x + 5)(x + 3)\",\"(x + 15)(x − 1)\"], a:0, e:\"Piège : le signe du plus grand nombre. Produit −15, somme +2 : +5 et −3 (5 − 3 = 2). L'inverse (−5 et 3) donnerait −2.\"},\n{p:\"Lequel de ces polynômes ne peut pas être factorisé dans ℝ ?\", o:[\"x^{2} + 25\",\"x^{2} − 25\",\"x^{2} + 10x + 25\",\"25 − x^{2}\"], a:0, e:\"Piège : la somme de carrés. x^{2} − 25 = (x − 5)(x + 5), x^{2} + 10x + 25 = (x + 5)^{2} et 25 − x^{2} = (5 − x)(5 + x). Mais x^{2} + 25 n'a aucune factorisation réelle.\"},\n{p:\"Résoudre x^{2} = 5x.\", o:[\"x = 0 ou x = 5\",\"x = 5\",\"x = 0\",\"x = 5 ou x = −5\"], a:0, e:\"Piège : diviser par x. x^{2} − 5x = 0, donc x(x − 5) = 0. Les solutions sont 0 et 5.\"},\n{p:\"Résoudre x(x − 3) = 10.\", o:[\"x = 5 ou x = −2\",\"x = 10 ou x = 13\",\"x = 5 ou x = 2\",\"x = −5 ou x = 2\"], a:0, e:\"Piège : produit égal à un nombre non nul. On développe : x^{2} − 3x − 10 = 0, soit (x − 5)(x + 2) = 0. Vérification : 5 · 2 = 10 et (−2)(−5) = 10.\"},\n{p:\"Factoriser complètement x^{4} − 81.\", o:[\"(x − 3)(x + 3)(x^{2} + 9)\",\"(x^{2} − 9)(x^{2} + 9)\",\"(x − 3)(x + 3)(x − 3)(x + 3)\",\"(x − 9)(x + 9)\"], a:0, e:\"Piège : arrêt prématuré. x^{4} − 81 = (x^{2} − 9)(x^{2} + 9), puis x^{2} − 9 = (x − 3)(x + 3). Le facteur x^{2} + 9 ne se décompose pas.\"},\n{p:\"Écrire x^{2} + 10x + 3 sous la forme (x − h)^{2} + k.\", o:[\"(x + 5)^{2} − 22\",\"(x + 5)^{2} + 22\",\"(x + 5)^{2} + 3\",\"(x + 10)^{2} − 97\"], a:0, e:\"Piège : compenser. (x + 5)^{2} = x^{2} + 10x + 25. On a ajouté 25 de trop : x^{2} + 10x + 3 = (x + 5)^{2} − 25 + 3 = (x + 5)^{2} − 22.\"},\n{p:\"Factoriser 2x^{2} + 7x + 3.\", o:[\"(2x + 1)(x + 3)\",\"(2x + 3)(x + 1)\",\"(x + 1)(x + 3)\",\"(2x − 1)(x − 3)\"], a:0, e:\"Piège : a ≠ 1. On vérifie par développement : (2x + 1)(x + 3) = 2x^{2} + 6x + x + 3 = 2x^{2} + 7x + 3. L'autre choix donne 2x^{2} + 5x + 3.\"},\n{p:\"Simplifier [[x^{2} − 9|x^{2} + 3x]] (avec x ≠ 0 et x ≠ −3).\", o:[\"[[x − 3|x]]\",\"−[[3|x]]\",\"[[x − 3|x + 3]]\",\"[[x + 3|x]]\"], a:0, e:\"Piège : factoriser avant de barrer. [[(x − 3)(x + 3)|x(x + 3)]] = [[x − 3|x]]. On ne peut pas barrer les x^{2} car ils sont des termes, pas des facteurs.\"}\n]};\n\nCHP[3] = {\npieges:[\n{t:\"Domaine ou image ? x ou y ?\",\n faux:\"Le domaine de f(x) = [[3|x − 5]] + 1 est ℝ \\\\ {1}\",\n vrai:\"Domaine : ℝ \\\\ {5} (le dénominateur s'annule en x = 5). Image : ℝ \\\\ {1}\",\n why:\"Le domaine regarde les valeurs de x permises. L'image regarde les valeurs de y atteintes. La valeur 1 est la hauteur de l'asymptote horizontale : elle touche l'image, pas le domaine.\",\n astuce:\"Domaine = « x : à l'horizontale ». Image = « y : à la verticale ».\"},\n{t:\"Le paramètre h joue à l'envers\",\n faux:\"g(x) = f(x − 3) déplace la courbe de 3 vers la gauche\",\n vrai:\"g(x) = f(x − 3) déplace la courbe de 3 vers la DROITE\",\n why:\"Pour que x − 3 vaille ce que valait x dans f, il faut que x soit 3 de plus. Exemple : le sommet de (x − 3)^{2} est en x = 3, car c'est là que x − 3 = 0.\",\n astuce:\"Cherchez ce qui annule la parenthèse : x − 3 = 0 donne x = 3, donc le centre est à 3.\"},\n{t:\"Le paramètre b joue aussi à l'envers\",\n faux:\"g(x) = f(2x) étire la courbe horizontalement par 2\",\n vrai:\"g(x) = f(2x) COMPRESSE horizontalement : chaque abscisse est divisée par 2\",\n why:\"Pour avoir la même valeur qu'avant, x n'a besoin que de la moitié. Si (4, 6) est sur f, alors f(2x) = 6 quand 2x = 4, donc x = 2 : le point (2, 6) est sur g.\",\n astuce:\"Verticalement, a multiplie les y. Horizontalement, b divise les x (facteur [[1|b]]).\"},\n{t:\"La partie entière des nombres négatifs recule\",\n faux:\"[−2,3] = −2\",\n vrai:\"[−2,3] = −3\",\n why:\"La partie entière est le plus grand entier inférieur ou égal au nombre. −3 ≤ −2,3, tandis que −2 est plus grand que −2,3, donc il ne convient pas.\",\n astuce:\"Sur une droite numérique, on recule vers la gauche jusqu'à l'entier le plus proche. Ce n'est pas un arrondi.\"},\n{t:\"Croissante n'est pas la même chose que positive\",\n faux:\"La fonction est négative, donc elle est décroissante\",\n vrai:\"On regarde la courbe de gauche à droite : si elle monte, la fonction est croissante, même si ses valeurs sont négatives\",\n why:\"La croissance parle de la direction de la courbe. Le signe parle de sa position par rapport à l'axe des x. Ce sont deux informations indépendantes.\",\n astuce:\"Croissance = « je monte ». Signe = « je suis au-dessus ou au-dessous de l'axe ».\"},\n{t:\"Valeur absolue : « plus petit que » enferme, « plus grand que » écarte\",\n faux:\"|x − 2| ≥ 3 donne −1 ≤ x ≤ 5\",\n vrai:\"|x − 2| ≥ 3 donne x ≤ −1 ou x ≥ 5. Et |x − 2| &lt; 3 donne −1 &lt; x &lt; 5\",\n why:\"|x − 2| mesure la distance entre x et 2. « Distance plus petite que 3 » = près de 2 (entre −1 et 5). « Distance plus grande que 3 » = loin de 2 (à l'extérieur).\",\n astuce:\"Dessinez la droite des nombres, placez 2 au centre et marquez 3 pas de chaque côté.\"}\n],\nq:[\n{p:\"Quel est le domaine de f(x) = [[3|x − 5]] + 1 ?\", o:[\"ℝ \\\\ {5}\",\"ℝ \\\\ {−5}\",\"ℝ \\\\ {1}\",\"ℝ\"], a:0, e:\"Piège : confondre domaine et image. Le dénominateur s'annule pour x = 5. La valeur 1 concerne y (asymptote horizontale).\"},\n{p:\"Quelle est l'image de f(x) = [[3|x − 5]] + 1 ?\", o:[\"ℝ \\\\ {1}\",\"ℝ \\\\ {5}\",\"ℝ\",\"]1, +∞[\"], a:0, e:\"Piège : domaine ou image. La fraction [[3|x − 5]] ne vaut jamais 0, donc f(x) ne vaut jamais 1. L'image est ℝ \\\\ {1}.\"},\n{p:\"La courbe de g(x) = f(x − 3) + 2 se déduit de celle de f par :\", o:[\"une translation de 3 vers la droite et de 2 vers le haut\",\"une translation de 3 vers la gauche et de 2 vers le haut\",\"une translation de 3 vers la droite et de 2 vers le bas\",\"une translation de 2 vers la droite et de 3 vers le haut\"], a:0, e:\"Piège : le signe de h. Dans x − 3, h = +3 : vers la droite. Le + 2 à l'extérieur déplace la courbe vers le haut.\"},\n{p:\"Le point (4, 6) est sur la courbe de f. Quel point est sur la courbe de g(x) = f(2x) ?\", o:[\"(2, 6)\",\"(8, 6)\",\"(4, 12)\",\"(4, 3)\"], a:0, e:\"Piège : b agit à l'envers. g(x) = 6 quand 2x = 4, donc x = 2. L'abscisse est divisée par 2.\"},\n{p:\"Le point (4, 6) est sur la courbe de f. Quel point est sur la courbe de g(x) = 2f(x − 1) ?\", o:[\"(5, 12)\",\"(3, 12)\",\"(5, 3)\",\"(8, 7)\"], a:0, e:\"Piège : a multiplie les y, h décale les x. x − 1 = 4 donne x = 5, et l'ordonnée devient 2 · 6 = 12.\"},\n{p:\"Que vaut [−0,5] + [0,5] ?\", o:[\"−1\",\"0\",\"1\",\"−0,5\"], a:0, e:\"Piège : partie entière d'un négatif. [−0,5] = −1 et [0,5] = 0. La somme vaut −1.\"},\n{p:\"Pour quelles valeurs de x a-t-on [x] = −2 ?\", o:[\"−2 ≤ x &lt; −1\",\"−3 &lt; x ≤ −2\",\"−2 &lt; x ≤ −1\",\"−2,5 ≤ x &lt; −1,5\"], a:0, e:\"Piège : le sens de l'intervalle. [−2] = −2 et [−1,9] = −2, mais [−1] = −1. L'intervalle est donc [−2, −1[ : fermé à gauche, ouvert à droite.\"},\n{p:\"Une fonction est négative sur [0, 3] et son graphique monte de gauche à droite. Laquelle de ces affirmations est vraie ?\", o:[\"Elle est négative et croissante\",\"Elle est négative donc décroissante\",\"Elle est positive et croissante\",\"Elle est constante\"], a:0, e:\"Piège : signe et croissance sont indépendants. La courbe monte (croissante) tout en restant au-dessous de l'axe des x (négative).\"},\n{p:\"Résoudre |x − 2| ≥ 3.\", o:[\"]−∞, −1] ∪ [5, +∞[\",\"[−1, 5]\",\"[5, +∞[\",\"]−∞, −1[ ∪ ]5, +∞[\"], a:0, e:\"Piège : « plus grand que » écarte, et ≥ inclut les bornes. |x − 2| ≥ 3 signifie x − 2 ≤ −3 ou x − 2 ≥ 3, soit x ≤ −1 ou x ≥ 5.\"},\n{p:\"Quelle est l'image de f(x) = −2|x − 3| + 5 ?\", o:[\"]−∞, 5]\",\"[5, +∞[\",\"]−∞, 3]\",\"ℝ\"], a:0, e:\"Piège : le signe de a. |x − 3| ≥ 0, donc −2|x − 3| ≤ 0 et f(x) ≤ 5. Le sommet (3, 5) est un maximum. L'image est ]−∞, 5].\"}\n]};\n\nwindow.CHP = window.CHP || {};\nCHP[4] = {\npieges:[\n{t:\"Le sommet : le h change de signe, le k non\",\n faux:\"f(x) = 3(x + 4)^{2} − 1 a pour sommet (4, −1)\",\n vrai:\"Sommet (−4, −1), car x + 4 = x − (−4)\",\n why:\"La forme canonique est a(x − h)^{2} + k. Un « + 4 » dans la parenthèse veut dire h = −4. Le k, lui, se lit tel quel.\",\n astuce:\"Cherchez la valeur de x qui annule la parenthèse : x + 4 = 0 donne x = −4.\"},\n{t:\"Axe de symétrie : −b ÷ 2a, pas −b\",\n faux:\"f(x) = x^{2} − 6x + 4 : l'axe est x = 6 ou x = −3\",\n vrai:\"h = −[[b|2a]] = −[[−6|2]] = 3. Axe de symétrie : x = 3\",\n why:\"Deux oublis fréquents : oublier de diviser par 2a, ou oublier le signe moins devant b. Ici b est déjà négatif, donc −b est positif.\",\n astuce:\"Le sommet est au milieu des deux zéros. Si les zéros sont 1 et 5, l'axe est x = 3.\"},\n{t:\"Maximum ou minimum ? Regardez le signe de a\",\n faux:\"Image de −2(x − 1)^{2} + 7 : [7, +∞[\",\n vrai:\"a &lt; 0, la parabole s'ouvre vers le bas : maximum 7, image ]−∞, 7]\",\n why:\"Si a &gt; 0, la parabole « sourit » : le sommet est un minimum. Si a &lt; 0, elle « fait la moue » : le sommet est un maximum.\",\n astuce:\"Dessinez un croquis de 5 secondes avant de répondre. La bonne image se voit.\"},\n{t:\"Zéros, ordonnée à l'origine : deux questions différentes\",\n faux:\"Pour f(x) = 2(x − 3)^{2} − 4, l'ordonnée à l'origine est −4\",\n vrai:\"On calcule f(0) = 2(−3)^{2} − 4 = 14. Le −4 est le k, l'ordonnée du sommet\",\n why:\"L'ordonnée à l'origine se trouve en remplaçant x par 0. Les zéros se trouvent en posant f(x) = 0. Le sommet se lit dans la forme canonique.\",\n astuce:\"Trois questions, trois outils : « Où coupe-t-elle l'axe y ? » → x = 0. « Où coupe-t-elle l'axe x ? » → f(x) = 0. « Où est le sommet ? » → (h, k).\"},\n{t:\"Complétion du carré avec a ≠ 1 : sortez a d'abord\",\n faux:\"2x^{2} + 8x + 3 = 2(x + 2)^{2} + 3\",\n vrai:\"2x^{2} + 8x + 3 = 2(x^{2} + 4x) + 3 = 2[(x + 2)^{2} − 4] + 3 = 2(x + 2)^{2} − 5\",\n why:\"Ce qu'on compense à l'intérieur de la parenthèse (−4) est multiplié par a (2) quand on sort de la parenthèse : −8, puis + 3 donne −5.\",\n astuce:\"Vérifiez en redéveloppant : 2(x + 2)^{2} − 5 = 2x^{2} + 8x + 8 − 5. Oui !\"},\n{t:\"Inéquation du 2e degré : dessinez la parabole, ne devinez pas\",\n faux:\"x^{2} − x − 6 ≤ 0 donne x ≤ −2 ou x ≥ 3\",\n vrai:\"Zéros −2 et 3. Parabole vers le haut, donc ≤ 0 entre les zéros : [−2, 3]\",\n why:\"Avec a &gt; 0, la parabole est au-dessous de l'axe (valeurs négatives) entre les zéros et au-dessus à l'extérieur. Avec ≤ ou ≥, les zéros sont inclus.\",\n astuce:\"Trouvez les zéros, esquissez la parabole, puis colorez la partie qui répond au signe demandé.\"},\n{t:\"Problèmes de ballon, de profit, de pont : quand ou combien ?\",\n faux:\"Hauteur maximale = la valeur de t du sommet\",\n vrai:\"Le sommet (h, k) répond à deux questions : h = QUAND, k = COMBIEN\",\n why:\"En contexte, h est la valeur de la variable indépendante (temps, prix, quantité) et k est la valeur maximale (hauteur, profit…). Ne pas les mélanger.\",\n astuce:\"Relisez la question et entourez le mot qui commence par « Quand », « À quel… » (h) ou « Quelle est la valeur… » (k).\"}\n],\nq:[\n{p:\"Quel est le sommet de f(x) = 3(x + 4)^{2} − 1 ?\", o:[\"(−4, −1)\",\"(4, −1)\",\"(−4, 1)\",\"(3, −1)\"], a:0, e:\"Piège : le signe de h. x + 4 = x − (−4), donc h = −4. Le k = −1 se lit tel quel.\"},\n{p:\"Quelle est l'équation de l'axe de symétrie de f(x) = x^{2} − 6x + 4 ?\", o:[\"x = 3\",\"x = −3\",\"x = 6\",\"x = −5\"], a:0, e:\"Piège : oublier 2a. h = −[[b|2a]] = −[[−6|2]] = 3. (6 serait −b sans diviser par 2.)\"},\n{p:\"Quelle est l'image de f(x) = −2(x − 1)^{2} + 7 ?\", o:[\"]−∞, 7]\",\"[7, +∞[\",\"]−∞, 1]\",\"[1, +∞[\"], a:0, e:\"Piège : le signe de a. a = −2 &lt; 0 : la parabole s'ouvre vers le bas, le sommet (1, 7) est un maximum. L'image est ]−∞, 7].\"},\n{p:\"Quelle est l'ordonnée à l'origine de f(x) = 2(x − 3)^{2} − 4 ?\", o:[\"14\",\"−4\",\"18\",\"−10\"], a:0, e:\"Piège : confondre k et f(0). f(0) = 2(0 − 3)^{2} − 4 = 2 · 9 − 4 = 14. (Le −4 est l'ordonnée du sommet.)\"},\n{p:\"Quels sont les zéros de f(x) = (x − 2)(x + 5) ?\", o:[\"2 et −5\",\"−2 et 5\",\"2 et 5\",\"−10\"], a:0, e:\"Piège : le signe. x − 2 = 0 donne x = 2 et x + 5 = 0 donne x = −5.\"},\n{p:\"Écrire 2x^{2} + 8x + 3 sous la forme canonique.\", o:[\"2(x + 2)^{2} − 5\",\"2(x + 2)^{2} + 3\",\"2(x + 4)^{2} − 29\",\"2(x + 2)^{2} − 1\"], a:0, e:\"Piège : sortir a avant de compléter. 2(x^{2} + 4x) + 3 = 2[(x + 2)^{2} − 4] + 3 = 2(x + 2)^{2} − 8 + 3 = 2(x + 2)^{2} − 5.\"},\n{p:\"Résoudre x^{2} − x − 6 ≤ 0.\", o:[\"[−2, 3]\",\"]−2, 3[\",\"]−∞, −2] ∪ [3, +∞[\",\"[−3, 2]\"], a:0, e:\"Piège : le sens et les bornes. x^{2} − x − 6 = (x − 3)(x + 2), zéros 3 et −2. Parabole vers le haut : ≤ 0 entre les zéros, bornes incluses.\"},\n{p:\"La hauteur d'un ballon est h(t) = −5t^{2} + 20t (h en mètres, t en secondes). Quelle est la hauteur maximale et à quel moment est-elle atteinte ?\", o:[\"20 m après 2 s\",\"2 m après 20 s\",\"20 m après 4 s\",\"40 m après 2 s\"], a:0, e:\"Piège : mélanger h et k. t du sommet = −[[20|2(−5)]] = 2 s. La hauteur maximale est h(2) = −20 + 40 = 20 m. (4 s est le moment où le ballon retombe.)\"},\n{p:\"Une parabole a pour sommet (2, −3) et passe par (0, 1). Quelle est sa règle ?\", o:[\"f(x) = (x − 2)^{2} − 3\",\"f(x) = (x + 2)^{2} − 3\",\"f(x) = 2(x − 2)^{2} − 3\",\"f(x) = (x − 2)^{2} + 3\"], a:0, e:\"Piège : a et le signe de h. f(x) = a(x − 2)^{2} − 3. Avec (0, 1) : 1 = 4a − 3, donc a = 1.\"},\n{p:\"Combien de zéros possède f(x) = x^{2} − 4x + 9 ?\", o:[\"Aucun\",\"Un\",\"Deux\",\"On ne peut pas le savoir\"], a:0, e:\"Piège : ne pas chercher le sommet. f(x) = (x − 2)^{2} + 5. Le minimum 5 est positif : la courbe ne touche jamais l'axe des x. (Discriminant : 16 − 36 &lt; 0.)\"}\n]};\n\nCHP[5] = {\npieges:[\n{t:\"Les aires changent au CARRÉ, les volumes au CUBE\",\n faux:\"Si les longueurs sont multipliées par 3, l'aire est multipliée par 3\",\n vrai:\"Longueurs × 3, aires × 3^{2} = 9, volumes × 3^{3} = 27\",\n why:\"On a l'impression que tout « grandit au même rythme ». Mais une aire a deux dimensions (largeur et hauteur grandissent) et un volume en a trois. Les chercheurs appellent ça « l'illusion de linéarité » : c'est l'erreur la plus classique en géométrie.\",\n astuce:\"Dessinez un carré de côté 1 puis de côté 2 : il y a 4 petits carrés dans le grand. Pas 2.\"},\n{t:\"Bien apparier les côtés homologues\",\n faux:\"On divise deux côtés qui « se ressemblent » sans vérifier\",\n vrai:\"Les côtés homologues sont ceux qui sont opposés à des angles égaux (le plus petit avec le plus petit, le plus grand avec le plus grand)\",\n why:\"Dans ABC ∼ DEF, l'ordre des lettres dit tout : AB correspond à DE, BC correspond à EF, AC correspond à DF.\",\n astuce:\"Écrivez d'abord le rapport k avec deux côtés CONNUS, puis multipliez : côté image = k × côté initial.\"},\n{t:\"Additionner n'est pas agrandir\",\n faux:\"AB = 4 devient DE = 6, donc on ajoute 2 : BC = 6 devient EF = 8\",\n vrai:\"k = 6 ÷ 4 = 1,5, donc EF = 6 × 1,5 = 9\",\n why:\"Un agrandissement multiplie toutes les longueurs par le même nombre. Il ne leur ajoute pas la même quantité.\",\n astuce:\"« Fois k, pas plus k. »\"},\n{t:\"Semblable ≠ isométrique (AAA ne suffit pas)\",\n faux:\"Deux triangles ont leurs trois angles égaux : ils sont isométriques\",\n vrai:\"Ils sont semblables. Pour être isométriques, il faut au moins un côté égal (CCC, CAC ou ACA)\",\n why:\"Une photo et son agrandissement ont les mêmes angles, mais pas la même taille.\",\n astuce:\"Isométrique = « même forme ET même taille » (k = 1). Semblable = « même forme ».\"},\n{t:\"Pythagore et les relations métriques : seulement dans un triangle RECTANGLE\",\n faux:\"6, 8 et 11 : 6^{2} + 8^{2} ≈ 11^{2}, donc le triangle est rectangle\",\n vrai:\"6^{2} + 8^{2} = 100 mais 11^{2} = 121. Ce n'est pas égal : le triangle n'est pas rectangle\",\n why:\"La relation a^{2} = b^{2} + c^{2} doit être EXACTEMENT vraie. Elle ne tolère pas « à peu près ».\",\n astuce:\"Dans les relations métriques, h^{2} = m · n : ce n'est pas la moyenne de m et n, et ce n'est pas la moitié de l'hypoténuse.\"},\n{t:\"Conversion d'unités d'aire : 1 m^{2} = 10 000 cm^{2}\",\n faux:\"3 m^{2} = 300 cm^{2}\",\n vrai:\"3 m^{2} = 3 × 100 × 100 = 30 000 cm^{2}\",\n why:\"1 m = 100 cm. Pour l'aire, il y a deux longueurs : on multiplie par 100 deux fois (100^{2} = 10 000). Pour un volume, trois fois (100^{3} = 1 000 000).\",\n astuce:\"Pour les aires, le facteur de conversion s'élève au carré. Pour les volumes, au cube.\"}\n],\nq:[\n{p:\"Un triangle a une aire de 12 cm^{2}. On l'agrandit avec un rapport de similitude k = 3. Quelle est l'aire du nouveau triangle ?\", o:[\"108 cm^{2}\",\"36 cm^{2}\",\"324 cm^{2}\",\"15 cm^{2}\"], a:0, e:\"Piège : l'aire est multipliée par k^{2} = 9. 12 × 9 = 108 cm^{2}.\"},\n{p:\"Une maquette à l'échelle 1 : 10 a un volume de 3 L. Quel est le volume réel ?\", o:[\"3 000 L\",\"30 L\",\"300 L\",\"30 000 L\"], a:0, e:\"Piège : le volume est multiplié par k^{3} = 10^{3} = 1 000. 3 × 1 000 = 3 000 L.\"},\n{p:\"Deux triangles semblables ont des aires de 20 cm^{2} et de 45 cm^{2}. Quel est le rapport de similitude (grand sur petit) ?\", o:[\"1,5\",\"2,25\",\"25\",\"3\"], a:0, e:\"Piège : le rapport des aires est k^{2}. [[45|20]] = 2,25 = k^{2}, donc k = √{2,25} = 1,5.\"},\n{p:\"ABC ∼ DEF avec AB = 4, BC = 6, AC = 8 et DE = 6. Quelle est la longueur de EF ?\", o:[\"9\",\"8\",\"12\",\"4\"], a:0, e:\"Piège : additionner au lieu de multiplier. k = [[6|4]] = 1,5. EF correspond à BC : 6 × 1,5 = 9.\"},\n{p:\"Lequel de ces cas ne suffit PAS à prouver que deux triangles sont isométriques ?\", o:[\"Trois angles homologues égaux\",\"Trois côtés homologues égaux (CCC)\",\"Deux côtés et l'angle compris égaux (CAC)\",\"Deux angles et le côté compris égaux (ACA)\"], a:0, e:\"Piège : AAA prouve seulement la similitude. Deux triangles peuvent avoir les mêmes angles et des tailles différentes.\"},\n{p:\"Dans un triangle rectangle, les cathètes mesurent 9 et 12. Quelle est la longueur de la hauteur issue de l'angle droit ?\", o:[\"7,2\",\"7,5\",\"21\",\"108\"], a:0, e:\"Piège : confondre avec la moitié de l'hypoténuse (7,5). L'hypoténuse vaut 15 et b · c = a · h donne h = [[9 × 12|15]] = 7,2.\"},\n{p:\"La hauteur h d'un triangle rectangle partage l'hypoténuse en segments de 4 et de 9. Quelle est la valeur de h ?\", o:[\"6\",\"6,5\",\"13\",\"36\"], a:0, e:\"Piège : prendre la moyenne. h^{2} = m · n = 4 × 9 = 36, donc h = 6.\"},\n{p:\"Une aire de 3 m^{2} est égale à combien de cm^{2} ?\", o:[\"30 000 cm^{2}\",\"300 cm^{2}\",\"3 000 cm^{2}\",\"300 000 cm^{2}\"], a:0, e:\"Piège : conversion d'aire. 1 m^{2} = 100 × 100 = 10 000 cm^{2}. 3 × 10 000 = 30 000.\"},\n{p:\"Un triangle a pour côtés 6, 8 et 11. Est-il rectangle ?\", o:[\"Non, car 6^{2} + 8^{2} = 100 ≠ 121\",\"Oui, car 6 + 8 &gt; 11\",\"Oui, car 6^{2} + 8^{2} est proche de 11^{2}\",\"Non, car 11 est impair\"], a:0, e:\"Piège : « presque » ne compte pas. Pour être rectangle, il faut a^{2} = b^{2} + c^{2} exactement, avec l'hypoténuse la plus longue : 100 ≠ 121.\"},\n{p:\"Un carré de côté 6 est équivalent à un triangle de base 12. Quelle est la hauteur du triangle ?\", o:[\"6\",\"3\",\"12\",\"24\"], a:0, e:\"Piège : oublier le ½. Aire du carré = 36. Pour le triangle : [[12 × h|2]] = 36, donc 6h = 36 et h = 6.\"}\n]};\n\nCHP[6] = {\npieges:[\n{t:\"Opposé et adjacent dépendent de l'angle choisi\",\n faux:\"Le côté « en haut » est toujours l'opposé\",\n vrai:\"Opposé = en face de l'angle. Adjacent = collé à l'angle (sans être l'hypoténuse). Si on change d'angle, les rôles s'échangent\",\n why:\"Les mots « opposé » et « adjacent » ne décrivent pas la position du côté dans la page, mais sa relation avec l'angle utilisé.\",\n astuce:\"Marquez l'angle d'un arc, puis étiquetez : hypoténuse (en face de 90°), opposé (en face de l'angle), adjacent (le reste). Seulement après, choisissez SOH-CAH-TOA.\"},\n{t:\"Calculatrice en mode DEGRÉS\",\n faux:\"sin 30 = −0,988 (calculatrice en radians)\",\n vrai:\"sin 30° = 0,5 (mode DEG)\",\n why:\"La calculatrice peut mesurer les angles en degrés (DEG) ou en radians (RAD). En radians, sin 30 signifie « sinus de 30 radians ».\",\n astuce:\"Avant chaque examen : calculez sin 30. Si vous n'obtenez pas 0,5, changez de mode. Pas de pitié pour cette erreur : elle fait perdre des points entiers.\"},\n{t:\"Chercher un côté ou chercher un angle ? Deux outils différents\",\n faux:\"Pour trouver l'angle, on calcule 1 ÷ tan\",\n vrai:\"On utilise la touche réciproque : θ = tan^{−1}([[7|10]])\",\n why:\"sin^{−1}, cos^{−1} et tan^{−1} (appelées « inverses » sur la calculatrice) retrouvent l'angle à partir du rapport. Elles n'ont rien à voir avec 1 ÷ sin, 1 ÷ cos ou 1 ÷ tan.\",\n astuce:\"Côté cherché ? On multiplie ou divise. Angle cherché ? On utilise « 2nde/shift » puis sin, cos ou tan.\"},\n{t:\"Loi des sinus : relier un angle à son côté OPPOSÉ\",\n faux:\"b ÷ sin A = a ÷ sin B (côtés croisés)\",\n vrai:\"[[a|sin A]] = [[b|sin B]] : chaque côté avec l'angle en face de lui\",\n why:\"La loi des sinus ne fonctionne que si on associe chaque côté à son angle opposé. Un côté croisé donne un résultat faux, et on ne s'en rend pas compte.\",\n astuce:\"Écrivez les « couples » (A, a), (B, b), (C, c) avant de commencer. Un couple complet sert de référence.\"},\n{t:\"Loi des cosinus : tout le −2bc cos A passe AVANT la racine\",\n faux:\"a^{2} = (b^{2} + c^{2} − 2bc) · cos A\",\n vrai:\"a^{2} = b^{2} + c^{2} − (2bc · cos A). On calcule d'abord 2bc cos A, on soustrait, puis on prend la racine carrée\",\n why:\"Le cosinus ne multiplie QUE le terme 2bc. Et on n'oublie pas la racine carrée à la fin : on a trouvé a^{2}, pas a.\",\n astuce:\"Écrivez le calcul en trois lignes : produit 2bc cos A, soustraction, racine. Et pour un angle obtus, cos A est négatif, donc −2bc cos A devient positif.\"},\n{t:\"Chercher un angle obtus avec la loi des cosinus\",\n faux:\"cos C = −0,37 donc C = cos^{−1}(0,37) ≈ 68°\",\n vrai:\"cos^{−1}(−0,37) ≈ 112° : on garde le signe négatif, donc l'angle est obtus\",\n why:\"Un cosinus négatif correspond à un angle obtus (plus de 90°). Perdre le signe change complètement la réponse.\",\n astuce:\"Si le plus grand côté est « très long », l'angle en face de lui est probablement obtus : vérifiez que votre réponse dépasse 90°.\"}\n],\nq:[\n{p:\"Dans un triangle rectangle, le côté opposé à θ mesure 5, le côté adjacent 12 et l'hypoténuse 13. Que vaut tan θ ?\", o:[\"[[5|12]]\",\"[[5|13]]\",\"[[12|5]]\",\"[[12|13]]\"], a:0, e:\"Piège : confondre les rapports. tan θ = [[opposé|adjacent]] = [[5|12]]. (sin θ = [[5|13]] et cos θ = [[12|13]].)\"},\n{p:\"Un angle de 40° et une hypoténuse de 20 cm : quelle est la longueur du côté opposé à l'angle ?\", o:[\"12,9 cm\",\"15,3 cm\",\"31,1 cm\",\"16,8 cm\"], a:0, e:\"Piège : choisir le bon rapport. sin 40° = [[opposé|20]], donc opposé = 20 sin 40° ≈ 12,9. (15,3 vient de cos, 16,8 de tan, 31,1 d'une division.)\"},\n{p:\"Dans un triangle rectangle, le côté opposé à l'angle θ mesure 7 et le côté adjacent mesure 10. Que vaut θ ?\", o:[\"35,0°\",\"55,0°\",\"44,4°\",\"45,6°\"], a:0, e:\"Piège : bon rapport et bonne touche. tan θ = [[7|10]] = 0,7, donc θ = tan^{−1}(0,7) ≈ 35,0°. (55,0° est l'autre angle aigu ; 44,4° et 45,6° viennent de sin^{−1} et cos^{−1}.)\"},\n{p:\"Votre calculatrice affiche sin 30 = −0,988. Que s'est-il passé ?\", o:[\"Elle est en mode radians : il faut passer en degrés (sin 30° = 0,5)\",\"Le résultat est correct car 30 est un grand angle\",\"Il faut utiliser sin^{−1} à la place de sin\",\"L'angle est obtus, ce qui explique le signe négatif\"], a:0, e:\"Piège : le mode. En radians, la calculatrice calcule sin(30 rad). Passez en mode DEG pour obtenir 0,5.\"},\n{p:\"Dans ABC, A = 50°, B = 70° et a = 12. Quelle est la longueur de b ?\", o:[\"14,7\",\"9,8\",\"11,3\",\"8,6\"], a:0, e:\"Piège : associer chaque côté à son angle opposé. [[b|sin 70°]] = [[12|sin 50°]], donc b = [[12 sin 70°|sin 50°]] ≈ 14,7. (9,8 vient d'un couple inversé.)\"},\n{p:\"Dans ABC, a = 9, b = 12 et C = 50°. Quelle est la longueur de c ?\", o:[\"9,3\",\"86,2\",\"2,4\",\"19,1\"], a:0, e:\"Piège : la racine carrée finale et la priorité des opérations. c^{2} = 81 + 144 − 2(9)(12) cos 50° ≈ 86,16, donc c ≈ 9,3. (86,2 oublie la racine ; 2,4 multiplie tout par cos ; 19,1 additionne au lieu de soustraire.)\"},\n{p:\"Un triangle a pour côtés 5, 7 et 10. Quelle est la mesure de l'angle opposé au côté de 10 ?\", o:[\"111,8°\",\"68,2°\",\"40,5°\",\"28,7°\"], a:0, e:\"Piège : le signe du cosinus. cos C = [[25 + 49 − 100|2(5)(7)]] = −0,371. Donc C = cos^{−1}(−0,371) ≈ 111,8°. (68,2° ignore le signe moins. 40,5° vient d'un sin^{−1}, qui ne donne que des angles aigus.)\"},\n{p:\"Quelle est l'aire d'un triangle dont deux côtés mesurent 6 et 9 et dont l'angle compris est de 40° ?\", o:[\"17,4\",\"20,7\",\"34,7\",\"27,0\"], a:0, e:\"Piège : oublier le ½ ou confondre sin et cos. Aire = [[1|2]] · 6 · 9 · sin 40° ≈ 17,4. (34,7 oublie le ½ ; 20,7 utilise cos.)\"},\n{p:\"Un observateur se trouve à 45 m d'un édifice. L'angle d'élévation du sommet est de 32°. Quelle est la hauteur de l'édifice (au dixième près) ?\", o:[\"28,1 m\",\"23,8 m\",\"72,0 m\",\"38,2 m\"], a:0, e:\"Piège : choisir le rapport. On connaît l'adjacent (45) et cherche l'opposé : tan 32° = [[h|45]], donc h = 45 tan 32° ≈ 28,1 m.\"},\n{p:\"On connaît les trois côtés d'un triangle quelconque et on cherche un angle. Quel outil convient ?\", o:[\"La loi des cosinus\",\"La loi des sinus\",\"Le théorème de Pythagore\",\"Le rapport tan = opposé ÷ adjacent\"], a:0, e:\"Piège : choisir la bonne loi. La loi des sinus demande un angle et son côté opposé connus. Avec trois côtés et aucun angle, on utilise la loi des cosinus. Pythagore et tan exigent un triangle rectangle.\"}\n]};\n\nwindow.CHP = window.CHP || {};\nCHP[7] = {\npieges:[\n{t:\"Pente : même ordre en haut et en bas\",\n faux:\"Entre (1, 2) et (4, 8) : [[8 − 2|1 − 4]] = −2\",\n vrai:\"[[8 − 2|4 − 1]] = [[6|3]] = 2\",\n why:\"Si on commence par un point en haut de la fraction, on doit commencer par le MÊME point en bas. Mélanger l'ordre change le signe.\",\n astuce:\"Faites un contrôle visuel : la droite monte de gauche à droite ? La pente est positive. Elle descend ? Elle est négative.\"},\n{t:\"Perpendiculaire : opposée ET inversée\",\n faux:\"Perpendiculaire à y = [[2|3]]x + 1 : pente [[3|2]] (ou −[[2|3]])\",\n vrai:\"Pente −[[3|2]], car [[2|3]] · (−[[3|2]]) = −1\",\n why:\"Il faut deux changements : on inverse la fraction ET on change le signe. Un seul changement ne suffit pas.\",\n astuce:\"Vérifiez en multipliant les deux pentes : le produit doit valoir exactement −1.\"},\n{t:\"Distance : on n'oublie pas la racine carrée\",\n faux:\"Entre (−1, 2) et (4, 14) : d = 5 + 12 = 17, ou d = 169\",\n vrai:\"d = √{5^{2} + 12^{2}} = √{169} = 13\",\n why:\"La formule vient du théorème de Pythagore : les écarts horizontal et vertical sont les deux cathètes, la distance est l'hypoténuse.\",\n astuce:\"Dessinez un petit triangle rectangle entre les deux points, puis appliquez Pythagore.\"},\n{t:\"Trouver b : on remplace x et y par un point, puis on isole b\",\n faux:\"Droite de pente −2 passant par (2, 3) : y = −2x + 3\",\n vrai:\"3 = −2(2) + b donc b = 7 et y = −2x + 7\",\n why:\"Le b de y = mx + b est l'ordonnée à l'origine, pas l'ordonnée du point donné.\",\n astuce:\"Contrôle : remplacez x = 2 dans votre équation. Vous devez retrouver y = 3.\"},\n{t:\"Diviser par un nombre négatif retourne l'inégalité\",\n faux:\"−2y &gt; 6 donne y &gt; −3\",\n vrai:\"−2y &gt; 6 donne y &lt; −3\",\n why:\"Multiplier ou diviser les deux côtés par un nombre négatif inverse l'ordre : −10 &lt; 4 mais 5 &gt; −2 après division par −2.\",\n astuce:\"Testez un nombre : y = −5 est dans y &lt; −3. Vérifiez : −2(−5) = 10 et 10 &gt; 6, vrai. Avec y = 0 : 0 &gt; 6 est faux, donc 0 n'est pas une solution.\"},\n{t:\"Frontière pleine ou pointillée, région au-dessus ou au-dessous\",\n faux:\"On colorie au hasard, et on trace toujours un trait plein\",\n vrai:\"≤ ou ≥ : trait plein (frontière incluse). &lt; ou &gt; : pointillé. Puis on teste (0, 0)\",\n why:\"Une inéquation stricte n'inclut jamais les points de la frontière. Le test d'un point (souvent l'origine) indique quel côté colorier.\",\n astuce:\"Si la frontière passe par l'origine, testez un autre point, comme (1, 0) ou (0, 1).\"},\n{t:\"Inéquation du 2e degré à deux variables : testez, ne devinez pas\",\n faux:\"(2, 0) est solution de y &gt; x^{2} − 4\",\n vrai:\"0 &gt; 0 est faux : (2, 0) est SUR la parabole, donc exclu\",\n why:\"Les points sur la frontière ne sont solutions que si l'inégalité est large (≤ ou ≥).\",\n astuce:\"Remplacez les deux coordonnées et calculez les deux côtés avant de conclure.\"}\n],\nq:[\n{p:\"Quelle est la pente de la droite passant par (−3, 4) et (3, −8) ?\", o:[\"−2\",\"2\",\"−[[1|2]]\",\"[[1|2]]\"], a:0, e:\"Piège : l'ordre et les signes. m = [[−8 − 4|3 − (−3)]] = [[−12|6]] = −2. La droite descend : pente négative.\"},\n{p:\"Quelle est l'équation de la droite parallèle à y = −3x + 2 passant par (2, −1) ?\", o:[\"y = −3x + 5\",\"y = −3x − 1\",\"y = [[1|3]]x − [[5|3]]\",\"y = 3x − 7\"], a:0, e:\"Piège : pente et ordonnée. Même pente −3. −1 = −3(2) + b donne b = 5.\"},\n{p:\"Quelle est la pente d'une droite perpendiculaire à y = [[2|3]]x + 1 ?\", o:[\"−[[3|2]]\",\"[[3|2]]\",\"−[[2|3]]\",\"[[2|3]]\"], a:0, e:\"Piège : un seul changement. Il faut inverser ET changer le signe : [[2|3]] · (−[[3|2]]) = −1.\"},\n{p:\"Quelle est la distance entre A(−1, 2) et B(4, 14) ?\", o:[\"13\",\"17\",\"169\",\"7\"], a:0, e:\"Piège : la racine carrée. d = √{5^{2} + 12^{2}} = √{25 + 144} = √{169} = 13.\"},\n{p:\"Quelle est l'équation de la droite de pente −2 passant par (2, 3) ?\", o:[\"y = −2x + 7\",\"y = −2x + 3\",\"y = −2x − 1\",\"y = −2x + 1\"], a:0, e:\"Piège : b n'est pas l'ordonnée du point. 3 = −2(2) + b donne b = 7.\"},\n{p:\"Quelle est la pente de la droite d'équation 3x − 4y + 8 = 0 ?\", o:[\"[[3|4]]\",\"−[[3|4]]\",\"3\",\"−[[4|3]]\"], a:0, e:\"Piège : le signe en forme générale. On isole y : 4y = 3x + 8, donc y = [[3|4]]x + 2. (La formule −[[A|B]] donne −[[3|−4]] = [[3|4]].)\"},\n{p:\"Résoudre −2y &gt; 6.\", o:[\"y &lt; −3\",\"y &gt; −3\",\"y &lt; 3\",\"y &gt; 3\"], a:0, e:\"Piège : diviser par un négatif. On divise par −2 et on retourne le sens : y &lt; −3.\"},\n{p:\"Pour l'inéquation 2x + y ≤ 4, laquelle de ces affirmations est vraie ?\", o:[\"(0, 0) est une solution et la frontière est en trait plein\",\"(0, 0) est une solution et la frontière est en pointillé\",\"(0, 0) n'est pas une solution et la frontière est en trait plein\",\"(0, 0) n'est pas une solution et la frontière est en pointillé\"], a:0, e:\"Piège : test et type de trait. 2(0) + 0 = 0 ≤ 4 est vrai, donc l'origine convient. Le symbole ≤ inclut la frontière : trait plein.\"},\n{p:\"Lequel de ces points est une solution de y &gt; x^{2} − 4 ?\", o:[\"(0, 0)\",\"(2, 0)\",\"(3, 5)\",\"(1, −4)\"], a:0, e:\"Piège : points sur la frontière. (0, 0) : 0 &gt; −4 vrai. (2, 0) : 0 &gt; 0 faux. (3, 5) : 5 &gt; 5 faux. (1, −4) : −4 &gt; −3 faux.\"},\n{p:\"Quelle est l'équation de la droite passant par (0, −1) et (3, 5) ?\", o:[\"y = 2x − 1\",\"y = 2x + 1\",\"y = x − 1\",\"y = [[1|2]]x − 1\"], a:0, e:\"Piège : pente et ordonnée à l'origine. m = [[5 − (−1)|3 − 0]] = 2. Le point (0, −1) donne directement b = −1.\"}\n]};\n\nCHP[8] = {\npieges:[\n{t:\"Réduction : multipliez TOUS les termes, des deux côtés du =\",\n faux:\"2 × (3x + y = 5) devient 6x + 2y = 5\",\n vrai:\"2 × (3x + y = 5) devient 6x + 2y = 10\",\n why:\"En multipliant une équation, on la multiplie en entier : chaque terme à gauche ET le nombre à droite.\",\n astuce:\"Entourez l'équation d'une parenthèse invisible : 2 × (tout).\"},\n{t:\"Soustraire deux équations : les signes de la deuxième changent tous\",\n faux:\"(4x + 3y = 10) − (4x + y = 2) donne 4y = 8\",\n vrai:\"(4x + 3y) − (4x + y) = 3y − y = 2y, et 10 − 2 = 8, donc 2y = 8 et y = 4\",\n why:\"Soustraire une équation, c'est soustraire chaque terme. Le « + y » devient « − y ». C'est l'erreur de signe la plus fréquente.\",\n astuce:\"Pour éviter les signes, multipliez l'une des équations par −1 et additionnez.\"},\n{t:\"Substitution : mettez des parenthèses\",\n faux:\"y = 2x − 3 dans 3x − 2y = 4 donne 3x − 2 · 2x − 3 = 4\",\n vrai:\"3x − 2(2x − 3) = 4, donc 3x − 4x + 6 = 4, donc x = 2\",\n why:\"On remplace y par l'expression ENTIÈRE. Sans parenthèses, le −2 ne multiplie que le premier terme.\",\n astuce:\"Écrivez toujours « ( ) » à la place de la variable remplacée, puis écrivez l'expression dedans.\"},\n{t:\"0 = 5 et 0 = 0 ne sont pas des erreurs\",\n faux:\"On obtient 0 = 9 : j'ai fait une erreur de calcul\",\n vrai:\"0 = 9 (faux) : aucune solution, droites parallèles distinctes. 0 = 0 (toujours vrai) : infinité de solutions, droites confondues\",\n why:\"Quand les variables disparaissent, c'est la nature du système qui se révèle. Les deux droites ont la même pente : soit elles ne se rencontrent jamais, soit elles se superposent.\",\n astuce:\"Comparez les pentes : même pente et même ordonnée à l'origine = confondues. Même pente, ordonnée différente = parallèles.\"},\n{t:\"Vérifiez dans les DEUX équations\",\n faux:\"(2, 1) vérifie x + 2y = 4, donc c'est la solution du système\",\n vrai:\"3(2) − 1 = 5 ≠ 6 : (2, 1) ne vérifie pas la deuxième équation, ce n'est pas la solution\",\n why:\"Un point sur la première droite n'est pas forcément sur la deuxième. La solution doit être sur les deux.\",\n astuce:\"Prenez 20 secondes à la fin de chaque système pour substituer dans les deux équations.\"},\n{t:\"Droite et parabole : donnez les points, pas seulement les x\",\n faux:\"Les solutions sont x = −1 et x = 3\",\n vrai:\"Les solutions sont les points (−1, −3) et (3, 5)\",\n why:\"Une solution de système est un COUPLE. Après avoir trouvé les x, on remplace dans la plus simple des équations pour trouver les y.\",\n astuce:\"Nombre de solutions = nombre de points d'intersection : 2 (discriminant &gt; 0), 1 (= 0), 0 (&lt; 0).\"},\n{t:\"Mise en équation : définissez vos inconnues\",\n faux:\"x + y = 25 et 12x + 7y = 235 sans dire qui est x et qui est y\",\n vrai:\"Soit x = nombre d'adultes et y = nombre d'enfants\",\n why:\"Sans définition, on ne sait plus quelle réponse est laquelle, et on risque de répondre à la mauvaise question.\",\n astuce:\"Écrivez « soit x = … » en toutes lettres, et relisez la question à la fin pour répondre avec la bonne inconnue.\"}\n],\nq:[\n{p:\"Résoudre le système 2x + 3y = 12 et x − y = 1.\", o:[\"(3, 2)\",\"(2, 3)\",\"(4, 3)\",\"(3, −2)\"], a:0, e:\"Piège : substituer avec des parenthèses. x = y + 1 : 2(y + 1) + 3y = 12, donc 5y = 10 et y = 2, puis x = 3.\"},\n{p:\"Quelle est la solution du système 3x + 2y = 16 et 5x − 2y = 8 ?\", o:[\"(3 ; 3,5)\",\"(3 ; 2,5)\",\"(2 ; 5)\",\"(8 ; −4)\"], a:0, e:\"Piège : vérifier les deux équations. On additionne : 8x = 24, donc x = 3. Puis 9 + 2y = 16 donne y = 3,5. (2 ; 5) vérifie la première équation mais pas la deuxième : 10 − 10 = 0 ≠ 8.\"},\n{p:\"Pour résoudre 4x + 3y = 10 et 4x + y = 2, on soustrait la 2e équation de la 1re. Quelle est alors la valeur de y ?\", o:[\"4\",\"3\",\"12\",\"−4\"], a:0, e:\"Piège : le signe. (4x + 3y) − (4x + y) = 2y et 10 − 2 = 8. Donc y = 4 (et x = −0,5).\"},\n{p:\"Combien de solutions possède le système 2x + y = 4 et 4x + 2y = 9 ?\", o:[\"Aucune\",\"Une seule\",\"Une infinité\",\"Deux\"], a:0, e:\"Piège : ne pas s'arrêter à 0 = 1. En multipliant la première par 2 : 4x + 2y = 8. Or 4x + 2y = 9 : contradiction. Droites parallèles distinctes.\"},\n{p:\"Combien de solutions possède le système 3x − 6y = 9 et x − 2y = 3 ?\", o:[\"Une infinité\",\"Aucune\",\"Une seule\",\"Deux\"], a:0, e:\"Piège : 0 = 0 est une bonne nouvelle. La première équation est 3 fois la deuxième : les droites sont confondues.\"},\n{p:\"Quelles sont les solutions du système y = x^{2} − 4 et y = 2x − 1 ?\", o:[\"(−1, −3) et (3, 5)\",\"−1 et 3\",\"(1, −3) et (−3, 5)\",\"(3, 5) seulement\"], a:0, e:\"Piège : donner un couple. x^{2} − 4 = 2x − 1 donne x^{2} − 2x − 3 = 0, soit (x − 3)(x + 1) = 0. Avec y = 2x − 1 : (3, 5) et (−1, −3).\"},\n{p:\"Combien de points communs ont la parabole y = x^{2} + 1 et la droite y = 2x − 3 ?\", o:[\"Aucun\",\"Un\",\"Deux\",\"On ne peut pas le savoir\"], a:0, e:\"Piège : le discriminant. x^{2} + 1 = 2x − 3 donne x^{2} − 2x + 4 = 0 : Δ = 4 − 16 = −12 &lt; 0. Aucune intersection.\"},\n{p:\"Un cinéma vend 25 billets pour 235 $ : adultes à 12 $ et enfants à 7 $. Combien d'adultes ?\", o:[\"12\",\"13\",\"60\",\"19\"], a:0, e:\"Piège : répondre à la bonne inconnue. a + e = 25 et 12a + 7e = 235. 12a + 7(25 − a) = 235 donne 5a = 60 et a = 12 adultes (13 enfants).\"},\n{p:\"Le couple (2, 1) est-il la solution du système x + 2y = 4 et 3x − y = 6 ?\", o:[\"Non : il vérifie la première équation mais pas la deuxième\",\"Oui : il vérifie la première équation\",\"Oui : 2 + 2 = 4 suffit\",\"Non : les nombres sont trop petits\"], a:0, e:\"Piège : vérifier les deux. 2 + 2(1) = 4 est vrai, mais 3(2) − 1 = 5 ≠ 6.\"},\n{p:\"Résoudre y = 2x − 3 et 3x − 2y = 4 : quelle est la valeur de x ?\", o:[\"2\",\"−10\",\"10\",\"−2\"], a:0, e:\"Piège : les parenthèses. 3x − 2(2x − 3) = 4 donne 3x − 4x + 6 = 4, donc −x = −2 et x = 2. (Sans parenthèses on obtient −10.)\"}\n]};\n\nCHP[9] = {\npieges:[\n{t:\"Corrélation ne veut pas dire causalité\",\n faux:\"Les ventes de crème glacée et les noyades augmentent ensemble : la crème glacée cause les noyades\",\n vrai:\"Une variable cachée explique les deux : la chaleur de l'été\",\n why:\"Deux choses qui varient ensemble ne sont pas forcément liées par une cause. Un troisième facteur (variable cachée) peut agir sur les deux.\",\n astuce:\"Demandez-vous toujours : « Y a-t-il un troisième facteur qui pourrait expliquer les deux ? »\"},\n{t:\"Le signe de r dit le sens, |r| dit la force\",\n faux:\"r = −0,9 est « plus faible » que r = 0,6 parce qu'il est négatif\",\n vrai:\"|−0,9| = 0,9 &gt; 0,6 : la corrélation de −0,9 est PLUS forte (et négative)\",\n why:\"Le signe moins indique seulement que y diminue quand x augmente. La force se lit sur la valeur absolue.\",\n astuce:\"Cachez le signe et comparez les nombres : plus proche de 1, plus fort.\"},\n{t:\"r proche de 0 ne veut pas dire « aucun lien »\",\n faux:\"r ≈ 0, donc il n'y a aucun lien entre les deux variables\",\n vrai:\"r ≈ 0 signifie qu'il n'y a pas de lien LINÉAIRE. Un nuage en forme de U peut avoir r ≈ 0 avec un lien très net\",\n why:\"Le coefficient de corrélation linéaire ne mesure que l'alignement des points. Il passe à côté d'une courbe.\",\n astuce:\"Regardez toujours le nuage de points avant de conclure. Il ne ment pas.\"},\n{t:\"Interpolation oui, extrapolation prudence\",\n faux:\"La droite a été construite avec x entre 2 et 10, donc elle prédit bien x = 40\",\n vrai:\"À x = 7, c'est fiable (interpolation). À x = 40, c'est très risqué (extrapolation)\",\n why:\"On ignore si la tendance continue en dehors des données. Les relations linéaires s'arrêtent souvent : une note ne dépasse pas 100.\",\n astuce:\"Avant de prédire, comparez x à l'étendue des données.\"},\n{t:\"Lire la pente et l'ordonnée à l'origine EN CONTEXTE\",\n faux:\"y = 1,5x + 20 : « la pente est 1,5 » (c'est tout)\",\n vrai:\"Chaque heure d'étude de plus fait augmenter la note prévue d'environ 1,5 point. Pour x = 0 heure, la note prévue est 20\",\n why:\"Une pente a une unité (« points par heure »). L'ordonnée à l'origine est la valeur prévue quand x = 0. Les deux n'ont de sens qu'avec les mots de l'énoncé.\",\n astuce:\"Complétez la phrase : « Quand [x] augmente de 1 [unité], [y] augmente de … [unité]. »\"},\n{t:\"La droite de régression passe par le point moyen\",\n faux:\"On trace une droite au hasard « au milieu » du nuage\",\n vrai:\"La droite passe par le point moyen, dont les coordonnées sont la moyenne des x et la moyenne des y\",\n why:\"La méthode des moindres carrés fait passer la droite exactement par le point moyen. Si on connaît la pente, ce point donne tout de suite l'équation.\",\n astuce:\"Avec un point moyen (4, 10) et pente 2 : y − 10 = 2(x − 4), donc y = 2x + 2.\"},\n{t:\"Une valeur aberrante peut tout changer\",\n faux:\"Un point très éloigné n'a presque aucun effet\",\n vrai:\"Un seul point isolé peut faire chuter |r| et déplacer toute la droite de régression\",\n why:\"Les calculs de r et de la droite reposent sur tous les points : un point très éloigné « tire » la droite vers lui.\",\n astuce:\"Repérez les points éloignés sur le nuage, et posez-vous la question : erreur de mesure ou vraie donnée ?\"}\n],\nq:[\n{p:\"Laquelle de ces corrélations est la plus forte ?\", o:[\"r = −0,85\",\"r = 0,6\",\"r = 0,3\",\"r = −0,1\"], a:0, e:\"Piège : le signe. On compare |r| : 0,85 &gt; 0,6 &gt; 0,3 &gt; 0,1. La plus forte est −0,85 (négative, mais forte).\"},\n{p:\"Les ventes de crème glacée et le nombre de noyades ont une corrélation r = 0,9 durant l'été. Quelle conclusion est valide ?\", o:[\"Les deux dépendent probablement d'un troisième facteur : la chaleur\",\"La crème glacée cause les noyades\",\"Les noyades font vendre de la crème glacée\",\"r = 0,9 est impossible\"], a:0, e:\"Piège : corrélation et causalité. Une forte corrélation ne prouve pas une cause. Une variable cachée (chaleur, nombre de baigneurs) explique les deux.\"},\n{p:\"Un nuage de points forme un U presque parfait (parabole) et on trouve r ≈ 0. Que peut-on conclure ?\", o:[\"Il n'y a pas de lien linéaire, mais il peut y avoir un lien non linéaire\",\"Il n'y a aucun lien entre les deux variables\",\"Le lien linéaire est très fort\",\"Les calculs sont certainement faux\"], a:0, e:\"Piège : r ne mesure que le lien linéaire. Une parabole est un lien net, mais pas aligné : r ≈ 0.\"},\n{p:\"La droite de régression y = 1,5x + 20 donne la note y selon le nombre d'heures d'étude x. Que signifie la pente 1,5 ?\", o:[\"Chaque heure d'étude de plus fait augmenter la note prévue d'environ 1,5 point\",\"La note est de 1,5 point quand x = 1\",\"Il faut étudier 1,5 heure pour réussir\",\"À 20 heures d'étude, la note est de 1,5\"], a:0, e:\"Piège : interpréter en contexte. La pente est la variation de y quand x augmente de 1 : ici, +1,5 point par heure.\"},\n{p:\"Avec y = 1,5x + 20, que représente le nombre 20 ?\", o:[\"La note prévue pour 0 heure d'étude\",\"La note maximale possible\",\"Le nombre d'heures d'étude nécessaire\",\"La pente de la droite\"], a:0, e:\"Piège : l'ordonnée à l'origine. Pour x = 0, y = 20. C'est la valeur prévue sans aucune heure d'étude.\"},\n{p:\"Avec y = 1,5x + 20, quelle est la note prévue pour 6 heures d'étude ?\", o:[\"29\",\"21,5\",\"90\",\"26\"], a:0, e:\"Piège : substitution. y = 1,5(6) + 20 = 9 + 20 = 29.\"},\n{p:\"La droite y = 1,5x + 20 a été construite avec des valeurs de x comprises entre 2 et 10. Quelle prévision est la plus fiable ?\", o:[\"La note pour x = 7\",\"La note pour x = 40\",\"La note pour x = 100\",\"La note pour x = −30\"], a:0, e:\"Piège : extrapolation. x = 7 est dans l'étendue des données (interpolation). Les autres valeurs sont très loin : on ne sait pas si la tendance se maintient.\"},\n{p:\"Une droite de régression a une pente de 2 et passe par le point moyen (4, 10). Quelle est son équation ?\", o:[\"y = 2x + 2\",\"y = 2x + 10\",\"y = 2x + 4\",\"y = 2x − 2\"], a:0, e:\"Piège : utiliser le point moyen. 10 = 2(4) + b donne b = 2.\"},\n{p:\"Les points (1, 2), (2, 4), (3, 6) et (4, 8) sont parfaitement alignés et montent. Que vaut r ?\", o:[\"1\",\"2\",\"0\",\"−1\"], a:0, e:\"Piège : r n'est pas la pente. Pour des points exactement alignés en montée, r = 1. La pente (2) est une autre information, et r ne peut pas dépasser 1.\"},\n{p:\"On ajoute un point très éloigné du nuage de points. Quel est l'effet le plus probable ?\", o:[\"|r| diminue et la droite de régression se déplace\",\"Aucun effet\",\"r devient toujours égal à 1\",\"La droite devient verticale\"], a:0, e:\"Piège : sous-estimer les valeurs aberrantes. Un point isolé tire la droite vers lui et brouille l'alignement : |r| baisse en général.\"}\n]};\n\nwindow.PROB = [\n/* ---------- Chapitre 1 ---------- */\n{id:\"p1a\", ch:[1], type:\"I\", titre:\"Le terrain rectangulaire\",\n enonce:\"<p>L'aire d'un terrain rectangulaire est donnée par A(x) = 2x^{2} + x − 3 (en m^{2}). Sa largeur mesure (x − 1) m.</p><p><b>a)</b> Trouvez une expression de la longueur.<br><b>b)</b> Si x = 6, quel est le périmètre du terrain ?</p>\",\n indices:[\"Aire = longueur × largeur : la longueur est le quotient A(x) ÷ (x − 1).\",\"Divisez 2x^{2} + x − 3 par x − 1 (division de polynômes ou factorisation).\"],\n sol:[\"<b>a)</b> On divise : (2x^{2} + x − 3) ÷ (x − 1). Premier terme du quotient : 2x. On retranche 2x(x − 1) = 2x^{2} − 2x : reste 3x − 3. Terme suivant : 3, on retranche 3(x − 1) = 3x − 3 : reste 0.\",\"La longueur est donc (2x + 3) m. Vérification : (x − 1)(2x + 3) = 2x^{2} + 3x − 2x − 3 = 2x^{2} + x − 3.\",\"<b>b)</b> Pour x = 6 : largeur = 6 − 1 = 5 m et longueur = 2(6) + 3 = 15 m.\",\"Périmètre = 2(15 + 5) = 40 m.\"],\n rep:\"a) Longueur : (2x + 3) m. b) Périmètre : 40 m.\",\n crit:[\"J'ai posé la bonne opération (aire ÷ largeur)\",\"Mon quotient est correct (2x + 3)\",\"J'ai remplacé x par 6 pour la largeur ET la longueur\",\"Ma réponse finale a l'unité (m)\"]},\n{id:\"p1b\", ch:[1], type:\"II\", titre:\"Karim a-t-il raison ?\",\n enonce:\"<p>Karim affirme que (x + 3)^{2} = x^{2} + 9 pour toutes les valeurs de x.</p><p>A-t-il raison ? Justifiez en utilisant un contre-exemple, puis en développant.</p>\",\n indices:[\"Un seul exemple où l'égalité est fausse suffit à invalider l'affirmation.\",\"Choisissez une valeur simple, comme x = 1.\"],\n sol:[\"<b>Contre-exemple (x = 1).</b> Côté gauche : (1 + 3)^{2} = 16. Côté droit : 1^{2} + 9 = 10. Comme 16 ≠ 10, l'égalité est fausse pour x = 1.\",\"<b>Développement.</b> (x + 3)^{2} = (x + 3)(x + 3) = x^{2} + 3x + 3x + 9 = x^{2} + 6x + 9.\",\"L'écart avec x^{2} + 9 est 6x : l'égalité n'est vraie que si 6x = 0, soit x = 0.\",\"Conclusion : Karim a tort. Il a oublié le double produit 2 · x · 3 = 6x.\"],\n rep:\"Non : (x + 3)^{2} = x^{2} + 6x + 9. L'égalité n'est vraie que pour x = 0.\",\n crit:[\"J'ai conclu clairement (Karim a tort)\",\"J'ai donné un contre-exemple avec les deux côtés calculés\",\"J'ai développé correctement (x + 3)^{2}\",\"J'ai identifié l'erreur (le double produit 6x)\"]},\n/* ---------- Chapitre 2 ---------- */\n{id:\"p2a\", ch:[2], type:\"I\", titre:\"La terrasse\",\n enonce:\"<p>L'aire d'une terrasse rectangulaire est x^{2} + 7x + 12 (en m^{2}) et sa largeur est (x + 3) m.</p><p><b>a)</b> Factorisez l'aire et trouvez la longueur.<br><b>b)</b> Le périmètre de la terrasse est 22 m. Quelles sont ses dimensions ?</p>\",\n indices:[\"Cherchez deux nombres de produit 12 et de somme 7.\",\"Écrivez le périmètre en fonction de x, puis posez l'équation = 22.\"],\n sol:[\"<b>a)</b> Produit 12 et somme 7 : 3 et 4. Donc x^{2} + 7x + 12 = (x + 3)(x + 4). La largeur est (x + 3) m, donc la longueur est (x + 4) m.\",\"<b>b)</b> Périmètre = 2[(x + 4) + (x + 3)] = 2(2x + 7) = 4x + 14.\",\"4x + 14 = 22 donne 4x = 8, donc x = 2.\",\"Dimensions : largeur 2 + 3 = 5 m et longueur 2 + 4 = 6 m. Vérification : 5 × 6 = 30 et 2^{2} + 7(2) + 12 = 30.\"],\n rep:\"a) Longueur (x + 4) m. b) x = 2 : la terrasse mesure 6 m sur 5 m.\",\n crit:[\"J'ai factorisé x^{2} + 7x + 12 correctement\",\"J'ai écrit le périmètre en fonction de x\",\"J'ai résolu l'équation et trouvé x = 2\",\"J'ai donné les dimensions (pas seulement x)\"]},\n{id:\"p2b\", ch:[2], type:\"II\", titre:\"Un carré parfait caché\",\n enonce:\"<p>Montrez que, pour tout nombre entier n, le produit de n par l'entier suivant, augmenté de l'entier suivant, est un carré parfait : n(n + 1) + (n + 1).</p><p>Utilisez ce résultat pour calculer rapidement 7 × 8 + 8.</p>\",\n indices:[\"Mettez (n + 1) en évidence.\",\"Un carré parfait s'écrit (quelque chose)^{2}.\"],\n sol:[\"<b>Démonstration.</b> n(n + 1) + (n + 1) = (n + 1)(n + 1) en sortant le facteur commun (n + 1) = (n + 1)^{2}.\",\"C'est le carré de l'entier n + 1 : c'est donc un carré parfait.\",\"<b>Application.</b> Avec n = 7 : 7 × 8 + 8 = (7 + 1)^{2} = 8^{2} = 64. Vérification : 56 + 8 = 64.\"],\n rep:\"n(n + 1) + (n + 1) = (n + 1)^{2}. Donc 7 × 8 + 8 = 64.\",\n crit:[\"J'ai mis le facteur commun (n + 1) en évidence\",\"J'ai écrit le résultat sous la forme (n + 1)^{2}\",\"J'ai conclu que c'est un carré parfait\",\"J'ai appliqué la formule avec n = 7 (= 64)\"]},\n/* ---------- Chapitre 3 ---------- */\n{id:\"p3a\", ch:[3], type:\"I\", titre:\"Le tarif du stationnement\",\n enonce:\"<p>Un stationnement facture 2 $ d'entrée plus 3 $ par heure <b>complète</b>. Le coût, en dollars, pour une durée de t heures est C(t) = 2 + 3[t], où [t] est la partie entière de t.</p><p><b>a)</b> Combien paie-t-on pour 2 h 45 min ?<br><b>b)</b> Combien pour 5,5 heures ?<br><b>c)</b> Pour quelles durées paie-t-on exactement 14 $ ?</p>\",\n indices:[\"2 h 45 min = 2,75 h.\",\"Pour c), résolvez 2 + 3[t] = 14, puis trouvez les t pour lesquels [t] prend cette valeur.\"],\n sol:[\"<b>a)</b> 2 h 45 min = 2,75 h et [2,75] = 2. C(2,75) = 2 + 3(2) = 8 $.\",\"<b>b)</b> [5,5] = 5. C(5,5) = 2 + 3(5) = 17 $.\",\"<b>c)</b> 2 + 3[t] = 14 donne [t] = 4. La partie entière vaut 4 sur l'intervalle [4, 5[.\",\"On paie 14 $ pour toute durée de 4 h (incluse) jusqu'à 5 h (exclue).\"],\n rep:\"a) 8 $. b) 17 $. c) Pour 4 ≤ t &lt; 5.\",\n crit:[\"J'ai converti 2 h 45 min en 2,75 h\",\"J'ai pris la partie entière (pas l'arrondi) dans a) et b)\",\"J'ai résolu [t] = 4 en c)\",\"J'ai écrit l'intervalle [4, 5[ avec les bonnes bornes\"]},\n{id:\"p3b\", ch:[3], type:\"II\", titre:\"L'image de la racine\",\n enonce:\"<p>Sarah affirme que la fonction g(x) = −2√{x + 3} + 1 a pour image [1, +∞[.</p><p>A-t-elle raison ? Déterminez le domaine et l'image de g et justifiez avec un point de la courbe.</p>\",\n indices:[\"√{x + 3} est toujours supérieur ou égal à 0.\",\"Multipliez par −2 : que devient le sens de l'inégalité ?\"],\n sol:[\"<b>Domaine.</b> Il faut x + 3 ≥ 0, donc x ≥ −3 : dom g = [−3, +∞[.\",\"<b>Image.</b> √{x + 3} ≥ 0, donc −2√{x + 3} ≤ 0 (on multiplie par un nombre négatif), puis −2√{x + 3} + 1 ≤ 1. L'image est ]−∞, 1].\",\"<b>Justification.</b> Pour x = 1 : g(1) = −2√{4} + 1 = −3. Cette valeur est dans ]−∞, 1] mais pas dans [1, +∞[.\",\"Sarah a tort : le sommet (−3, 1) est un maximum, et la courbe descend à partir de là.\"],\n rep:\"Non. dom g = [−3, +∞[ et im g = ]−∞, 1]. Contre-exemple : g(1) = −3.\",\n crit:[\"J'ai trouvé le domaine [−3, +∞[\",\"J'ai tenu compte du signe de a (−2 retourne l'inégalité)\",\"J'ai trouvé l'image ]−∞, 1]\",\"J'ai donné un point de la courbe qui contredit Sarah\"]},\n/* ---------- Chapitre 4 ---------- */\n{id:\"p4a\", ch:[4], type:\"I\", titre:\"Le lancer du ballon\",\n enonce:\"<p>Un ballon est lancé depuis une hauteur de 2 m. Sa hauteur (en mètres) après t secondes est h(t) = −5t^{2} + 20t + 2.</p><p><b>a)</b> Quelle est la hauteur maximale et à quel moment est-elle atteinte ?<br><b>b)</b> Après combien de secondes le ballon touche-t-il le sol (au centième près) ?<br><b>c)</b> Pendant combien de temps le ballon est-il à plus de 17 m ?</p>\",\n indices:[\"Le sommet répond à « quand » (h) et à « combien » (k).\",\"Pour b), résolvez h(t) = 0 avec la formule quadratique.\",\"Pour c), résolvez h(t) ≥ 17 : ramenez à 0.\"],\n sol:[\"<b>a)</b> t du sommet = −[[20|2(−5)]] = 2 s. Hauteur : h(2) = −20 + 40 + 2 = 22 m. Maximum de 22 m après 2 s.\",\"<b>b)</b> −5t^{2} + 20t + 2 = 0 : t = [[−20 ± √{400 + 40}|−10]] = [[−20 ± √{440}|−10]]. La solution positive est t = [[20 + √{440}|10]] ≈ 4,10 s. (L'autre solution, ≈ −0,10, est rejetée : le temps est positif.)\",\"<b>c)</b> −5t^{2} + 20t + 2 ≥ 17 donne −5t^{2} + 20t − 15 ≥ 0, soit t^{2} − 4t + 3 ≤ 0 (on divise par −5 et on retourne le sens).\",\"t^{2} − 4t + 3 = (t − 1)(t − 3) : zéros 1 et 3. Parabole vers le haut, ≤ 0 entre les zéros : 1 ≤ t ≤ 3. Durée : 3 − 1 = 2 s.\"],\n rep:\"a) 22 m après 2 s. b) ≈ 4,10 s. c) 2 secondes (de t = 1 à t = 3).\",\n crit:[\"a) J'ai trouvé le moment (2 s) ET la hauteur (22 m)\",\"b) J'ai utilisé la formule et rejeté la solution négative\",\"c) J'ai retourné l'inégalité en divisant par −5\",\"c) J'ai répondu à la question posée (la durée : 2 s)\"]},\n{id:\"p4b\", ch:[4], type:\"I\", titre:\"Le profit d'une entreprise\",\n enonce:\"<p>Le profit (en dollars) d'une entreprise qui vend x articles est P(x) = −2x^{2} + 120x − 1000.</p><p><b>a)</b> Combien d'articles faut-il vendre pour maximiser le profit, et quel est ce profit ?<br><b>b)</b> Entre quelles quantités l'entreprise fait-elle un profit positif ?</p>\",\n indices:[\"Cherchez le sommet de la parabole.\",\"Un profit positif signifie P(x) &gt; 0 : cherchez les zéros.\"],\n sol:[\"<b>a)</b> x du sommet = −[[120|2(−2)]] = 30 articles. P(30) = −2(900) + 3600 − 1000 = 800 $.\",\"<b>b)</b> P(x) = 0 : −2x^{2} + 120x − 1000 = 0, donc x^{2} − 60x + 500 = 0, soit (x − 10)(x − 50) = 0. Zéros : 10 et 50.\",\"La parabole s'ouvre vers le bas : P(x) &gt; 0 entre les zéros. Le profit est positif pour 10 &lt; x &lt; 50 articles.\"],\n rep:\"a) 30 articles, profit de 800 $. b) Profit positif pour 10 &lt; x &lt; 50.\",\n crit:[\"J'ai trouvé x = 30 (le « quand »)\",\"J'ai calculé P(30) = 800 $ (le « combien »)\",\"J'ai trouvé les zéros 10 et 50 en factorisant\",\"J'ai choisi le bon intervalle (entre les zéros, bornes exclues)\"]},\n/* ---------- Chapitre 5 ---------- */\n{id:\"p5a\", ch:[5], type:\"I\", titre:\"L'arbre et la maquette\",\n enonce:\"<p><b>a)</b> Au même moment, un piquet de 1,5 m projette une ombre de 2 m et un arbre projette une ombre de 12 m. Quelle est la hauteur de l'arbre ?</p><p><b>b)</b> La façade d'une maquette à l'échelle 1 : 50 a une aire de 0,8 m^{2}. Quelle est l'aire de la façade réelle ?</p>\",\n indices:[\"Les deux triangles (piquet + ombre, arbre + ombre) sont semblables.\",\"Les aires sont multipliées par k^{2}.\"],\n sol:[\"<b>a)</b> Triangles semblables (mêmes angles, car le soleil est au même angle). [[hauteur de l'arbre|1,5]] = [[12|2]], donc hauteur = [[12 × 1,5|2]] = 9 m.\",\"<b>b)</b> Rapport de similitude k = 50. Les aires sont multipliées par k^{2} = 2 500 : 0,8 × 2 500 = 2 000 m^{2}.\"],\n rep:\"a) 9 m. b) 2 000 m^{2}.\",\n crit:[\"J'ai justifié la similitude des triangles\",\"J'ai écrit la proportion avec les bons côtés homologues\",\"J'ai multiplié l'aire par k^{2} (pas par k)\",\"Mes réponses ont les unités (m, m^{2})\"]},\n{id:\"p5b\", ch:[5], type:\"II\", titre:\"Doubler les côtés, doubler l'aire ?\",\n enonce:\"<p>Un élève affirme : « Si je double les côtés d'un triangle, son aire double aussi. »</p><p>Invalidez cette affirmation avec le triangle rectangle de côtés 3, 4 et 5, puis expliquez ce qui se passe en général.</p>\",\n indices:[\"Calculez l'aire du triangle 3-4-5, puis celle du triangle 6-8-10.\",\"Quel est le rapport de similitude ? Par quoi les aires sont-elles multipliées ?\"],\n sol:[\"Triangle 3-4-5 (rectangle, cathètes 3 et 4) : aire = [[3 × 4|2]] = 6.\",\"Triangle 6-8-10 (côtés doublés) : aire = [[6 × 8|2]] = 24.\",\"Le rapport 24 ÷ 6 = 4 : l'aire est multipliée par 4, pas par 2. L'affirmation est fausse (contre-exemple).\",\"<b>En général.</b> Les deux triangles sont semblables avec k = 2. Les longueurs sont multipliées par k, mais les aires par k^{2} = 4.\"],\n rep:\"Non : l'aire passe de 6 à 24 (× 4 = 2^{2}). Les aires sont multipliées par k^{2}.\",\n crit:[\"J'ai calculé l'aire du triangle initial (6)\",\"J'ai calculé l'aire du triangle doublé (24)\",\"J'ai conclu que l'affirmation est fausse (× 4)\",\"J'ai expliqué avec k^{2}\"]},\n/* ---------- Chapitre 6 ---------- */\n{id:\"p6a\", ch:[6], type:\"I\", titre:\"Le drone et les deux bateaux\",\n enonce:\"<p>Un drone vole à 60 m au-dessus de l'eau. Il observe deux bateaux alignés avec lui, du même côté. Les angles de dépression sont de 25° pour le premier bateau et de 40° pour le second.</p><p>Quelle distance sépare les deux bateaux (au dixième de mètre près) ?</p>\",\n indices:[\"Faites un schéma : deux triangles rectangles qui partagent la verticale du drone.\",\"L'angle de dépression est égal à l'angle à la base du triangle (angles alternes-internes). Dans chaque triangle : tan = 60 ÷ distance.\"],\n sol:[\"Distance horizontale au premier bateau : tan 25° = [[60|d_{1}]], donc d_{1} = [[60|tan 25°]] ≈ 128,67 m.\",\"Distance horizontale au second bateau : tan 40° = [[60|d_{2}]], donc d_{2} = [[60|tan 40°]] ≈ 71,51 m.\",\"Les bateaux sont alignés du même côté : distance entre eux = d_{1} − d_{2} ≈ 128,67 − 71,51 ≈ 57,2 m.\",\"On garde les décimales jusqu'à la fin pour ne pas arrondir trop tôt.\"],\n rep:\"Environ 57,2 m.\",\n crit:[\"J'ai fait un schéma avec les deux triangles rectangles\",\"J'ai utilisé tan (opposé = 60, adjacent = distance)\",\"Ma calculatrice était en mode degrés\",\"J'ai soustrait d_{1} − d_{2} et arrondi seulement à la fin\"]},\n{id:\"p6b\", ch:[6], type:\"I\", titre:\"Deux routes qui se séparent\",\n enonce:\"<p>Deux routes partent d'un même point en formant un angle de 70°. Un camion roule 12 km sur la première route et une voiture roule 9 km sur la seconde.</p><p><b>a)</b> Quelle distance les sépare (au dixième de km près) ?<br><b>b)</b> Quelle est l'aire du triangle formé par le point de départ et les deux véhicules ?</p>\",\n indices:[\"On connaît deux côtés et l'angle compris : quelle loi utiliser ?\",\"Aire = [[1|2]] · a · b · sin C.\"],\n sol:[\"<b>a)</b> Loi des cosinus : d^{2} = 12^{2} + 9^{2} − 2(12)(9) cos 70° = 144 + 81 − 216 cos 70° ≈ 225 − 73,88 = 151,12.\",\"d = √{151,12} ≈ 12,3 km.\",\"<b>b)</b> Aire = [[1|2]] · 12 · 9 · sin 70° = 54 sin 70° ≈ 50,7 km^{2}.\"],\n rep:\"a) ≈ 12,3 km. b) ≈ 50,7 km^{2}.\",\n crit:[\"J'ai choisi la loi des cosinus (2 côtés et l'angle compris)\",\"J'ai calculé d^{2} puis pris la racine carrée\",\"J'ai utilisé ½ · 12 · 9 · sin 70° pour l'aire\",\"Mes réponses ont les unités (km, km^{2})\"]},\n/* ---------- Chapitre 7 ---------- */\n{id:\"p7a\", ch:[7], type:\"II\", titre:\"Un triangle rectangle isocèle ?\",\n enonce:\"<p>Soit les points A(1, 1), B(5, 3) et C(3, −3).</p><p>Démontrez que le triangle ABC est rectangle et isocèle, puis calculez son aire.</p>\",\n indices:[\"Calculez les pentes de AB et de AC : leur produit vaut-il −1 ?\",\"Calculez les longueurs AB, AC et BC avec la formule de distance.\"],\n sol:[\"<b>Pentes.</b> m_{AB} = [[3 − 1|5 − 1]] = [[1|2]] et m_{AC} = [[−3 − 1|3 − 1]] = −2. Produit : [[1|2]] × (−2) = −1. AB ⟂ AC : l'angle en A est droit.\",\"<b>Longueurs.</b> AB = √{4^{2} + 2^{2}} = √{20} et AC = √{2^{2} + (−4)^{2}} = √{20}. Donc AB = AC : le triangle est isocèle.\",\"(Vérification : BC = √{(−2)^{2} + (−6)^{2}} = √{40} et 20 + 20 = 40, conforme à Pythagore.)\",\"<b>Aire</b> = [[AB × AC|2]] = [[20|2]] = 10 unités carrées.\"],\n rep:\"ABC est rectangle en A (pentes de produit −1) et isocèle (AB = AC = √{20}). Aire = 10 u^{2}.\",\n crit:[\"J'ai calculé les deux pentes sans me tromper de signe\",\"J'ai montré que leur produit vaut −1\",\"J'ai calculé AB et AC avec la formule de distance\",\"J'ai calculé l'aire avec les cathètes (10)\"]},\n{id:\"p7b\", ch:[7], type:\"I\", titre:\"Le budget du traiteur\",\n enonce:\"<p>Un traiteur prépare x repas au poulet (8 $ chacun) et y repas végétariens (6 $ chacun). Son budget est d'au plus 240 $ et il doit préparer au moins 10 repas au total.</p><p><b>a)</b> Écrivez les inéquations qui décrivent la situation.<br><b>b)</b> Le couple (15, 10) est-il une solution ?<br><b>c)</b> S'il prépare 12 repas au poulet, combien de repas végétariens peut-il préparer au maximum ?</p>\",\n indices:[\"Coût : 8x + 6y. Nombre de repas : x + y.\",\"Testez le couple en remplaçant x et y dans chaque inéquation.\"],\n sol:[\"<b>a)</b> Budget : 8x + 6y ≤ 240. Nombre minimal de repas : x + y ≥ 10. Et x ≥ 0, y ≥ 0.\",\"<b>b)</b> Pour (15, 10) : 8(15) + 6(10) = 180 ≤ 240 (vrai) et 15 + 10 = 25 ≥ 10 (vrai). Oui, c'est une solution.\",\"<b>c)</b> Avec x = 12 : 96 + 6y ≤ 240, donc 6y ≤ 144 et y ≤ 24. Il peut préparer au maximum 24 repas végétariens (et 12 + 24 = 36 ≥ 10, la condition est respectée).\"],\n rep:\"a) 8x + 6y ≤ 240, x + y ≥ 10, x ≥ 0, y ≥ 0. b) Oui. c) 24 repas végétariens.\",\n crit:[\"J'ai écrit les deux inéquations avec les bons symboles\",\"J'ai ajouté x ≥ 0 et y ≥ 0\",\"J'ai testé le couple dans LES DEUX inéquations\",\"J'ai trouvé y ≤ 24 et vérifié l'autre condition\"]},\n/* ---------- Chapitre 8 ---------- */\n{id:\"p8a\", ch:[8], type:\"I\", titre:\"Deux forfaits cellulaires\",\n enonce:\"<p>Le forfait A coûte 20 $ par mois plus 0,10 $ la minute. Le forfait B coûte 35 $ par mois plus 0,05 $ la minute.</p><p><b>a)</b> Pour combien de minutes les deux forfaits coûtent-ils le même prix ? Quel est ce prix ?<br><b>b)</b> Quel forfait choisir pour 400 minutes par mois ?</p>\",\n indices:[\"Définissez : m = minutes, C = coût mensuel. Écrivez une équation par forfait.\",\"Posez C_{A} = C_{B}.\"],\n sol:[\"Soit m le nombre de minutes. Forfait A : C = 20 + 0,10m. Forfait B : C = 35 + 0,05m.\",\"<b>a)</b> 20 + 0,10m = 35 + 0,05m donne 0,05m = 15, soit m = 300. Prix : 20 + 0,10(300) = 50 $. Vérification avec B : 35 + 0,05(300) = 50 $.\",\"<b>b)</b> Pour 400 min : A coûte 20 + 40 = 60 $ et B coûte 35 + 20 = 55 $. Le forfait B est moins cher.\"],\n rep:\"a) 300 minutes, 50 $. b) Le forfait B (55 $ contre 60 $).\",\n crit:[\"J'ai défini mes variables (m et C)\",\"J'ai écrit les deux équations correctement\",\"J'ai trouvé m = 300 et vérifié dans les deux équations\",\"J'ai comparé les deux prix pour 400 minutes\"]},\n{id:\"p8b\", ch:[8,7], type:\"I\", titre:\"Le tunnel et le câble\",\n enonce:\"<p>Dans un repère (unités en mètres), un tunnel a la forme de la parabole y = −0,5x^{2} + 8 et un câble droit suit la droite y = −x + 4.</p><p>Trouvez les points où le câble touche le tunnel, puis calculez la distance entre ces deux points (au centième près).</p>\",\n indices:[\"Égalez les deux expressions de y.\",\"Après avoir trouvé les x, remplacez-les pour trouver les y.\"],\n sol:[\"−0,5x^{2} + 8 = −x + 4 donne −0,5x^{2} + x + 4 = 0. On multiplie par −2 : x^{2} − 2x − 8 = 0, soit (x − 4)(x + 2) = 0. Donc x = 4 ou x = −2.\",\"Avec y = −x + 4 : pour x = 4, y = 0 ; pour x = −2, y = 6. Points : (4, 0) et (−2, 6).\",\"Distance : d = √{(4 − (−2))^{2} + (0 − 6)^{2}} = √{36 + 36} = √{72} ≈ 8,49 m.\"],\n rep:\"Points (4, 0) et (−2, 6). Distance ≈ 8,49 m.\",\n crit:[\"J'ai égalé les deux équations\",\"J'ai factorisé x^{2} − 2x − 8 et trouvé x = 4 et x = −2\",\"J'ai donné les points complets (x ET y)\",\"J'ai utilisé la formule de distance avec la racine carrée\"]},\n/* ---------- Chapitre 9 ---------- */\n{id:\"p9a\", ch:[9], type:\"I\", titre:\"Étudier et réussir\",\n enonce:\"<p>Cinq élèves ont étudié x heures et obtenu la note y :</p><p>(1 ; 52) · (2 ; 58) · (3 ; 61) · (4 ; 70) · (5 ; 74)</p><p><b>a)</b> Avec votre calculatrice, trouvez le coefficient de corrélation r et l'équation de la droite de régression.<br><b>b)</b> Interprétez la pente.<br><b>c)</b> Quelle note prévoit-on pour 6 heures ? Cette prévision est-elle fiable ?</p>\",\n indices:[\"Entrez les données dans le mode statistique à deux variables de la calculatrice.\",\"Pour c), regardez si x = 6 est dans l'étendue des données.\"],\n sol:[\"<b>a)</b> r ≈ 0,99 (corrélation positive très forte). Droite de régression : y ≈ 5,6x + 46,2.\",\"<b>b)</b> Pente 5,6 : chaque heure d'étude de plus fait augmenter la note prévue d'environ 5,6 points.\",\"<b>c)</b> y = 5,6(6) + 46,2 = 79,8, soit environ 80.\",\"Mais les données vont de x = 1 à x = 5 : x = 6 est en dehors (extrapolation). La prévision est moins fiable, car on ne sait pas si la tendance continue.\"],\n rep:\"a) r ≈ 0,99 ; y ≈ 5,6x + 46,2. b) +5,6 points par heure. c) ≈ 80, mais extrapolation (peu fiable).\",\n crit:[\"J'ai trouvé r ≈ 0,99 et la bonne équation\",\"J'ai interprété la pente avec des unités (points par heure)\",\"J'ai calculé la note prévue pour x = 6\",\"J'ai signalé que x = 6 est une extrapolation\"]},\n{id:\"p9b\", ch:[9], type:\"II\", titre:\"Les pompiers causent-ils les dégâts ?\",\n enonce:\"<p>Un journal affirme : « Dans les villes, plus il y a de pompiers sur un incendie, plus les dégâts sont importants (r = 0,85). Donc envoyer des pompiers aggrave les dégâts. »</p><p>Cette conclusion est-elle valide ? Justifiez.</p>\",\n indices:[\"Une forte corrélation prouve-t-elle une cause ?\",\"Y a-t-il un troisième facteur qui influence à la fois le nombre de pompiers et les dégâts ?\"],\n sol:[\"r = 0,85 indique une corrélation positive forte : les deux variables varient ensemble. Mais corrélation ne signifie pas causalité.\",\"Une <b>variable cachée</b> explique les deux : la gravité (la taille) de l'incendie. Un gros incendie demande beaucoup de pompiers ET cause beaucoup de dégâts.\",\"Conclusion : la conclusion du journal n'est pas valide. Les pompiers ne causent pas les dégâts. Pour juger de leur effet, il faudrait comparer des incendies de gravité semblable.\"],\n rep:\"Non : corrélation n'est pas causalité. La gravité de l'incendie est une variable cachée qui explique les deux.\",\n crit:[\"J'ai conclu que la conclusion n'est pas valide\",\"J'ai rappelé que corrélation ≠ causalité\",\"J'ai nommé une variable cachée (gravité de l'incendie)\",\"J'ai expliqué le lien avec les deux variables\"]},\n/* ---------- Situations mixtes ---------- */\n{id:\"pm1\", ch:[4,8], type:\"I\", titre:\"Revenus, coûts et profit\",\n enonce:\"<p>Une entreprise vend x articles. Son revenu est R(x) = −x^{2} + 80x et son coût de production est C(x) = 20x + 300 (en dollars).</p><p><b>a)</b> Écrivez la fonction profit P(x) = R(x) − C(x).<br><b>b)</b> Quel nombre d'articles maximise le profit ? Quel est ce profit ?<br><b>c)</b> À partir de combien d'articles (entiers) l'entreprise fait-elle un profit positif ?</p>\",\n indices:[\"Soustrayez avec soin : le signe moins s'applique à tous les termes de C(x).\",\"Cherchez le sommet, puis les zéros de P(x) avec la formule quadratique.\"],\n sol:[\"<b>a)</b> P(x) = (−x^{2} + 80x) − (20x + 300) = −x^{2} + 60x − 300.\",\"<b>b)</b> x du sommet = −[[60|2(−1)]] = 30. P(30) = −900 + 1 800 − 300 = 600 $. Maximum : 600 $ pour 30 articles.\",\"<b>c)</b> P(x) = 0 : x^{2} − 60x + 300 = 0, soit x = [[60 ± √{3 600 − 1 200}|2]] = 30 ± √{600} ≈ 30 ± 24,49. Zéros ≈ 5,51 et 54,49.\",\"P(x) &gt; 0 entre les zéros. Le premier entier dans cet intervalle est 6 : le profit devient positif à partir de 6 articles (et le reste jusqu'à 54).\"],\n rep:\"a) P(x) = −x^{2} + 60x − 300. b) 30 articles, 600 $. c) À partir de 6 articles (jusqu'à 54).\",\n crit:[\"J'ai distribué le signe moins à tout C(x)\",\"J'ai trouvé le sommet (30 ; 600)\",\"J'ai résolu P(x) = 0 avec la formule\",\"J'ai choisi le premier ENTIER de l'intervalle (6)\"]},\n{id:\"pm2\", ch:[6,5], type:\"I\", titre:\"Le mât sur l'édifice\",\n enonce:\"<p>Un mât est fixé au sommet d'un édifice. À 40 m de la base de l'édifice, on observe le bas du mât sous un angle d'élévation de 35° et le haut du mât sous un angle de 42°.</p><p>Quelle est la hauteur du mât (au dixième de mètre près) ?</p>\",\n indices:[\"Faites un schéma : deux triangles rectangles ayant le même côté adjacent (40 m).\",\"Hauteur du mât = (hauteur jusqu'au haut) − (hauteur jusqu'au bas).\"],\n sol:[\"Hauteur jusqu'au bas du mât : tan 35° = [[h_{1}|40]], donc h_{1} = 40 tan 35° ≈ 28,01 m.\",\"Hauteur jusqu'au haut du mât : tan 42° = [[h_{2}|40]], donc h_{2} = 40 tan 42° ≈ 36,02 m.\",\"Hauteur du mât = h_{2} − h_{1} ≈ 36,02 − 28,01 ≈ 8,0 m.\",\"(Astuce : 40(tan 42° − tan 35°) ≈ 8,01 m. On évite d'arrondir avant la soustraction.)\"],\n rep:\"Environ 8,0 m.\",\n crit:[\"J'ai fait un schéma avec deux triangles rectangles\",\"J'ai utilisé tan avec l'adjacent 40 m\",\"Ma calculatrice était en mode degrés\",\"J'ai soustrait les deux hauteurs et arrondi à la fin\"]},\n{id:\"pm3\", ch:[1,2], type:\"II\", titre:\"La différence de deux carrés\",\n enonce:\"<p>Démontrez que, pour tous nombres a et b, (a + b)^{2} − (a − b)^{2} = 4ab.</p><p>Servez-vous ensuite de la différence de carrés pour calculer mentalement 53^{2} − 47^{2}.</p>\",\n indices:[\"Développez chaque carré séparément, puis soustrayez : attention au signe moins devant la 2e parenthèse.\",\"Pour 53^{2} − 47^{2}, utilisez a^{2} − b^{2} = (a − b)(a + b).\"],\n sol:[\"<b>Démonstration.</b> (a + b)^{2} = a^{2} + 2ab + b^{2} et (a − b)^{2} = a^{2} − 2ab + b^{2}.\",\"Différence : (a^{2} + 2ab + b^{2}) − (a^{2} − 2ab + b^{2}) = a^{2} + 2ab + b^{2} − a^{2} + 2ab − b^{2} = 4ab.\",\"<b>Calcul mental.</b> 53^{2} − 47^{2} = (53 − 47)(53 + 47) = 6 × 100 = 600.\",\"Avec la première formule : a = 50 et b = 3 donnent aussi 4 · 50 · 3 = 600. Les deux méthodes concordent.\"],\n rep:\"(a + b)^{2} − (a − b)^{2} = 4ab. Et 53^{2} − 47^{2} = 600.\",\n crit:[\"J'ai développé les deux carrés correctement\",\"J'ai changé tous les signes de la 2e parenthèse\",\"J'ai obtenu 4ab\",\"J'ai calculé 53^{2} − 47^{2} = 600 par factorisation\"]},\n{id:\"pm4\", ch:[6,5], type:\"II\", titre:\"Sinus : loi et rapport\",\n enonce:\"<p>Dans un triangle ABC rectangle en C, montrez que la loi des sinus [[a|sin A]] = [[c|sin C]] redonne la définition sin A = [[côté opposé|hypoténuse]].</p>\",\n indices:[\"Quelle est la valeur de sin 90° ?\",\"Dans ce triangle, quel côté est opposé à A ? Quel côté est l'hypoténuse ?\"],\n sol:[\"Dans le triangle rectangle en C : le côté a est opposé à l'angle A, et le côté c (opposé à l'angle droit C) est l'hypoténuse.\",\"La loi des sinus donne [[a|sin A]] = [[c|sin C]]. Comme C = 90°, sin C = 1, donc [[a|sin A]] = c.\",\"On isole : sin A = [[a|c]] = [[côté opposé|hypoténuse]]. C'est exactement la définition du sinus dans un triangle rectangle : la loi des sinus généralise ce rapport à tous les triangles.\"],\n rep:\"Avec C = 90° : sin C = 1, donc [[a|sin A]] = c et sin A = [[a|c]] = opposé ÷ hypoténuse.\",\n crit:[\"J'ai identifié a (opposé à A) et c (hypoténuse)\",\"J'ai utilisé sin 90° = 1\",\"J'ai isolé sin A = a ÷ c\",\"J'ai conclu que c'est la définition du sinus\"]}\n];\n\n(function(){\nvar CH = window.CH;\nCH.forEach(function(c){\n  var P=(window.CHP||{})[c.id]||{};\n  c.pieges=P.pieges||[]; c.q2=P.q||[];\n  c.q.forEach(function(q){ q.ch = c.id; });\n  c.q2.forEach(function(q){ q.ch = c.id; q.piege = true; });\n});\nvar app = document.getElementById('app');\nfunction qid(q){ var t=q.p+'|'+q.o[0], h=5381; for(var i=0;i<t.length;i++){ h=((h<<5)+h+t.charCodeAt(i))|0; } return 'q'+(h>>>0).toString(36); }\nvar QI={};\nCH.forEach(function(c){ c.q.concat(c.q2).forEach(function(q){ q.id=qid(q); QI[q.id]=q; }); });\n\n/* ---------- utilitaires ---------- */\nfunction fmt(s){\n  return String(s)\n    .replace(/\\^\\{([^{}]*)\\}/g,'<sup>$1</sup>')\n    .replace(/_\\{([^{}]*)\\}/g,'<sub>$1</sub>')\n    .replace(/√\\{([^{}]*)\\}/g,'<span class=\"rad\">√<span class=\"rc\">$1</span></span>')\n    .replace(/\\[\\[(.+?)\\|(.+?)\\]\\]/g,'<span class=\"fr\"><span>$1</span><span>$2</span></span>');\n}\nfunction shuffle(a){ a=a.slice(); for(var i=a.length-1;i>0;i--){var j=Math.floor(Math.random()*(i+1));var t=a[i];a[i]=a[j];a[j]=t;} return a; }\nfunction nf(n){ return String(+n.toFixed(2)).replace('.',','); }\nfunction chap(id){ return CH.filter(function(c){return c.id===id;})[0]; }\nfunction mention(p){ return p>=90?'Excellent':p>=80?'Très bien':p>=70?'Bien':p>=60?'Passable':'À retravailler'; }\nfunction mmss(s){ s=Math.max(0,Math.round(s)); return Math.floor(s/60)+':'+('0'+(s%60)).slice(-2); }\nvar LET=['A','B','C','D','E'];\n\nvar PR=window.PROB||[];\nfunction prob(id){ return PR.filter(function(p){return p.id===id;})[0]; }\nvar KEY='sn4-v1', S={quiz:{},quiz2:{},miss:{},prob:{},hist:[]};\ntry{ var raw=localStorage.getItem(KEY); if(raw){ var o=JSON.parse(raw); S.quiz=o.quiz||{}; S.quiz2=o.quiz2||{}; S.miss=o.miss||{}; S.prob=o.prob||{}; S.hist=o.hist||[]; } }catch(e){}\nfunction save(){ try{ localStorage.setItem(KEY,JSON.stringify(S)); }catch(e){} }\n\n/* ---------- routeur ---------- */\nvar cur=null, tick=null;\nfunction stopTimer(){ if(tick){ clearInterval(tick); tick=null; } }\nfunction setNav(k){\n  var links=document.querySelectorAll('#nav a');\n  for(var i=0;i<links.length;i++){ if(links[i].getAttribute('data-k')===k) links[i].setAttribute('aria-current','page'); else links[i].removeAttribute('aria-current'); }\n}\nfunction missCount(){ return Object.keys(S.miss).filter(function(k){return QI[k];}).length; }\nfunction updateBadge(){\n  var a=document.querySelector('#nav a[data-k=\"erreurs\"]'); if(!a) return;\n  var n=missCount(); a.innerHTML='Mes erreurs'+(n?' <span class=\"badge\">'+n+'</span>':'');\n}\nfunction route(){\n  updateBadge();\n  var h=(location.hash||'#accueil').slice(1);\n  var m=h.match(/^(cours|pieges|quiz|qpieges)-(\\d+)$/);\n  stopTimer(); cur=null;\n  window.scrollTo(0,0);\n  if(m && chap(+m[2])){ setNav('accueil'); return chapter(+m[2],m[1]); }\n  var mp=h.match(/^problemes(?:-(\\d+))?$/), mq=h.match(/^probleme-(\\w+)$/), mf=h.match(/^fiche-(\\d+)$/);\n  if(mp){ setNav('problemes'); return problemList(mp[1]?+mp[1]:0); }\n  if(mq && prob(mq[1])){ setNav('problemes'); return problemPage(mq[1]); }\n  if(mf && chap(+mf[1])){ setNav('accueil'); return fiche(+mf[1]); }\n  if(h==='erreurs'){ setNav('erreurs'); return errors(); }\n  if(h==='pieges'){ setNav('pieges'); return allTraps(); }\n  if(h==='tests'){ setNav('tests'); return builder('test'); }\n  if(h==='examens'){ setNav('examens'); return builder('exam'); }\n  setNav('accueil'); home();\n}\nwindow.addEventListener('hashchange',route);\n\n/* ---------- accueil ---------- */\nfunction home(){\n  var done=0, sum=0;\n  CH.forEach(function(c){ var b=S.quiz[c.id]; if(b!=null){ done++; sum+=b; } });\n  var nq=CH.reduce(function(n,c){return n+c.q.length+c.q2.length;},0), np=CH.reduce(function(n,c){return n+c.pieges.length;},0);\n  var html='<section class=\"intro\"><p class=\"eyebrow\">Mathématique · Sciences naturelles · 4e secondaire</p>'+\n   '<h1>Atelier <mark>Maths</mark> SN4</h1>'+\n   '<p class=\"lead\">Un cours résumé par chapitre, les pièges où tout le monde tombe (et comment les éviter), des quiz corrigés pas à pas, puis des tests et des examens chronométrés.</p>'+\n   '<div class=\"summary\"><span><b>'+CH.length+'</b>chapitres</span><span><b>'+nq+'</b>questions</span><span><b>'+np+'</b>pièges expliqués</span><span><b>'+done+'/'+CH.length+'</b>quiz faits</span>'+\n   (done?'<span><b>'+Math.round(sum/done)+' %</b>moyenne des meilleurs quiz</span>':'')+'</div></section>';\n  html+='<h2 style=\"margin-bottom:.8rem\">Les chapitres</h2><ul class=\"list\">';\n  CH.forEach(function(c){\n    var b=S.quiz[c.id];\n    html+='<li class=\"row\"><span class=\"num\">'+c.id+'</span><div><h3>'+fmt(c.titre)+'</h3><p>'+fmt(c.resume)+'</p>'+\n      '<div class=\"bar\" aria-hidden=\"true\"><i style=\"width:'+(b||0)+'%\"></i></div>'+\n      '<div class=\"best\">'+(b!=null?'Meilleur quiz : '+b+' %':'Quiz pas encore tenté')+(S.quiz2[c.id]!=null?' · quiz pièges : '+S.quiz2[c.id]+' %':'')+'</div></div>'+\n      '<div class=\"acts\"><a class=\"btn-s\" href=\"#cours-'+c.id+'\">Cours</a><a class=\"btn-s\" href=\"#pieges-'+c.id+'\">Pièges</a><a class=\"btn\" href=\"#quiz-'+c.id+'\">Quiz</a></div></li>';\n  });\n  var TOP=[[1,0],[5,0],[6,1],[2,4],[9,0]];\n  var np2=PR.length, nd=PR.filter(function(p){return S.prob[p.id]!=null;}).length;\n  var nm=missCount();\n  html+='</ul><div class=\"panel\" style=\"margin-bottom:1rem\"><h2>Problèmes de situation d\\'application</h2><p class=\"muted\">Comme à l\\'examen : un énoncé, une démarche à rédiger, puis la solution pas à pas et une auto-évaluation. <b>'+(nd)+'/'+(np2)+'</b> problèmes faits.</p><a class=\"btn\" href=\"#problemes\">Résoudre un problème</a></div><div class=\"panel\" style=\"margin-bottom:1rem\"><h2>Mes erreurs</h2><p class=\"muted\">'+(nm?'<b>'+nm+'</b> question'+(nm>1?'s':'')+' à revoir. Chaque question ratée est gardée ici et reproposée jusqu\\'à ce qu\\'elle soit réussie deux fois.':'Les questions ratées seront gardées ici pour être reproposées jusqu\\'à ce qu\\'elles soient maîtrisées.')+'</p><a class=\"btn'+(nm?'':'-s')+'\" href=\"#erreurs\">'+(nm?'Réviser mes erreurs':'Voir mes erreurs')+'</a></div><div class=\"panel\" style=\"margin-bottom:1rem\"><h2>Les pièges où tout le monde tombe</h2><p class=\"muted\">Cinq erreurs très fréquentes. Chacune est expliquée avec un test pour ne plus la refaire.</p><ul class=\"toplist\">'+\n    TOP.map(function(p){ var g=chap(p[0]).pieges[p[1]]; return '<li><a href=\"#pieges-'+p[0]+'\"><b>'+fmt(g.t)+'</b><span>Chapitre '+p[0]+'</span></a></li>'; }).join('')+\n    '</ul><a class=\"btn\" href=\"#pieges\">Voir tous les pièges</a></div><div class=\"two\"><div class=\"panel\"><h2>Tests</h2><p class=\"muted\">Choisissez les chapitres à réviser et le nombre de questions. Corrigé détaillé à la fin.</p><a class=\"btn\" href=\"#tests\">Composer un test</a></div>'+\n   '<div class=\"panel\"><h2>Examens</h2><p class=\"muted\">Conditions réelles : chronomètre, pas de correction avant la fin, bilan par chapitre.</p><a class=\"btn\" href=\"#examens\">Passer un examen</a></div></div>';\n  html+='<div class=\"panel\"><h2>Derniers résultats</h2>';\n  if(S.hist.length){\n    html+='<ul class=\"hist\">'+S.hist.slice(0,8).map(function(r){\n      return '<li><span>'+r.titre+'</span><span><b>'+r.pct+' %</b> · '+r.date+'</span></li>';}).join('')+'</ul>';\n  } else html+='<p class=\"muted\" style=\"margin:0\">Aucun résultat pour l\\'instant. Les scores sont gardés dans ce navigateur.</p>';\n  html+='</div>';\n  app.innerHTML=html;\n}\n\n/* ---------- chapitre ---------- */\nfunction chapter(id,tab){\n  var c=chap(id);\n  var prev=chap(id-1), next=chap(id+1);\n  var html='<div class=\"crumb\"><a href=\"#accueil\">← Tous les chapitres</a><span>'+\n    (prev?'<a href=\"#'+tab+'-'+prev.id+'\">Chapitre '+prev.id+'</a>':'')+(prev&&next?' · ':'')+(next?'<a href=\"#'+tab+'-'+next.id+'\">Chapitre '+next.id+' →</a>':'')+'</span></div>'+\n    '<p class=\"eyebrow\">Chapitre '+id+'</p><h1 style=\"font-size:clamp(1.7rem,5vw,2.5rem)\">'+fmt(c.titre)+'</h1>'+\n    '<div class=\"tabs\"><a href=\"#cours-'+id+'\"'+(tab==='cours'?' aria-current=\"page\"':'')+'>Cours</a><a href=\"#pieges-'+id+'\"'+(tab==='pieges'?' aria-current=\"page\"':'')+'>Pièges ('+c.pieges.length+')</a><a href=\"#quiz-'+id+'\"'+(tab==='quiz'?' aria-current=\"page\"':'')+'>Quiz</a><a href=\"#qpieges-'+id+'\"'+(tab==='qpieges'?' aria-current=\"page\"':'')+'>Quiz pièges</a></div><div id=\"pane\"></div>';\n  app.innerHTML=html;\n  var pane=document.getElementById('pane');\n  if(tab==='cours'){\n    var h='';\n    c.cours.forEach(function(s){ h+='<article class=\"sec\"><h2>'+fmt(s.h)+'</h2>'+fmt(s.html)+'</article>'; });\n    if(c.explorer) h+='<article class=\"sec\"><h2>Explorateur de parabole</h2><div id=\"xp\"></div></article>';\n    h+='<div class=\"cta\"><a class=\"btn\" href=\"#pieges-'+id+'\">Voir les pièges du chapitre</a><a class=\"btn-s\" href=\"#quiz-'+id+'\">Passer au quiz</a><a class=\"btn-s\" href=\"#problemes-'+id+'\">Problèmes</a><a class=\"btn-s\" href=\"#fiche-'+id+'\">Fiche imprimable</a><a class=\"btn-s\" href=\"#accueil\">Retour</a></div>';\n    pane.innerHTML=h;\n    if(c.explorer) explorer(document.getElementById('xp'));\n  } else if(tab==='pieges'){\n    pane.innerHTML='<p class=\"lead\" style=\"max-width:62ch\">Ces erreurs reviennent dans la majorité des copies. Pour chacune : ce qu\\'on écrit trop souvent, la bonne version, pourquoi on se trompe et un truc pour ne plus tomber dedans.</p>'+\n      c.pieges.map(trapCard).join('')+\n      '<div class=\"cta\"><a class=\"btn\" href=\"#qpieges-'+id+'\">S\\'entraîner : quiz pièges</a><a class=\"btn-s\" href=\"#cours-'+id+'\">Retour au cours</a></div>';\n  } else if(tab==='qpieges'){\n    var b2=S.quiz2[id];\n    pane.innerHTML='<div class=\"panel\"><h2>Quiz pièges du chapitre</h2><p class=\"muted\">10 questions construites autour des erreurs classiques : chaque mauvaise réponse correspond à une vraie erreur d\\'élève. Correction immédiate, avec le nom du piège.'+(b2!=null?' Votre meilleur résultat : <b>'+b2+' %</b>.':'')+'</p><div class=\"acts\"><button class=\"btn\" id=\"go\">Commencer</button><a class=\"btn-s\" href=\"#pieges-'+id+'\">Relire les pièges</a></div></div>';\n    document.getElementById('go').onclick=function(){\n      start({kind:'quiz2',titre:'Quiz pièges — chapitre '+id,mode:'now',qs:shuffle(c.q2),chap:id,seconds:0});\n    };\n  } else {\n    var b=S.quiz[id];\n    pane.innerHTML='<div class=\"panel\"><h2>Quiz du chapitre</h2><p class=\"muted\">10 questions de base, correction immédiate après chaque réponse. L\\'ordre des choix change à chaque essai.'+(b!=null?' Votre meilleur résultat : <b>'+b+' %</b>.':'')+'</p><button class=\"btn\" id=\"go\">Commencer</button></div>';\n    document.getElementById('go').onclick=function(){\n      start({kind:'quiz',titre:'Quiz — chapitre '+id,mode:'now',qs:shuffle(c.q),chap:id,seconds:0});\n    };\n  }\n}\n\n/* ---------- problèmes ---------- */\nfunction chTags(p){ return p.ch.map(function(i){return 'Ch. '+i;}).join(' + '); }\nfunction problemList(n){\n  var list=PR.filter(function(p){ return !n||p.ch.indexOf(n)>=0; });\n  var h='<p class=\"eyebrow\">Situations d\\'application</p><h1 style=\"font-size:clamp(1.7rem,5vw,2.5rem)\">Problèmes à résoudre</h1>'+\n   '<p class=\"lead\" style=\"max-width:64ch\">Comme dans la section C de l\\'examen : on lit l\\'énoncé, on rédige sa démarche sur papier, puis on compare avec la solution et on s\\'auto-évalue. <b>Type I</b> : enchaîner des opérations. <b>Type II</b> : argumenter, démontrer ou invalider avec un contre-exemple.</p>'+\n   '<div class=\"chips\"><a href=\"#problemes\"'+(n?'':' aria-current=\"page\"')+'>Tous</a>'+CH.map(function(c){ return '<a href=\"#problemes-'+c.id+'\"'+(n===c.id?' aria-current=\"page\"':'')+'>Ch. '+c.id+'</a>'; }).join('')+'</div><ul class=\"list\">';\n  list.forEach(function(p){\n    var b=S.prob[p.id];\n    h+='<li class=\"row\"><span class=\"num\" style=\"font-size:1.1rem\">'+p.type+'</span><div><h3>'+fmt(p.titre)+'</h3><p>'+chTags(p)+' · '+(b!=null?'dernier résultat : '+b+' %':'pas encore fait')+'</p></div><div class=\"acts\"><a class=\"btn'+(b!=null?'-s':'')+'\" href=\"#probleme-'+p.id+'\">'+(b!=null?'Refaire':'Commencer')+'</a></div></li>';\n  });\n  app.innerHTML=h+'</ul>';\n}\nfunction problemPage(id){\n  var p=prob(id), i=PR.indexOf(p), nx=PR[i+1];\n  var h='<div class=\"crumb\"><a href=\"#problemes\">← Tous les problèmes</a>'+(nx?'<a href=\"#probleme-'+nx.id+'\">Problème suivant →</a>':'')+'</div>'+\n    '<p class=\"eyebrow\">Type '+p.type+' · '+chTags(p)+'</p><h1 style=\"font-size:clamp(1.6rem,5vw,2.3rem)\">'+fmt(p.titre)+'</h1>'+\n    '<div class=\"sec\">'+fmt(p.enonce)+'</div>'+\n    '<div class=\"panel\" style=\"margin-bottom:1rem\"><b>Besoin d\\'un coup de pouce ?</b><div id=\"hints\"></div><button class=\"btn-s\" id=\"hb\" style=\"margin-top:.6rem\">Afficher un indice ('+p.indices.length+')</button></div>'+\n    '<div class=\"panel\" style=\"margin-bottom:1rem\"><label for=\"ans\"><b>Ma démarche</b> <span class=\"muted\">(le brouillon n\\'est pas enregistré : écrivez aussi sur papier)</span></label><textarea id=\"ans\" rows=\"7\" placeholder=\"Écrivez vos étapes, vos calculs et votre réponse…\"></textarea><div class=\"cta\" style=\"margin-bottom:0\"><button class=\"btn\" id=\"sb\">Voir la solution</button></div></div><div id=\"solzone\"></div>';\n  app.innerHTML=h;\n  var k=0;\n  document.getElementById('hb').onclick=function(){\n    var d=document.createElement('p'); d.className='hint'; d.innerHTML='<b>Indice '+(k+1)+'.</b> '+fmt(p.indices[k]);\n    document.getElementById('hints').appendChild(d); k++;\n    if(k>=p.indices.length){ this.disabled=true; this.textContent='Plus d\\'indices'; } else this.textContent='Afficher un autre indice ('+(p.indices.length-k)+')';\n  };\n  document.getElementById('sb').onclick=function(){\n    this.disabled=true;\n    var z=document.getElementById('solzone');\n    z.innerHTML='<div class=\"sec\"><h2>Solution</h2><ol class=\"steps\">'+p.sol.map(function(t){return '<li>'+fmt(t)+'</li>';}).join('')+'</ol><p class=\"final\"><b>Réponse :</b> '+fmt(p.rep)+'</p></div>'+\n      '<div class=\"panel\"><h2>Auto-évaluation</h2><p class=\"muted\">Soyez honnête : cochez seulement ce que votre copie contient vraiment.</p>'+\n      p.crit.map(function(c,j){ return '<label class=\"crit\"><input type=\"checkbox\" class=\"cr\" value=\"'+j+'\"> '+fmt(c)+'</label>'; }).join('')+\n      '<div class=\"cta\"><button class=\"btn\" id=\"ev\">Enregistrer mon résultat</button></div><div id=\"evr\"></div></div>';\n    z.scrollIntoView({behavior:'smooth'});\n    document.getElementById('ev').onclick=function(){\n      var n=[].filter.call(document.querySelectorAll('.cr'),function(x){return x.checked;}).length, pct=Math.round(n/p.crit.length*100);\n      S.prob[p.id]=pct; save();\n      var msg=pct>=75?'Très bien : cette démarche est maîtrisée.':pct>=50?'Bon début. Relisez la solution et refaites le problème dans quelques jours.':'À retravailler : relisez le cours et les pièges du chapitre, puis refaites ce problème.';\n      document.getElementById('evr').innerHTML='<p class=\"tip\"><b>'+n+' / '+p.crit.length+' ('+pct+' %).</b> '+msg+'</p><div class=\"cta\">'+(p.ch.map(function(c){ return '<a class=\"btn-s\" href=\"#pieges-'+c+'\">Pièges du chapitre '+c+'</a>'; }).join(''))+(nx?'<a class=\"btn\" href=\"#probleme-'+nx.id+'\">Problème suivant</a>':'')+'</div>';\n    };\n  };\n}\n\n/* ---------- fiche imprimable ---------- */\nfunction fiche(id){\n  var c=chap(id), h='<div class=\"noprint crumb\"><a href=\"#cours-'+id+'\">← Retour au cours</a><button class=\"btn\" id=\"pr\">Imprimer la fiche</button></div>'+\n   '<div class=\"fiche\"><p class=\"eyebrow\">Fiche de révision · Chapitre '+id+'</p><h1 style=\"font-size:1.8rem;margin-bottom:.6rem\">'+fmt(c.titre)+'</h1>';\n  c.cours.forEach(function(s){\n    var parts=[], re=/<div class=\"formula\">[\\s\\S]*?\\n<\\/div>|<ul>[\\s\\S]*?<\\/ul>|<div class=\"ex\">[\\s\\S]*?<\\/div>|<p class=\"tip\">[\\s\\S]*?<\\/p>|<p>[\\s\\S]*?<\\/p>/g, m, np=0, ne=0;\n    while((m=re.exec(s.html))){\n      var t=m[0];\n      if(t.indexOf('<p>')===0){ if(np++) continue; }\n      else if(t.indexOf('<div class=\"ex\">')===0){ if(ne++) continue; }\n      parts.push(t);\n    }\n    h+='<section class=\"fs\"><h2>'+fmt(s.h)+'</h2>'+fmt(parts.join(''))+'</section>';\n  });\n  h+='<section class=\"fs\"><h2>Pièges à éviter</h2><ul class=\"fp\">'+c.pieges.map(function(g){ return '<li><b>'+fmt(g.t)+'</b><br>'+fmt(g.vrai)+'</li>'; }).join('')+'</ul></section></div>';\n  app.innerHTML=h;\n  document.getElementById('pr').onclick=function(){ window.print(); };\n}\n\n/* ---------- mes erreurs ---------- */\nfunction errors(){\n  var ids=Object.keys(S.miss).filter(function(k){return QI[k];}), by={};\n  ids.forEach(function(k){ var c=QI[k].ch; by[c]=(by[c]||0)+1; });\n  var h='<p class=\"eyebrow\">Révision ciblée</p><h1 style=\"font-size:clamp(1.7rem,5vw,2.5rem)\">Mes erreurs</h1>';\n  if(!ids.length){\n    h+='<div class=\"panel\"><p style=\"margin:0\">Aucune erreur en attente pour l\\'instant. Les questions ratées dans les quiz, tests et examens apparaîtront ici. Une question disparaît de la liste quand elle est réussie <b>deux fois</b> en révision.</p></div><div class=\"cta\"><a class=\"btn\" href=\"#accueil\">Aller aux chapitres</a></div>';\n    app.innerHTML=h; return;\n  }\n  h+='<p class=\"lead\" style=\"max-width:62ch\"><b>'+ids.length+'</b> question'+(ids.length>1?'s':'')+' à revoir. Une question quitte la liste quand elle est réussie deux fois de suite en révision.</p>'+\n    '<div class=\"panel\"><h2>Par chapitre</h2><div class=\"bars\">'+CH.filter(function(c){return by[c.id];}).map(function(c){\n      return '<div><span>'+c.id+'. '+fmt(c.titre)+'</span><span class=\"bar\"><i class=\"lo\" style=\"width:'+Math.min(100,by[c.id]*10)+'%\"></i></span><span>'+by[c.id]+'</span></div>'; }).join('')+'</div></div>'+\n    '<div class=\"cta\"><button class=\"btn\" id=\"rv\">Réviser maintenant (jusqu\\'à 10)</button>'+\n    CH.filter(function(c){return by[c.id];}).map(function(c){ return '<button class=\"btn-s rvc\" data-c=\"'+c.id+'\">Chapitre '+c.id+' ('+by[c.id]+')</button>'; }).join('')+'</div>'+\n    '<p class=\"tip\">Astuce : relisez le <a href=\"#pieges\">piège</a> correspondant avant de réviser. On comprend mieux l\\'erreur qu\\'on a nommée.</p>';\n  app.innerHTML=h;\n  function go(list){\n    var qs=shuffle(list.map(function(k){return QI[k];}).sort(function(a,b){return S.miss[b.id].n-S.miss[a.id].n;}).slice(0,10));\n    start({kind:'revision',titre:'Révision de mes erreurs',mode:'now',qs:qs,seconds:0});\n  }\n  document.getElementById('rv').onclick=function(){ go(ids); };\n  [].forEach.call(document.querySelectorAll('.rvc'),function(b){ b.onclick=function(){ var c=+b.getAttribute('data-c'); go(ids.filter(function(k){return QI[k].ch===c;})); }; });\n}\n\n/* ---------- pièges ---------- */\nfunction trapCard(g){\n  return '<article class=\"trap\"><h3>'+fmt(g.t)+'</h3><div class=\"tg\"><div class=\"bad\"><span>À éviter</span>'+fmt(g.faux)+'</div><div class=\"good\"><span>Correct</span>'+fmt(g.vrai)+'</div></div>'+\n    '<p class=\"why\"><b>Pourquoi on se trompe.</b> '+fmt(g.why)+'</p><p class=\"hint\"><b>Truc.</b> '+fmt(g.astuce)+'</p></article>';\n}\nfunction allTraps(){\n  var h='<p class=\"eyebrow\">Bibliothèque d\\'erreurs</p><h1 style=\"font-size:clamp(1.7rem,5vw,2.5rem)\">Tous les pièges</h1><p class=\"lead\" style=\"max-width:62ch\">Les erreurs les plus fréquentes, chapitre par chapitre. À relire avant un test ou un examen.</p><div class=\"chips\">'+\n    CH.map(function(c){ return '<a href=\"#pieges-'+c.id+'\">'+c.id+'. '+fmt(c.titre)+'</a>'; }).join('')+'</div>';\n  CH.forEach(function(c){\n    h+='<h2 style=\"margin:1.6rem 0 .7rem\">Chapitre '+c.id+' · '+fmt(c.titre)+'</h2>'+c.pieges.map(trapCard).join('')+\n      '<div class=\"cta\"><a class=\"btn-s\" href=\"#qpieges-'+c.id+'\">Quiz pièges du chapitre '+c.id+'</a></div>';\n  });\n  app.innerHTML=h;\n}\n\n/* ---------- explorateur de parabole ---------- */\nfunction explorer(el){\n  el.innerHTML='<div class=\"xp\"><div>'+\n   '<p class=\"tip\" style=\"margin-top:0\">Déplacez les curseurs pour voir comment a, h et k changent la parabole f(x) = a(x − h)<sup>2</sup> + k.</p>'+\n   '<label>a<input id=\"pa\" type=\"range\" min=\"-3\" max=\"3\" step=\"0.5\" value=\"1\"><output id=\"oa\">1</output></label>'+\n   '<label>h<input id=\"ph\" type=\"range\" min=\"-6\" max=\"6\" step=\"1\" value=\"2\"><output id=\"oh\">2</output></label>'+\n   '<label>k<input id=\"pk\" type=\"range\" min=\"-6\" max=\"6\" step=\"1\" value=\"-3\"><output id=\"ok\">−3</output></label>'+\n   '<div class=\"readout\" id=\"ro\"></div></div><svg id=\"sv\" viewBox=\"0 0 384 384\" role=\"img\" aria-label=\"Graphique de la parabole\"></svg></div>';\n  var U=24, C=192;\n  function px(x){return C+x*U;} function py(y){return C-y*U;}\n  function draw(){\n    var a=+document.getElementById('pa').value, h=+document.getElementById('ph').value, k=+document.getElementById('pk').value;\n    if(a===0){ a=0.5; document.getElementById('pa').value=0.5; }\n    document.getElementById('oa').textContent=nf(a); document.getElementById('oh').textContent=String(h).replace('-','−'); document.getElementById('ok').textContent=String(k).replace('-','−');\n    var s='<defs><clipPath id=\"cp\"><rect x=\"0\" y=\"0\" width=\"384\" height=\"384\"/></clipPath></defs>';\n    for(var i=-8;i<=8;i++){ s+='<line class=\"gridl\" x1=\"'+px(i)+'\" y1=\"0\" x2=\"'+px(i)+'\" y2=\"384\"/><line class=\"gridl\" x1=\"0\" y1=\"'+py(i)+'\" x2=\"384\" y2=\"'+py(i)+'\"/>'; }\n    s+='<line class=\"axis\" x1=\"0\" y1=\"'+C+'\" x2=\"384\" y2=\"'+C+'\"/><line class=\"axis\" x1=\"'+C+'\" y1=\"0\" x2=\"'+C+'\" y2=\"384\"/>';\n    s+='<text class=\"svgt\" x=\"372\" y=\"'+(C-5)+'\">x</text><text class=\"svgt\" x=\"'+(C+5)+'\" y=\"12\">y</text>';\n    var d='';\n    for(var xx=-8;xx<=8.001;xx+=0.1){ var yy=a*(xx-h)*(xx-h)+k; d+=(d?'L':'M')+px(xx).toFixed(1)+' '+py(yy).toFixed(1); }\n    s+='<g clip-path=\"url(#cp)\"><path class=\"curve\" d=\"'+d+'\"/></g>';\n    s+='<line x1=\"'+px(h)+'\" y1=\"0\" x2=\"'+px(h)+'\" y2=\"384\" stroke=\"var(--accent)\" stroke-dasharray=\"4 4\" stroke-width=\"1\" opacity=\".6\"/>';\n    var disc=-k/a, zs=[];\n    if(disc>0){ zs=[h-Math.sqrt(disc),h+Math.sqrt(disc)]; } else if(Math.abs(disc)<1e-9){ zs=[h]; }\n    zs.forEach(function(z){ s+='<circle class=\"pz\" cx=\"'+px(z)+'\" cy=\"'+C+'\" r=\"4.5\"/>'; });\n    s+='<circle class=\"pt\" cx=\"'+px(h)+'\" cy=\"'+py(k)+'\" r=\"5\"/>';\n    document.getElementById('sv').innerHTML=s;\n    var A=a, B=-2*a*h, Cc=a*h*h+k;\n    function t(n){ return nf(n).replace('-','−'); }\n    document.getElementById('ro').innerHTML=\n      '<div>Sommet : (<b>'+t(h)+'</b>, <b>'+t(k)+'</b>) &nbsp;·&nbsp; axe : x = '+t(h)+'</div>'+\n      '<div>Forme générale : '+(A===1?'':A===-1?'−':t(A))+'x<sup>2</sup> '+(B<0?'−':'+')+' '+nf(Math.abs(B))+'x '+(Cc<0?'−':'+')+' '+nf(Math.abs(Cc))+'</div>'+\n      '<div>Ordonnée à l\\'origine : '+t(Cc)+'</div>'+\n      '<div>Zéros : '+(zs.length===0?'aucun':zs.map(t).join(' et '))+'</div>'+\n      '<div>'+(a>0?'Minimum':'Maximum')+' : '+t(k)+'</div>';\n  }\n  ['pa','ph','pk'].forEach(function(id){ document.getElementById(id).addEventListener('input',draw); });\n  draw();\n}\n\n/* ---------- composition des tests et examens ---------- */\nfunction pool(id,only){ var c=chap(id); return only?c.q2:c.q.concat(c.q2); }\nfunction draw(chapters,n,only){\n  var per={}, base=Math.floor(n/chapters.length), extra=n-base*chapters.length, order=shuffle(chapters);\n  order.forEach(function(id,i){ per[id]=base+(i<extra?1:0); });\n  var out=[];\n  chapters.forEach(function(id){ out=out.concat(shuffle(pool(id,only)).slice(0,Math.min(per[id],pool(id,only).length))); });\n  return shuffle(out);\n}\nfunction builder(kind){\n  if(kind==='test'){\n    var h='<p class=\"eyebrow\">Tests</p><h1 style=\"font-size:clamp(1.7rem,5vw,2.5rem)\">Composer un test</h1><p class=\"muted\">Les questions sont tirées au hasard dans les chapitres choisis.</p>'+\n     '<div class=\"panel form\"><div><b>Chapitres</b><div class=\"chk\" style=\"margin-top:.5rem\">'+\n     CH.map(function(c){ return '<label><input type=\"checkbox\" class=\"cc\" value=\"'+c.id+'\" checked> '+c.id+'. '+fmt(c.titre)+'</label>'; }).join('')+'</div></div>'+\n     '<div class=\"inl\"><label for=\"nq\">Questions&nbsp;<select id=\"nq\"><option>10</option><option selected>15</option><option>20</option><option>30</option><option>45</option></select></label>'+\n     '<label><input type=\"checkbox\" id=\"po\"> Seulement les questions pièges</label>'+\n     '<label><input type=\"checkbox\" id=\"tm\"> Chronomètre&nbsp;<input type=\"number\" id=\"mn\" value=\"30\" min=\"5\" max=\"180\" style=\"width:5.5em\">&nbsp;min</label></div>'+\n     '<div id=\"err\" class=\"warn\" hidden>Choisissez au moins un chapitre.</div>'+\n     '<div><button class=\"btn\" id=\"go\">Lancer le test</button></div></div>';\n    app.innerHTML=h;\n    document.getElementById('go').onclick=function(){\n      var ids=[].slice.call(document.querySelectorAll('.cc')).filter(function(x){return x.checked;}).map(function(x){return +x.value;});\n      if(!ids.length){ document.getElementById('err').hidden=false; return; }\n      var only=document.getElementById('po').checked;\n      var n=Math.min(+document.getElementById('nq').value, ids.length*(only?10:20));\n      var secs=document.getElementById('tm').checked?Math.max(5,+document.getElementById('mn').value||30)*60:0;\n      start({kind:'test',titre:'Test — '+(ids.length===CH.length?'tous les chapitres':'chap. '+ids.join(', ')),mode:'end',qs:draw(ids,n,only),seconds:secs});\n    };\n    return;\n  }\n  var P=[\n   {t:'Examen 1 — chapitres 1 à 3',d:'Manipulation d\\'expressions algébriques, factorisation, étude des fonctions.',ids:[1,2,3],n:18,m:60},\n   {t:'Examen 2 — chapitres 4 à 6',d:'Fonction du second degré, triangles et figures équivalentes, relations trigonométriques.',ids:[4,5,6],n:18,m:60},\n   {t:'Examen 3 — chapitres 7 à 9',d:'Droites et inéquations à deux variables, systèmes d\\'équations, statistique.',ids:[7,8,9],n:18,m:60},\n   {t:'Examen final — tous les chapitres',d:'Toute la matière de l\\'année, 36 questions réparties également.',ids:[1,2,3,4,5,6,7,8,9],n:36,m:120},\n   {t:'Examen pièges — tous les chapitres',d:'27 questions construites autour des erreurs classiques, 3 par chapitre. Pour vérifier que les pièges sont bien évités.',ids:[1,2,3,4,5,6,7,8,9],n:27,m:75,only:true}];\n  var h2='<p class=\"eyebrow\">Examens</p><h1 style=\"font-size:clamp(1.7rem,5vw,2.5rem)\">Passer un examen</h1><p class=\"muted\">Le chronomètre démarre dès le début. La correction n\\'apparaît qu\\'à la fin, ou quand le temps est écoulé.</p><div class=\"presets\" style=\"margin-top:1.2rem\">'+\n   P.map(function(p,i){ return '<div class=\"panel preset\"><div><h2>'+p.t+'</h2><p class=\"muted\" style=\"margin:0\">'+p.d+'</p><p style=\"margin:.4rem 0 0\"><b>'+p.n+' questions · '+p.m+' minutes</b></p></div><button class=\"btn\" data-i=\"'+i+'\">Commencer</button></div>'; }).join('')+'</div>';\n  app.innerHTML=h2;\n  [].forEach.call(document.querySelectorAll('.preset button'),function(b){\n    b.onclick=function(){ var p=P[+b.getAttribute('data-i')]; start({kind:'exam',titre:p.t,mode:'end',qs:draw(p.ids,p.n,p.only),seconds:p.m*60}); };\n  });\n}\n\n/* ---------- moteur de session ---------- */\nfunction start(cfg){\n  stopTimer();\n  cur={cfg:cfg,i:0,t0:Date.now(),over:false,confirm:false,\n    items:cfg.qs.map(function(q){\n      return {q:q,sel:null,opts:shuffle(q.o.map(function(t,i){return {t:t,ok:i===q.a};}))};\n    })};\n  if(cfg.seconds){\n    cur.end=Date.now()+cfg.seconds*1000;\n    tick=setInterval(function(){\n      var left=(cur.end-Date.now())/1000, el=document.getElementById('tm');\n      if(el){ el.textContent=mmss(left); el.className='timer'+(left<300?' low':''); }\n      if(left<=0){ finish(true); }\n    },500);\n  }\n  window.scrollTo(0,0);\n  render();\n}\nfunction answered(){ return cur.items.filter(function(x){return x.sel!=null;}).length; }\nfunction render(){\n  var s=cur, cfg=s.cfg, it=s.items[s.i], n=s.items.length, now=cfg.mode==='now';\n  var h='<div class=\"qhead\"><div><p class=\"eyebrow\" style=\"margin:0\">'+cfg.titre+'</p><b>Question '+(s.i+1)+' / '+n+'</b></div>'+\n    (cfg.seconds?'<div class=\"timer\" id=\"tm\">'+mmss((s.end-Date.now())/1000)+'</div>':'')+'</div>'+\n    '<div class=\"qbar\"><i style=\"width:'+Math.round((now?answered():s.i+1)/n*100)+'%\"></i></div><div class=\"qlayout'+(now?' solo':'')+'\"><div>'+\n    '<div class=\"qcard\"><div class=\"qtag\">'+chap(it.q.ch).id+'. '+fmt(chap(it.q.ch).titre)+'</div><div class=\"qtext\">'+fmt(it.q.p)+'</div><div class=\"opts\">';\n  it.opts.forEach(function(o,i){\n    var c='opt';\n    if(now && it.sel!=null){ if(o.ok) c+=' good'; else if(it.sel===i) c+=' bad'; }\n    else if(it.sel===i) c+=' sel';\n    h+='<button class=\"'+c+'\" data-i=\"'+i+'\"'+(now&&it.sel!=null?' disabled':'')+'><span class=\"l\">'+LET[i]+'</span><span>'+fmt(o.t)+'</span></button>';\n  });\n  h+='</div>';\n  if(now && it.sel!=null){\n    var good=it.opts[it.sel].ok;\n    h+='<div class=\"expl\"><b class=\"'+(good?'g':'r')+'\">'+(good?'Bonne réponse.':'Pas tout à fait.')+'</b> '+fmt(it.q.e)+'</div>';\n  }\n  h+='</div><div class=\"qnav\"><button class=\"btn-s\" id=\"pv\"'+(s.i===0?' disabled':'')+'>← Précédente</button>';\n  var last=s.i===n-1;\n  if(now) h+='<button class=\"btn\" id=\"nx\"'+(it.sel==null?' disabled':'')+'>'+(last?'Voir le résultat':'Suivante →')+'</button>';\n  else h+=last?'<button class=\"btn\" id=\"fin\">Terminer</button>':'<button class=\"btn\" id=\"nx\">Suivante →</button>';\n  h+='</div>';\n  if(!now && s.confirm){\n    var miss=n-answered();\n    h+='<div class=\"warn\">'+(miss?'Il reste '+miss+' question'+(miss>1?'s':'')+' sans réponse. ':'Toutes les questions ont une réponse. ')+'Terminer maintenant ?<div class=\"qnav\" style=\"margin-top:.6rem\"><button class=\"btn\" id=\"yes\">Oui, voir la correction</button><button class=\"btn-s\" id=\"no\">Continuer</button></div></div>';\n  }\n  h+='</div>';\n  if(!now){\n    h+='<aside><b style=\"font-size:.9rem\">Navigation</b><div class=\"navg\" style=\"margin-top:.5rem\">'+\n      s.items.map(function(x,i){ return '<button data-n=\"'+i+'\" class=\"'+(x.sel!=null?'done':'')+(i===s.i?' cur':'')+'\" aria-label=\"Question '+(i+1)+'\">'+(i+1)+'</button>'; }).join('')+'</div>'+\n      '<p class=\"tip\" style=\"margin-top:.8rem\">Vous pouvez revenir à n\\'importe quelle question avant de terminer.</p><button class=\"btn-s\" id=\"fin2\" style=\"margin-top:.4rem\">Terminer</button></aside>';\n  }\n  h+='</div>';\n  app.innerHTML=h;\n  [].forEach.call(app.querySelectorAll('.opt'),function(b){\n    b.onclick=function(){ it.sel=+b.getAttribute('data-i'); s.confirm=false; render(); };\n  });\n  var $=function(id){return document.getElementById(id);};\n  if($('pv')) $('pv').onclick=function(){ s.i--; s.confirm=false; render(); window.scrollTo(0,0); };\n  if($('nx')) $('nx').onclick=function(){ if(last&&now){ finish(false); } else { s.i++; s.confirm=false; render(); window.scrollTo(0,0); } };\n  var ask=function(){ s.confirm=true; render(); };\n  if($('fin')) $('fin').onclick=ask; if($('fin2')) $('fin2').onclick=ask;\n  if($('yes')) $('yes').onclick=function(){ finish(false); };\n  if($('no')) $('no').onclick=function(){ s.confirm=false; render(); };\n  [].forEach.call(app.querySelectorAll('.navg button'),function(b){ b.onclick=function(){ s.i=+b.getAttribute('data-n'); s.confirm=false; render(); }; });\n}\n\n/* ---------- résultats ---------- */\nfunction finish(timeUp){\n  if(!cur||cur.over) return;\n  var s=cur; s.over=true; stopTimer();\n  var cfg=s.cfg, n=s.items.length;\n  var good=s.items.filter(function(x){return x.sel!=null&&x.opts[x.sel].ok;}).length;\n  var pct=Math.round(good/n*100), used=(Date.now()-s.t0)/1000;\n  if(cfg.kind==='quiz'){ if(S.quiz[cfg.chap]==null||pct>S.quiz[cfg.chap]) S.quiz[cfg.chap]=pct; }\n  if(cfg.kind==='quiz2'){ if(S.quiz2[cfg.chap]==null||pct>S.quiz2[cfg.chap]) S.quiz2[cfg.chap]=pct; }\n  var d=new Date(), pad=function(x){return ('0'+x).slice(-2);};\n  S.hist.unshift({titre:cfg.titre,pct:pct,date:pad(d.getDate())+'/'+pad(d.getMonth()+1)}); S.hist=S.hist.slice(0,20);\n  save();\n  s.items.forEach(function(x){\n    if(x.sel==null||!x.q.id) return;\n    var ok=x.opts[x.sel].ok, m=S.miss[x.q.id];\n    if(!ok){ S.miss[x.q.id]={ch:x.q.ch,n:(m?m.n:0)+1,streak:0}; }\n    else if(m){ m.streak=(m.streak||0)+1; if(m.streak>=2) delete S.miss[x.q.id]; }\n  });\n  save(); updateBadge();\n  var by={};\n  s.items.forEach(function(x){ var c=x.q.ch; by[c]=by[c]||{g:0,n:0}; by[c].n++; if(x.sel!=null&&x.opts[x.sel].ok) by[c].g++; });\n  var h='<p class=\"eyebrow\">'+cfg.titre+'</p>'+(timeUp?'<div class=\"warn\" style=\"margin:0 0 1rem\">Le temps est écoulé. Les questions sans réponse comptent comme fausses.</div>':'')+\n   '<div class=\"score\"><span class=\"big\">'+good+' / '+n+'</span><span class=\"big\" style=\"font-size:2rem;color:var(--muted)\">'+pct+' %</span><span class=\"mention\">'+mention(pct)+'</span></div>'+\n   '<p class=\"muted\">Durée : '+mmss(used)+(cfg.seconds?' sur '+mmss(cfg.seconds):'')+'</p>';\n  var ids=Object.keys(by).map(Number).sort(function(a,b){return a-b;});\n  if(ids.length>1){\n    h+='<div class=\"panel\"><h2>Bilan par chapitre</h2><div class=\"bars\">'+ids.map(function(id){\n      var p=Math.round(by[id].g/by[id].n*100);\n      return '<div><span>'+id+'. '+fmt(chap(id).titre)+'</span><span class=\"bar\"><i class=\"'+(p<60?'lo':'')+'\" style=\"width:'+p+'%\"></i></span><span>'+by[id].g+'/'+by[id].n+'</span></div>';}).join('')+'</div>'+\n      (function(){ var weak=ids.filter(function(id){return by[id].g/by[id].n<0.7;}); return weak.length?'<p class=\"tip\" style=\"margin:0\">À retravailler : '+weak.map(function(id){return '<a href=\"#pieges-'+id+'\">chapitre '+id+' (pièges)</a>';}).join(', ')+'.</p>':'<p class=\"tip\" style=\"margin:0\">Tous les chapitres sont au-dessus de 70 %. Excellent travail.</p>'; })()+'</div>';\n  }\n  var wrong=s.items.filter(function(x){return !(x.sel!=null&&x.opts[x.sel].ok);});\n  h+='<div class=\"filters\"><button class=\"btn\" id=\"all\">Voir toute la correction</button>'+(wrong.length?'<button class=\"btn-s\" id=\"wr\">Erreurs seulement ('+wrong.length+')</button><button class=\"btn-s\" id=\"redo\">Refaire les erreurs</button>':'')+''+(cfg.kind==='revision'?'<button class=\"btn-s\" id=\"toerr\">Mes erreurs ('+missCount()+')</button>':'')+'<a class=\"btn-s\" href=\"#accueil\">Accueil</a></div><div id=\"rev\"></div>';\n  app.innerHTML=h; window.scrollTo(0,0);\n  function review(list){\n    document.getElementById('rev').innerHTML='<div class=\"rev\">'+list.map(function(x){\n      var ok=x.sel!=null&&x.opts[x.sel].ok, rightIdx=x.opts.findIndex(function(o){return o.ok;});\n      return '<div class=\"qcard\"><div class=\"qtag\">'+x.q.ch+'. '+fmt(chap(x.q.ch).titre)+' · <span class=\"'+(ok?'res-ok':'res-no')+'\">'+(ok?'Réussie':(x.sel==null?'Sans réponse':'Incorrecte'))+'</span></div>'+\n        '<div class=\"qtext\" style=\"font-size:1.05rem\">'+fmt(x.q.p)+'</div>'+\n        (ok?'':'<p style=\"margin:0 0 .3rem\"><b>Votre réponse :</b> '+(x.sel==null?'—':fmt(x.opts[x.sel].t))+'</p>')+\n        '<p style=\"margin:0 0 .5rem\"><b>Bonne réponse :</b> <span class=\"m\">'+LET[rightIdx]+'. '+fmt(x.opts[rightIdx].t)+'</span></p>'+\n        '<div class=\"expl\" style=\"margin-top:.4rem\">'+fmt(x.q.e)+'</div></div>';}).join('')+'</div>';\n    document.getElementById('rev').scrollIntoView({behavior:'smooth'});\n  }\n  document.getElementById('all').onclick=function(){ review(s.items); };\n  if(document.getElementById('toerr')) document.getElementById('toerr').onclick=function(){ errors(); window.scrollTo(0,0); };\n  if(document.getElementById('wr')) document.getElementById('wr').onclick=function(){ review(wrong); };\n  if(document.getElementById('redo')) document.getElementById('redo').onclick=function(){\n    start({kind:'redo',titre:'Reprise des erreurs',mode:'now',qs:shuffle(wrong.map(function(x){return x.q;})),seconds:0});\n  };\n}\n\nroute();\n})();\n\n</script>\n</body>\n</html>\n";
